	public FightLogEntry(Player attacker, Player defender, PvpDamageCalc pvpDamageCalc, int attackerOffensivePray, CombatLevels levels, AnimationData animationData)
	{
		this(attacker, defender, pvpDamageCalc, attackerOffensivePray, levels, animationData, PLUGIN.getClient().getTickCount(), Instant.now().toEpochMilli());
	}

	public FightLogEntry(Player attacker, Player defender, PvpDamageCalc pvpDamageCalc, int attackerOffensivePray, CombatLevels levels, AnimationData animationData, int tick, long time)
	{
		this(attacker, defender, pvpDamageCalc, attackerOffensivePray, levels, animationData, tick, time, null, null);
	}

	public FightLogEntry(Player attacker, Player defender, PvpDamageCalc pvpDamageCalc, int attackerOffensivePray, CombatLevels levels, AnimationData animationData, int tick, long time, Integer soulreaperStacks, Integer recordedSoulreaperStacksVarp)
	{
		this.isFullEntry = true;

		// general
		this.attackerName = attacker.getName();
		this.time = time;
		this.tick = tick;
		this.hitsplatMatchTick = PLUGIN.getClient().getTickCount();

		this.animationData = animationData;
		this.soulreaperStacks = soulreaperStacks;
		this.recordedSoulreaperStacksVarp = recordedSoulreaperStacksVarp;

		// attacker data
		this.attackerGear = attacker.getPlayerComposition().getEquipmentIds();
		this.attackerOverhead = attacker.getOverheadIcon();

		this.expectedDamage = pvpDamageCalc.getAverageHit();
		this.accuracy = pvpDamageCalc.getAccuracy();
		this.minHit = pvpDamageCalc.getMinHit();
		this.maxHit = pvpDamageCalc.getMaxHit();
		this.damageRollDistribution = pvpDamageCalc.getDamageRollDistribution();
		this.damageRollHitCount = pvpDamageCalc.getDamageRollHitCount();
		this.splash = animationData.attackStyle == AnimationData.AttackStyle.MAGIC && defender.getGraphic() == GraphicID.SPLASH;
		this.attackerLevels = levels; // CAN BE NULL
		this.attackerRingItemId = getLocalPlayerRingItemId(attacker);
		this.attackerAmmoItemId = getLocalPlayerAmmoItemId(attacker);

		// defender data
		this.defenderGear = defender.getPlayerComposition().getEquipmentIds();
		this.defenderOverhead = defender.getOverheadIcon();
		this.attackerOffensivePray = attackerOffensivePray;
		this.expectedHits = PvpUtils.getExpectedHits(animationData);
		this.matchedHitsCount = 0;
		this.actualDamageSum = 0;
	}

	// create incomplete entry to save competitor's defensive stats which are only client side
	// in this context, the "attacker" is not attacking, only defending.
	public FightLogEntry(String attackerName, CombatLevels levels, int attackerOffensivePray)
	{
		this(attackerName, levels, attackerOffensivePray, PLUGIN.getClient().getTickCount(), Instant.now().toEpochMilli());
	}

	public FightLogEntry(String attackerName, CombatLevels levels, int attackerOffensivePray, int tick, long time)
	{
		this.isFullEntry = false;

		this.attackerName = attackerName;
		this.time = time;
		this.tick = tick;
		this.hitsplatMatchTick = PLUGIN.getClient().getTickCount();

		this.attackerLevels = levels;
		this.attackerOffensivePray = attackerOffensivePray;
		this.attackerRingItemId = getLocalPlayerRingItemId(PLUGIN.getClient().getLocalPlayer());
		this.attackerAmmoItemId = getLocalPlayerAmmoItemId(PLUGIN.getClient().getLocalPlayer());
		this.actualDamageSum = 0;
	}

	private boolean isLocalPlayer(Player player)
	{
		if (player == null)
		{
			return false;
		}
		Player localPlayer = PLUGIN.getClient().getLocalPlayer();
		if (localPlayer == null || localPlayer.getName() == null || player.getName() == null)
		{
			return false;
		}

		String localName = localPlayer.getName().replace("\u00a0", " ").replace("_", " ").trim().toUpperCase();
		String playerName = player.getName().replace("\u00a0", " ").replace("_", " ").trim().toUpperCase();

		return localName.equals(playerName);
	}

	private Integer getLocalPlayerRingItemId(Player attacker)
	{
		if (!isLocalPlayer(attacker))
		{
			return null;
		}

		ItemContainer worn = PLUGIN.getClient().getItemContainer(InventoryID.EQUIPMENT);
		if (worn == null)
		{
			return null;
		}

		Item ring = worn.getItem(EquipmentInventorySlot.RING.getSlotIdx());
		if (ring == null || ring.getId() <= 0)
		{
			return null;
		}

		return ring.getId();
	}

	private Integer getLocalPlayerAmmoItemId(Player attacker)
	{
		if (!isLocalPlayer(attacker))
		{
			return null;
		}

		ItemContainer worn = PLUGIN.getClient().getItemContainer(InventoryID.EQUIPMENT);
		if (worn == null)
		{
			return null;
		}

		Item ammo = worn.getItem(EquipmentInventorySlot.AMMO.getSlotIdx());
		if (ammo == null || ammo.getId() <= 0)
		{
			return null;
		}

		return ammo.getId();
	}

	// randomized entry used for testing
	public FightLogEntry(int [] attackerGear, int expectedDamage, double accuracy, int minHit, int maxHit, int [] defenderGear, String attackerName)
	{
		this(attackerGear, expectedDamage, accuracy, minHit, maxHit, defenderGear, attackerName, 0, Instant.now().toEpochMilli());
	}

	// randomized entry used for testing
	public FightLogEntry(int [] attackerGear, int expectedDamage, double accuracy, int minHit, int maxHit, int [] defenderGear, String attackerName, int tick, long time)
	{
		this.attackerName = attackerName;
		this.attackerGear = attackerGear;
		this.attackerOverhead = HeadIcon.MAGIC;
		this.animationData = Math.random() <= 0.5 ? AnimationData.MELEE_DAGGER_SLASH : AnimationData.MAGIC_ANCIENT_MULTI_TARGET;
		this.expectedDamage = expectedDamage;
		this.accuracy = accuracy;
		this.minHit = minHit;
		this.maxHit = maxHit;
		this.splash = Math.random() >= 0.5;
		this.time = time;
		this.tick = tick;
		this.defenderGear = defenderGear;
		this.defenderOverhead = HeadIcon.MAGIC;
		this.actualDamageSum = 0;
	}


	public boolean success()
	{
		return animationData.attackStyle.getProtection() != defenderOverhead;
	}

	public PvpDamageCalc.DamageRollDistribution getDamageRollDistribution()
	{
		return damageRollDistribution != null ? damageRollDistribution : PvpDamageCalc.DamageRollDistribution.STANDARD;
	}

	public int getDamageRollHitCount()
	{
		return Math.max(1, damageRollHitCount);
	}

	public String toChatMessage()
	{
		Color darkRed = new Color(127, 0, 0); // same color as default clan chat color
		return new ChatMessageBuilder()
			.append(darkRed, attackerName + ": ")
			.append(Color.BLACK, "Style: ")
			.append(darkRed, WordUtils.capitalizeFully(animationData.attackStyle.toString()))
			.append(Color.BLACK, "  Hit: ")
			.append(darkRed, getHitRange())
			.append(Color.BLACK, "  Acc: ")
			.append(darkRed, nf1.format(accuracy))
			.append(Color.BLACK, "  AvgHit: ")
			.append(darkRed, nf1.format(expectedDamage))
			.append(Color.BLACK, " Spec?: ")
			.append(darkRed, animationData.isSpecial ? "Y" : "N")
			.append(Color.BLACK, " OffP?:")
			.append(darkRed, success() ? "Y" : "N")
			.build();
	}

	public String getHitRange()
	{
		return minHit + "-" + maxHit;
	}

	// use to sort by last fight time, to sort fights by date/time.
	@Override
	public int compareTo(FightLogEntry o)
	{
		long diff = tick - o.tick;

		// if the attacks were same-ticked, further sort by attacker name so that the sorting is more consistent between 2
		// clients. Since we add competitor logs to the array before opponent logs, it seems like it would always
		// prioritize displaying the client player on same-tick attacks, which would result in an oddly conflicting
		// result when comparing 2 clients, even if the result is the same. This should help keep it more consistent.
		// note that this is when comparing 2 different fight logs, so when processing same-tick attacks, it should
		// never be comparing the attacker name with itself, always the opponent name.
		if (diff == 0 && !Strings.isNullOrEmpty(attackerName) && !Strings.isNullOrEmpty(o.attackerName))
		{
			diff = attackerName.compareTo(o.attackerName);
		}

		// if diff = 0, return 0. Otherwise, divide diff by its absolute value. This will result in
		// -1 for negative numbers, and 1 for positive numbers, keeping the sign and a safely small int.
		return diff == 0 ? 0 :
			(int)(diff / Math.abs(diff));
	}

}

