	private String name;
	private int itemId;

	RingData(String name, int itemId)
	{
		this.name = name;
		this.itemId = itemId;
	}

	@Override
	public String toString()
	{
		return name;
	}

	public static RingData fromId(int itemId)
	{
		for (RingData ring : values())
		{
			if (ring.itemId == itemId)
			{
				return ring;
			}
		}
		return NONE;
	}
