				ColorUtil.colorToHexCode(PvpColorScheme.BLOOD_RED_ORANGE_REDDER) + "'>" + "&nbsp;&nbsp;&nbsp;&#9888;</font><br>See tooltip!");
			final String levelWarningTooltip = "<html>" +
