	public String getOffPrayStats(boolean shortString)
	{
		return shortString ?
			offPraySuccessCount + "/" + attackCount :
			offPraySuccessCount + "/" + attackCount + " (" + nf.format(calculateOffPraySuccessPercentage()) + "%)";
	}

