	{
		return getOffensivePrayStats(false);
	}

	public String getGhostBarrageStats()
	{
		return ghostBarrageCount + " G.B. (" + PvpUtils.prependPlusIfPositive(nf1.format(ghostBarrageExpectedDamage), ghostBarrageExpectedDamage) + ")";
	}

