	{
		return offensivePray == SpriteID.PRAYER_PIETY ? PIETY_STR_PRAYER_MODIFIER :
			offensivePray == SpriteID.PRAYER_ULTIMATE_STRENGTH ? ULTIMATE_STRENGTH_PRAYER_MODIFIER :
			1;
	}

