package com.venomnpctracker;

import lombok.Getter;

@Getter
public enum DisplayMode
{
	LEVEL("Level", 0),
	NAME("Name", 1),
	BOTH("Both", 2),
	SUFFIXONLY("Suffix-Only", 3);

