	@Inject
	public FlipsServiceImpl(GeUncutApi api) {
		this.api = api;
	}

	@Override
	public void fetch(String scanType, String risk, Long capital, Consumer<FlipsResponse> onSuccess, Consumer<ApiFailure> onError) {
		api.fetchFlips(scanType, risk, capital,
				response -> onSuccess.accept(normalize(response)),
				onError);
	}

	// The consumer contract: never null, never a null flip list.
	private static FlipsResponse normalize(FlipsResponse response) {
		if (response == null) {
			return FlipsResponse.builder().flips(Collections.emptyList()).build();
		}
		if (response.getFlips() == null) {
			return FlipsResponse.builder()
					.flips(Collections.emptyList())
					.myCapital(response.getMyCapital())
					.build();
		}
		return response;
	}
}

package app.geuncut.service.impl;

import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;

import app.geuncut.api.ApiFailure;
import app.geuncut.api.GeUncutApi;
import app.geuncut.config.GeUncutConfig;
import app.geuncut.dto.LinkSession;
import app.geuncut.service.LinkService;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.LinkBrowser;

/**
 * Device-link pairing state machine. Starts a session, surfaces the short
 * code for the user to type at geuncut.app/link, polls until the claim lands,
 * then writes the delivered token into the plugin config itself.
 */
@Slf4j
@Singleton
public class LinkServiceImpl implements LinkService {
	private static final int POLL_SECONDS = 5;

	private final GeUncutApi api;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executor;

	private LinkSession session;
	private ScheduledFuture<?> poller;
	private boolean starting;

	@Inject
	public LinkServiceImpl(GeUncutApi api, ConfigManager configManager, ScheduledExecutorService executor) {
		this.api = api;
		this.configManager = configManager;
		this.executor = executor;
	}

	// session and poller are mutated from the UI thread (begin, cancel) and the
	// scheduler thread (poll callbacks); every transition is synchronized so a
	// cancel can never interleave with a start or a poll reading half a state.

	@Override
	public synchronized boolean isPairing() {
		return session != null;
	}

	@Override
	public synchronized void openClaimPage() {
		if (session != null) {
			LinkBrowser.browse(GeUncutConfig.API_BASE + "/link?code=" + session.getUserCode());
		}
	}

	@Override
	public void begin(Consumer<String> onCode, Runnable onLinked, Consumer<ApiFailure> onError) {
		synchronized (this) {
			if (session != null) {
				openClaimPage();
				return;
			}
			if (starting) {
				return;
			}
			starting = true;
		}
		api.startLink(started -> {
			synchronized (this) {
				starting = false;
				if (session != null) {
					return;
				}
				session = started;
				poller = executor.scheduleWithFixedDelay(
						() -> poll(onLinked, onError), POLL_SECONDS, POLL_SECONDS, TimeUnit.SECONDS);
			}
			log.debug("event=link_started expires_in={}s", started.getExpiresInSeconds());
			onCode.accept(started.getUserCode());
		}, failure -> {
			synchronized (this) {
				starting = false;
			}
			onError.accept(failure);
		});
	}

	@Override
	public synchronized void cancel() {
		session = null;
		if (poller != null) {
			poller.cancel(false);
			poller = null;
		}
	}

	private void poll(Runnable onLinked, Consumer<ApiFailure> onError) {
		LinkSession active;
		synchronized (this) {
			if (session == null) {
				return;
			}
			active = session;
		}
		api.pollLink(active.getDeviceCode(),
				token -> {
					synchronized (this) {
						if (session != active) {
							return;
						}
					}
					configManager.setConfiguration(GeUncutConfig.GROUP, "apiToken", token);
					log.debug("event=link_completed");
					cancel();
					onLinked.run();
				},
				() -> {
				},
				failure -> {
					synchronized (this) {
						if (session != active) {
							return;
						}
					}
					log.debug("event=link_poll_stopped kind={} status={} message=\"{}\"",
							failure.getKind(), failure.getStatusCode(), failure.getMessage());
					cancel();
					onError.accept(failure);
				});
	}
}

package app.geuncut.service.impl;

import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;

import app.geuncut.api.GeUncutApi;
import app.geuncut.dto.GeOffer;
import app.geuncut.dto.OfferPlacement;
import app.geuncut.service.OfferSyncService;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Keeps a per-slot view of the player's working offers and flushes the whole
 * set when it changes. A longer interval than the fill stream: this is a
 * glanceable mirror, not an audit log, and the coarse cadence keeps the plugin
 * well inside its request budget when a buy and a sell are filling at once.
 */
@Slf4j
@Singleton
public class OfferSyncServiceImpl extends AbstractSyncService implements OfferSyncService {
	private static final int FLUSH_SECONDS = 10;

	private final GeUncutApi api;
	private final Map<Integer, GeOffer> slots = new HashMap<>();
	// Server placement times keyed "accountHash|slot", consumed on first sight
	// of a matching offer so an age survives a client restart.
	private final Map<String, OfferPlacement> seeds = new HashMap<>();

	private String lastAccountHash;
	private boolean dirty;
	private boolean flushInFlight;

	@Inject
	public OfferSyncServiceImpl(GeUncutApi api, ScheduledExecutorService executor) {
		super(executor, FLUSH_SECONDS);
		this.api = api;
	}

	@Override
	protected void onStop() {
		flush();
		synchronized (slots) {
			slots.clear();
			seeds.clear();
			dirty = false;
			flushInFlight = false;
		}
	}

	@Override
	public void seed(List<OfferPlacement> placements) {
		synchronized (slots) {
			for (OfferPlacement placement : placements) {
				if (placement.getAccountHash() == null || placement.getPlacedAt() == null) {
					continue;
				}
				seeds.put(placement.getAccountHash() + "|" + placement.getSlot(), placement);
				// Retro-apply: the login replay may have recorded the slot before
				// this response arrived.
				if (placement.getAccountHash().equals(lastAccountHash)) {
					GeOffer existing = slots.get(placement.getSlot());
					String placed = seededPlacement(placement, existing);
					if (placed != null && !placed.equals(existing.getOccurredAt())) {
						slots.put(placement.getSlot(), withOccurredAt(existing, placed));
						dirty = true;
					}
				}
			}
		}
	}

	@Override
	public void record(int slot, int itemId, GrandExchangeOfferState state,
			int quantitySold, int totalQuantity, int price, Instant now) {
		synchronized (slots) {
			// Captured while a game event is firing, so it is always the hash of
			// the logged-in account even if the flush tick lands after a logout.
			lastAccountHash = accountHash();
			if (state == GrandExchangeOfferState.EMPTY) {
				if (slots.remove(slot) != null) {
					dirty = true;
				}
				return;
			}
			GeOffer offer = toOffer(slot, itemId, state, quantitySold, totalQuantity, price, now);
			// A malformed slot (non-positive total or price) is dropped rather
			// than queued: the server validates the whole snapshot, so one bad
			// row would otherwise reject every working offer.
			if (offer == null) {
				return;
			}
			GeOffer previous = slots.get(slot);
			if (previous != null && previous.getItemId() == offer.getItemId()
					&& previous.getSide().equals(offer.getSide())
					&& previous.getPriceEach() == offer.getPriceEach()
					&& previous.getQuantityTotal() == offer.getQuantityTotal()
					&& previous.getOccurredAt() != null) {
				offer = withOccurredAt(offer, previous.getOccurredAt());
			} else if (previous == null && lastAccountHash != null) {
				OfferPlacement seedRow = seeds.remove(lastAccountHash + "|" + slot);
				String placed = seedRow != null ? seededPlacement(seedRow, offer) : null;
				if (placed != null) {
					offer = withOccurredAt(offer, placed);
				}
			}
			// GE offers only fire an event when something actually changed, so
			// any recorded change is worth a flush; the interval caps the rate.
			slots.put(slot, offer);
			dirty = true;
		}
	}

	@Override
	public List<GeOffer> current() {
		synchronized (slots) {
			return new ArrayList<>(slots.values());
		}
	}

	@Override
	protected void flush() {
		String hash;
		List<GeOffer> snapshot;
		String syncedAt;
		synchronized (slots) {
			// flushInFlight serializes the async posts: a slow/retrying request must
			// never be overtaken by a newer one, or a stale snapshot could land last.
			if (flushInFlight || !dirty || lastAccountHash == null) {
				return;
			}
			hash = lastAccountHash;
			snapshot = new ArrayList<>(slots.values());
			// Monotonic snapshot time so the server can reject an out-of-order post.
			syncedAt = Instant.now().toString();
			dirty = false;
			flushInFlight = true;
		}
		api.postOffers(hash, snapshot, syncedAt,
				() -> {
					synchronized (slots) {
						flushInFlight = false;
					}
					log.debug("event=offer_sync_flushed count={}", snapshot.size());
				},
				failure -> {
					synchronized (slots) {
						flushInFlight = false;
						if (!failure.isUnauthorized()) {
							dirty = true;
						}
					}
					if (failure.isUnauthorized()) {
						// Not linked: retrying re-hits the same rejection every tick.
						log.warn("event=offer_sync_unauthorized offers={}", snapshot.size());
					} else {
						log.debug("event=offer_sync_requeued offers={} kind={} status={} reason=\"{}\"",
								snapshot.size(), failure.getKind(), failure.getStatusCode(), failure.getMessage());
					}
				});
	}

	// The seed applies only to the offer it describes: same identity, and the
	// server's filled count not ahead of the client's (ahead means the slot was
	// re-placed with an identical offer since the server last saw it).
	private static String seededPlacement(OfferPlacement placement, GeOffer offer) {
		if (offer == null || placement.getSide() == null
				|| placement.getItemId() != offer.getItemId()
				|| !placement.getSide().equals(offer.getSide())
				|| placement.getPriceEach() != offer.getPriceEach()
				|| placement.getQuantityTotal() != offer.getQuantityTotal()
				|| placement.getQuantityFilled() > offer.getQuantityFilled()) {
			return null;
		}
		return toInstantString(placement.getPlacedAt());
	}

	// The server sends naive-UTC timestamps; the panel parses Instant strings.
	private static String toInstantString(String timestamp) {
		try {
			return Instant.parse(timestamp).toString();
		} catch (RuntimeException notInstant) {
			try {
				return LocalDateTime.parse(timestamp).toInstant(ZoneOffset.UTC).toString();
			} catch (RuntimeException unparseable) {
				return null;
			}
		}
	}

	private static GeOffer withOccurredAt(GeOffer offer, String occurredAt) {
		return GeOffer.builder()
				.slot(offer.getSlot())
				.itemId(offer.getItemId())
				.side(offer.getSide())
				.state(offer.getState())
				.quantityFilled(offer.getQuantityFilled())
				.quantityTotal(offer.getQuantityTotal())
				.priceEach(offer.getPriceEach())
				.occurredAt(occurredAt)
				.build();
	}

	private static GeOffer toOffer(int slot, int itemId, GrandExchangeOfferState state,
			int quantitySold, int totalQuantity, int price, Instant now) {
		if (totalQuantity <= 0 || price <= 0 || quantitySold < 0 || quantitySold > totalQuantity) {
			return null;
		}
		String side;
		String stateName;
		switch (state) {
			case BUYING:
				side = "buy";
				stateName = "buying";
				break;
			case BOUGHT:
				side = "buy";
				stateName = "bought";
				break;
			case CANCELLED_BUY:
				side = "buy";
				stateName = "cancelled_buy";
				break;
			case SELLING:
				side = "sell";
				stateName = "selling";
				break;
			case SOLD:
				side = "sell";
				stateName = "sold";
				break;
			case CANCELLED_SELL:
				side = "sell";
				stateName = "cancelled_sell";
				break;
			default:
				return null;
		}
		return GeOffer.builder()
				.slot(slot)
				.itemId(itemId)
				.side(side)
				.state(stateName)
				.quantityFilled(quantitySold)
				.quantityTotal(totalQuantity)
				.priceEach(price)
				.occurredAt(now.toString())
				.build();
	}
}

