package app.geuncut.tracker.impl;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import javax.inject.Singleton;

import app.geuncut.model.Purchase;
import app.geuncut.tracker.BuyLimitTracker;

@Singleton
public class BuyLimitTrackerImpl implements BuyLimitTracker {
	private static final Duration WINDOW = Duration.ofHours(4);

	private final Map<Integer, Deque<Purchase>> purchasesByItem = new HashMap<>();

	@Override
	public void recordBuy(int itemId, int quantity, Instant boughtAt) {
		purchasesByItem.computeIfAbsent(itemId, unseenItemId -> new ArrayDeque<>()).addLast(new Purchase(quantity, boughtAt));
	}

	@Override
	public int boughtInWindow(int itemId, Instant now) {
		Deque<Purchase> purchases = purchasesByItem.get(itemId);
		if (purchases == null) {
			return 0;
		}
		Instant cutoff = now.minus(WINDOW);
		// removeIf, not front-only peek: a backward wall-clock adjustment can leave an
		// out-of-order entry the front-only sweep would never reach.
		purchases.removeIf(purchase -> purchase.getBoughtAt().isBefore(cutoff));
		if (purchases.isEmpty()) {
			purchasesByItem.remove(itemId);
			return 0;
		}
		return purchases.stream().mapToInt(Purchase::getQuantity).sum();
	}

	@Override
	public Optional<Instant> nextReset(int itemId, Instant now) {
		Deque<Purchase> purchases = purchasesByItem.get(itemId);
		if (purchases == null || boughtInWindow(itemId, now) == 0) {
			return Optional.empty();
		}
		return Optional.of(purchases.peekFirst().getBoughtAt().plus(WINDOW));
	}

	@Override
	public void reset() {
		purchasesByItem.clear();
	}
}

package app.geuncut.tracker.impl;

import java.time.Instant;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import javax.inject.Singleton;

import app.geuncut.model.OfferDelta;
import app.geuncut.model.OfferSnapshot;
import app.geuncut.tracker.OfferTracker;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Turns raw GrandExchangeOfferChanged events into fill deltas.
 *
 * The client replays the state of every slot on login. The first event seen
 * for a slot therefore only establishes a baseline and never emits a delta;
 * without this, every login would double count the standing offers.
 */
@Slf4j
@Singleton
public class OfferTrackerImpl implements OfferTracker {
	private final Map<Integer, OfferSnapshot> slots = new HashMap<>();
	// Slots whose first post-reset event has been seen. Only that first event is a
	// login/hop replay to baseline; a slot reused later in the same session is not.
	private final Set<Integer> replayedSlots = new HashSet<>();

	@Override
	public Optional<OfferDelta> onOfferChanged(
			int slot,
			int itemId,
			GrandExchangeOfferState state,
			int quantitySold,
			int spent,
			int totalQuantity,
			int price,
			Instant now) {
		if (state == GrandExchangeOfferState.EMPTY) {
			return residualFill(slots.remove(slot), slot, now);
		}

		boolean selling = isSellState(state);
		boolean firstSinceReset = replayedSlots.add(slot);
		OfferSnapshot last = slots.get(slot);
		slots.put(slot, new OfferSnapshot(itemId, quantitySold, spent, state, totalQuantity, price));

		if (last == null || last.getItemId() != itemId || isSellState(last.getState()) != selling) {
			if (quantitySold > 0 && firstSinceReset) {
				return Optional.empty();
			}
			last = new OfferSnapshot(itemId, 0, 0, state, totalQuantity, price);
		}

		int quantityDelta = quantitySold - last.getQuantitySold();
		int spentDelta = spent - last.getSpent();
		if (quantityDelta <= 0 || spentDelta <= 0) {
			if (quantityDelta > 0 && spentDelta < 0) {
				log.warn("event=fill_discarded_negative_spend item={} slot={} quantity_delta={} spent_delta={}",
						itemId, slot, quantityDelta, spentDelta);
			}
			return Optional.empty();
		}

		int priceEach = (int) Math.round((double) spentDelta / quantityDelta);
		OfferDelta.Side side = selling ? OfferDelta.Side.SELL : OfferDelta.Side.BUY;
		return Optional.of(new OfferDelta(itemId, side, quantityDelta, priceEach, slot, now));
	}

	// A slot that empties while its offer was still BUYING/SELLING and short of
	// its total means the final fill's event never arrived - it can land in the
	// same tick as the collection and collapse straight to EMPTY. Book the
	// unaccounted units at the offer price rather than losing them. An abort
	// always shows its CANCELLED state first, so those clear with no residual;
	// a slot collected while this client was away has no snapshot and is skipped.
	private Optional<OfferDelta> residualFill(OfferSnapshot last, int slot, Instant now) {
		if (last == null || !isActiveState(last.getState())) {
			return Optional.empty();
		}
		int missing = last.getQuantityTotal() - last.getQuantitySold();
		if (missing <= 0 || last.getPrice() <= 0) {
			return Optional.empty();
		}
		OfferDelta.Side side = isSellState(last.getState()) ? OfferDelta.Side.SELL : OfferDelta.Side.BUY;
		log.debug("event=residual_fill_on_empty item={} slot={} missing={} price={}",
				last.getItemId(), slot, missing, last.getPrice());
		return Optional.of(new OfferDelta(last.getItemId(), side, missing, last.getPrice(), slot, now));
	}

	@Override
	public void reset() {
		slots.clear();
		replayedSlots.clear();
	}

	private static boolean isActiveState(GrandExchangeOfferState state) {
		return state == GrandExchangeOfferState.BUYING
				|| state == GrandExchangeOfferState.SELLING;
	}

	private static boolean isSellState(GrandExchangeOfferState state) {
		return state == GrandExchangeOfferState.SELLING
				|| state == GrandExchangeOfferState.SOLD
				|| state == GrandExchangeOfferState.CANCELLED_SELL;
	}
}

package app.geuncut.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

/** A slim progress bar: a dark track with a coloured fill for offer progress. */
class FillBar extends JComponent {
	private final double fraction;
	private final Color fill;

	FillBar(double fraction, Color fill) {
		this.fraction = Math.max(0, Math.min(1, fraction));
		this.fill = fill;
		setPreferredSize(new Dimension(10, 6));
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();
		g2.setColor(Theme.TRACK);
		g2.fillRoundRect(0, 0, w - 1, h - 1, h, h);
		g2.setColor(Theme.LINE);
		g2.drawRoundRect(0, 0, w - 1, h - 1, h, h);
		int fillWidth = (int) Math.round((w - 2) * fraction);
		if (fillWidth > 0) {
			g2.setColor(fill);
			g2.fillRoundRect(1, 1, Math.max(fillWidth, h - 2), h - 2, h, h);
		}
		g2.dispose();
	}
}

package app.geuncut.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;

/**
 * A flat, brand-styled dropdown that replaces the default Swing combo box (a
 * beveled, Windows-era control). Shows the current value and a painted chevron;
 * a click opens a dark popup of the options.
 */
class FlatSelect extends RoundedPanel {
	private String[] labels;
	private String[] values;
	private final JLabel valueLabel;
	private int selectedIndex;
	private Runnable onChange = () -> {
	};

	FlatSelect(String[] options, int selectedIndex) {
		this(options, options, selectedIndex);
	}

	FlatSelect(String[] labels, String[] values, int selectedIndex) {
		super(7, Theme.RAISED, Theme.LINE);
		this.labels = labels;
		this.values = values;
		this.selectedIndex = selectedIndex;
		setLayout(new BorderLayout(6, 0));
		setBorder(BorderFactory.createEmptyBorder(5, 10, 5, 18));

		valueLabel = new JLabel(labels[selectedIndex]);
		valueLabel.setForeground(Theme.INK);
		valueLabel.setFont(Theme.BODY);
		add(valueLabel, BorderLayout.CENTER);

		MouseAdapter adapter = new MouseAdapter() {
			@Override
			public void mousePressed(MouseEvent event) {
				showMenu();
			}

			@Override
			public void mouseEntered(MouseEvent event) {
				setFill(Theme.HOVER);
			}

			@Override
			public void mouseExited(MouseEvent event) {
				if (!contains(SwingUtilities.convertPoint((Component) event.getSource(), event.getPoint(), FlatSelect.this))) {
					setFill(Theme.RAISED);
				}
			}
		};
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addMouseListener(adapter);
		valueLabel.addMouseListener(adapter);
	}

	@Override
	protected void paintComponent(Graphics g) {
		super.paintComponent(g);
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setColor(Theme.FAINT);
		int cx = getWidth() - 12;
		int cy = getHeight() / 2;
		g2.fillPolygon(new int[] { cx - 4, cx + 4, cx }, new int[] { cy - 2, cy - 2, cy + 3 }, 3);
		g2.dispose();
	}

	void setOnChange(Runnable onChange) {
		this.onChange = onChange;
	}

	// The inner label owns most of the hover area, so a tooltip must ride on
	// both components or it only shows over the padding.
	@Override
	public void setToolTipText(String text) {
		super.setToolTipText(text);
		valueLabel.setToolTipText(text);
	}

	String selectedValue() {
		return values[selectedIndex];
	}

	// Replace the option set, keeping the selection on desiredValue when it
	// still exists (first option otherwise). Never fires onChange - the caller
	// decides whether the effective value moved and what to do about it.
	void setOptions(String[] labels, String[] values, String desiredValue) {
		this.labels = labels;
		this.values = values;
		selectedIndex = 0;
		for (int i = 0; i < values.length; i++) {
			if (values[i].equals(desiredValue)) {
				selectedIndex = i;
				break;
			}
		}
		valueLabel.setText(labels[selectedIndex]);
	}

	private void showMenu() {
		JPopupMenu menu = new JPopupMenu();
		menu.setBackground(Theme.RAISED);
		menu.setBorder(BorderFactory.createLineBorder(Theme.LINE_STRONG));
		for (int i = 0; i < labels.length; i++) {
			JMenuItem item = new JMenuItem(labels[i]);
			item.setBackground(Theme.RAISED);
			item.setForeground(i == selectedIndex ? Theme.WHITE : Theme.INK);
			item.setFont(Theme.BODY);
			item.setBorder(BorderFactory.createEmptyBorder(4, 9, 4, 9));
			int index = i;
			item.addActionListener(event -> select(index));
			menu.add(item);
		}
		menu.show(this, 0, getHeight() + 2);
	}

	private void select(int index) {
		if (index == selectedIndex) {
			return;
		}
		selectedIndex = index;
		valueLabel.setText(labels[index]);
		onChange.run();
	}
}

