						? position.getSoldAvgPrice() : position.getExitPrice();
		addLeft(card, detailRow("Sold at",
				soldPrice != null ? GP.format(soldPrice) : "— not sold",
				soldPrice != null ? Theme.INK : Theme.MUTED));
		addLeft(card, detailRow("Spent", shortGp(position.getBuyPrice() * position.getQuantity()), Theme.INK));

		clickable(card, position.getItemId());
		JPanel actions = new JPanel(new BorderLayout());
		actions.setOpaque(false);
		actions.setAlignmentX(Component.LEFT_ALIGNMENT);
		actions.setBorder(BorderFactory.createEmptyBorder(9, 0, 0, 0));
		boolean completed = position.getClosedAt() != null
				|| (position.getSoldQty() != null && position.getSoldQty() > 0);
		actions.add(withTooltip(actionButton(completed ? "Restore" : "Track as a flip",
				() -> onRestore.accept(position.getId())),
				completed ? "Restores under Completed on geuncut.app"
						: "Back to your active flips"), BorderLayout.EAST);
		card.add(actions);
		return card;
	}

	private static RoundedPanel withTooltip(RoundedPanel button, String tip) {
		button.setToolTipText(tip);
		for (Component child : button.getComponents()) {
			if (child instanceof JComponent) {
				((JComponent) child).setToolTipText(tip);
			}
		}
		return button;
	}

	private RoundedPanel plainHistoryCard(int itemId, String name) {
		RoundedPanel card = new RoundedPanel(10, Theme.RAISED, Theme.LINE);
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBorder(BorderFactory.createEmptyBorder(10, 11, 10, 11));
		JPanel head = new JPanel(new BorderLayout(9, 0));
		head.setOpaque(false);
		head.setAlignmentX(Component.LEFT_ALIGNMENT);
		head.add(icon(itemId, name, 26), BorderLayout.WEST);
		JLabel nameHead = nameLabel(name);
		shrinkToFit(nameHead, CONTENT_WIDTH - 26 - 9);
		head.add(nameHead, BorderLayout.CENTER);
		card.add(head);
		card.add(Box.createVerticalStrut(8));
		clickable(card, itemId);
		return card;
	}

	private RoundedPanel marginCheckCard(MarginCheck check) {
		RoundedPanel card = plainHistoryCard(check.getItemId(), check.getItemName());
		addLeft(card, detailRow("Quantity", "1", Theme.INK));
		addLeft(card, detailRow("Bought at", GP.format(check.getBuyPrice()), Theme.INK));
		addLeft(card, detailRow("Sold at", GP.format(check.getSellPrice()), Theme.INK));
		JPanel actions = new JPanel(new BorderLayout());
		actions.setOpaque(false);
		actions.setAlignmentX(Component.LEFT_ALIGNMENT);
		actions.setBorder(BorderFactory.createEmptyBorder(9, 0, 0, 0));
		actions.add(withTooltip(actionButton("Restore",
				() -> onTrackPair.accept(check.getSellEventId())),
				"Restores under Completed on geuncut.app"), BorderLayout.EAST);
		card.add(actions);
		return card;
	}

	private RoundedPanel archivedSellCard(ArchivedSell sale) {
		RoundedPanel card = plainHistoryCard(sale.getItemId(), sale.getItemName());
		addLeft(card, detailRow("Quantity", GP.format(sale.getQuantity()), Theme.INK));
		addLeft(card, detailRow("Bought at", "—", Theme.MUTED));
		addLeft(card, detailRow("Sold at",
				sale.getPriceEach() != null ? GP.format(sale.getPriceEach()) : "—",
				sale.getPriceEach() != null ? Theme.INK : Theme.MUTED));
		return card;
	}


	private JLabel icon(int itemId, String name, int size) {
		JLabel label = new JLabel();
		label.setPreferredSize(new Dimension(size + 2, size));
		label.setHorizontalAlignment(SwingConstants.CENTER);
		iconLoader.load(itemId, name, label, size);
		return label;
	}

	// Item rows open the full item page on geuncut.app, with a hover highlight so
	// the row reads as tappable. Installed across the whole subtree so a click
	// anywhere in the card counts, not just the padding between labels.
	private void clickable(RoundedPanel card, int itemId) {
		installHoverClick(card, () -> onOpenItem.accept(itemId));
	}

	private static void installHoverClick(RoundedPanel panel, Runnable onClick) {
		MouseAdapter adapter = new MouseAdapter() {
			@Override
			public void mouseClicked(MouseEvent event) {
				onClick.run();
			}

			@Override
			public void mouseEntered(MouseEvent event) {
				panel.setFill(Theme.HOVER);
			}

			@Override
			public void mouseExited(MouseEvent event) {
				if (!panel.contains(SwingUtilities.convertPoint((Component) event.getSource(), event.getPoint(), panel))) {
					panel.setFill(Theme.RAISED);
				}
			}
		};
		installRecursively(panel, adapter);
	}

	private static void installRecursively(Component component, MouseAdapter adapter) {
		component.addMouseListener(adapter);
		component.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		if (component instanceof Container) {
			for (Component child : ((Container) component).getComponents()) {
				installRecursively(child, adapter);
			}
		}
	}

	private Pill pill(String label, java.awt.Color hue) {
		return new Pill(label, hue, Theme.soft(hue), null);
	}

	private Pill solidPill(String label, java.awt.Color hue) {
		Pill chip = new Pill(label, Theme.PILL_INK, hue, null);
		chip.setFont(Theme.PILL);
		return chip;
	}

	private JPanel sectionHeader(String title, JLabel count) {
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.X_AXIS));
		header.setBackground(Theme.SURFACE);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.setBorder(BorderFactory.createEmptyBorder(2, 0, 9, 0));

		JLabel titleLabel = text(title.toUpperCase(), Theme.MUTED, Theme.SECTION);
		header.add(titleLabel);
		header.add(Box.createHorizontalStrut(9));
		if (count != null) {
			count.setForeground(Theme.MUTED);
			count.setFont(Theme.NUM_SMALL);
			header.add(count);
			header.add(Box.createHorizontalStrut(8));
		}
		JPanel rule = new JPanel();
		rule.setBackground(Theme.LINE);
		rule.setPreferredSize(new Dimension(10, 1));
		rule.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
		header.add(rule);
		return header;
	}

	private static JLabel statValue(String text) {
		JLabel label = new JLabel(text, SwingConstants.CENTER);
		label.setForeground(Theme.WHITE);
		label.setFont(Theme.NUM_BOLD);
		return label;
	}

	private JPanel wrapList(JPanel list) {
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(Theme.SURFACE);
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);
		wrapper.add(list, BorderLayout.NORTH);
		return wrapper;
	}

	private static JPanel listPanel() {
		// BoxLayout, not GridLayout: cards must size to their own content. GridLayout
		// stretched every card to the tallest one, leaving whitespace under short ones.
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(Theme.SURFACE);
		return list;
	}

	// Add a full-width card, capped to its own height so the vertical box never
	// stretches it, with a 6px gap above every card after the first.
	private static void addCard(JPanel list, JComponent card) {
		if (list.getComponentCount() > 0) {
			list.add(Box.createVerticalStrut(6));
		}
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		list.add(card);
	}

	// Item name that never widens the card past the panel: a long name clips (with
	// the full name on hover) instead of forcing a minimum width wider than 225px.
	private JLabel nameLabel(String name) {
		JLabel label = text(name, Theme.WHITE, Theme.BODY_BOLD);
		label.setToolTipText(name);
		int height = label.getPreferredSize().height;
		label.setMinimumSize(new Dimension(0, height));
		label.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return label;
	}

	private static JLabel text(String value, java.awt.Color color, java.awt.Font font) {
		JLabel label = new JLabel(value);
		label.setForeground(color);
		label.setFont(font);
		return label;
	}

	private static JButton styledButton(String text) {
		JButton button = new JButton(text);
		button.setBackground(Theme.RAISED);
		button.setForeground(Theme.INK);
		button.setFont(Theme.BODY);
		button.setFocusPainted(false);
		button.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(Theme.LINE_STRONG),
				BorderFactory.createEmptyBorder(6, 12, 6, 12)));
		return button;
	}

	private static Component strut(int height) {
		return Box.createVerticalStrut(height);
	}

	private static void setStat(JLabel label, long value) {
		if (value == 0) {
			label.setText("0");
			label.setForeground(Theme.WHITE);
		} else if (value > 0) {
			label.setText("+" + shortGp(value));
			label.setForeground(Theme.UP);
		} else {
			label.setText("−" + shortGp(-value));
			label.setForeground(Theme.DOWN);
		}
	}

	private static void setPct(JLabel label, Double value) {
		if (value == null) {
			label.setText("—");
			label.setForeground(Theme.MUTED);
		} else {
			label.setText(signedPct(value));
			label.setForeground(value >= 0 ? Theme.UP : Theme.DOWN);
		}
	}

	private static String pnlText(long value) {
		return (value >= 0 ? "+" : "−") + shortGp(Math.abs(value));
	}

	private static String signedPct(double value) {
		return (value >= 0 ? "+" : "−") + trimNum(Math.abs(value)) + "%";
	}

	private static String trimNum(double value) {
		double rounded = Math.round(value * 10) / 10.0;
		return rounded == Math.floor(rounded) ? Integer.toString((int) rounded) : Double.toString(rounded);
	}

	private static String shortGp(long value) {
		long magnitude = Math.abs(value);
		if (magnitude >= 1_000_000) {
			return String.format("%.1fM", value / 1_000_000.0);
		}
		if (magnitude >= 1_000) {
			return Math.round(value / 1000.0) + "k";
		}
		return Long.toString(value);
	}
}

package app.geuncut.ui;

import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;

import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Loads the crisp wiki "detail" render for an item (the same image the website
 * shows), falling back to the in-game inventory sprite until it arrives or if
 * the fetch fails. Cached by name so a given item is only fetched once.
 *
 * Uses RuneLite's shared client, which carries no plugin auth, so the token is
 * never sent to the wiki.
 */
public class ItemIconLoader {
	private static final int MAX_CACHE = 512;

	private final OkHttpClient http;
	private final ItemManager itemManager;
	private final Map<String, ImageIcon> cache = Collections.synchronizedMap(
			new LinkedHashMap<String, ImageIcon>(64, 0.75f, true) {
				@Override
				protected boolean removeEldestEntry(Map.Entry<String, ImageIcon> eldest) {
					return size() > MAX_CACHE;
				}
			});

	public ItemIconLoader(OkHttpClient http, ItemManager itemManager) {
		this.http = http;
		this.itemManager = itemManager;
	}

	// In-game inventory sprite, no network; onLoaded fires (on the EDT) once it decodes.
	Image sprite(int itemId, Runnable onLoaded) {
		AsyncBufferedImage image = itemManager.getImage(itemId);
		image.onLoaded(() -> SwingUtilities.invokeLater(onLoaded));
		return image;
	}

	void load(int itemId, String name, JLabel label, int size) {
		AsyncBufferedImage sprite = itemManager.getImage(itemId);
		sprite.onLoaded(() -> SwingUtilities.invokeLater(() ->
				label.setIcon(new ImageIcon(fit(sprite, size)))));
		label.setIcon(new ImageIcon(fit(sprite, size)));
		if (name == null || name.trim().isEmpty()) {
			return;
		}
		String key = itemId + ":" + size;
		ImageIcon cached = cache.get(key);
		if (cached != null) {
			label.setIcon(cached);
			return;
		}
		http.newCall(new Request.Builder().url(detailUrl(name)).build()).enqueue(new Callback() {
			@Override
			public void onFailure(Call call, IOException exception) {
				// Keep the sprite already on the label.
			}

			@Override
			public void onResponse(Call call, Response response) {
				try (Response managed = response) {
					if (!managed.isSuccessful() || managed.body() == null) {
						return;
					}
					BufferedImage image = ImageIO.read(managed.body().byteStream());
					if (image == null) {
						return;
					}
					ImageIcon icon = new ImageIcon(fit(image, size));
					cache.put(key, icon);
					SwingUtilities.invokeLater(() -> label.setIcon(icon));
				} catch (IOException unreadable) {
					// Keep the sprite.
				}
			}
		});
	}

	// Scale to fit a size x size box while keeping the render's aspect ratio.
	private static Image fit(BufferedImage image, int size) {
		int width = image.getWidth();
		int height = image.getHeight();
		double scale = (double) size / Math.max(width, height);
		int scaledWidth = Math.max(1, (int) Math.round(width * scale));
		int scaledHeight = Math.max(1, (int) Math.round(height * scale));
		return image.getScaledInstance(scaledWidth, scaledHeight, Image.SCALE_SMOOTH);
	}

	private static String detailUrl(String name) {
		String file = name.trim().replace(' ', '_') + "_detail.png";
		return "https://oldschool.runescape.wiki/images/thumb/" + file + "/96px-" + file;
	}
}

package app.geuncut.ui;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Component;
import java.awt.Composite;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntConsumer;
import javax.swing.JComponent;
import javax.swing.Timer;

import app.geuncut.dto.MoverEntry;

/**
 * A paged list of movers, two text lines per row: the name owns line one (with
 * the ↗ click affordance), price and day volume fill line two beside the
 * change%. Extra pages fade in and out on a timer, an alpha dip rather than a
 * scroll, so nothing moves per frame. Clicking a row opens its item details.
 */
class MoversRotator extends JComponent {
	private static final int PAGE = 5;
	private static final int DWELL_MS = 10_000;
	private static final int FADE_MS = 650;
	private static final int TICK_MS = 16;
	private static final int ROW_HEIGHT = 36;
	private static final int ICON = 20;
	private static final int TEXT_X = ICON + 8;
	private static final int NAME_GAP = 8;

	/** Supplies the row icon and repaints the strip once the sprite decodes. */
	interface IconProvider {
		Image icon(int itemId, Runnable onLoaded);
	}

	private final Font numberFont;
	private final Color pctColor;
	private final IconProvider icons;
	private final IntConsumer onOpen;
	private final java.util.function.Function<MoverEntry, String> valueText;
	private final List<Row> rows = new ArrayList<>();
	private final Timer timer;

	private int page;
	private int fadingFrom = -1; // page dipping out, or -1 when settled
	private long fadeStartNanos;
	private long pageShownNanos;

	MoversRotator(Font numberFont, Color pctColor, IconProvider icons, IntConsumer onOpen) {
		this(numberFont, pctColor, icons, onOpen,
				entry -> String.format("%+.1f%%", entry.getChangePct()));
	}

	MoversRotator(Font numberFont, Color pctColor, IconProvider icons, IntConsumer onOpen,
			java.util.function.Function<MoverEntry, String> valueText) {
		this.numberFont = numberFont;
		this.pctColor = pctColor;
		this.icons = icons;
		this.onOpen = onOpen;
		this.valueText = valueText;
		setOpaque(true);
		setBackground(Theme.SURFACE);
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter() {
			@Override
			public void mouseClicked(MouseEvent event) {
				int index = page * PAGE + event.getY() / ROW_HEIGHT;
				if (onOpen != null && index >= 0 && index < rows.size()) {
					onOpen.accept(rows.get(index).itemId);
				}
			}
		});
		timer = new Timer(TICK_MS, event -> tick());
	}

	void setEntries(List<MoverEntry> next) {
		rows.clear();
		if (next != null) {
			for (MoverEntry entry : next) {
				// A malformed feed entry (Gson leaves an absent name null) must not
				// NPE every paint of the strip.
				if (entry == null || entry.getName() == null) {
					continue;
				}
				Row row = new Row(entry.getName(), valueText.apply(entry),
						detailLine(entry), entry.getItemId());
				// Fetch the sprite once here (not per paint) so onLoaded is registered once.
				row.icon = icons.icon(entry.getItemId(), this::repaint);
				rows.add(row);
			}
		}
		page = 0;
		fadingFrom = -1;
		pageShownNanos = nowNanos();
		int visibleRows = totalPages() > 1 ? PAGE : rows.size();
		Dimension size = new Dimension(10, visibleRows * ROW_HEIGHT);
		setPreferredSize(size);
		setMaximumSize(new Dimension(Integer.MAX_VALUE, visibleRows * ROW_HEIGHT));
		if (totalPages() > 1) {
			if (!timer.isRunning()) {
				timer.start();
			}
		} else {
			timer.stop();
		}
		revalidate();
		repaint();
	}

	private int totalPages() {
		return rows.isEmpty() ? 0 : (rows.size() + PAGE - 1) / PAGE;
	}

	private static String detailLine(MoverEntry entry) {
		if (entry.getPrice() == null) {
			return null;
		}
		String line = String.format("%,d gp", entry.getPrice());
		if (entry.getVolumeDay() != null && entry.getVolumeDay() > 0) {
			line += " · " + shortAmount(entry.getVolumeDay()) + " vol";
		}
		return line;
	}

	private static String shortAmount(long value) {
		if (value >= 1_000_000) {
			return String.format("%.1fM", value / 1_000_000.0);
		}
		if (value >= 1_000) {
			return Math.round(value / 1000.0) + "k";
		}
		return Long.toString(value);
	}

	// Package-private so the offscreen render harness can step the animation.
	void tick() {
		long now = nowNanos();
		if (fadingFrom >= 0) {
			if (now - fadeStartNanos >= FADE_MS * 1_000_000L) {
				fadingFrom = -1;
				pageShownNanos = now;
			}
			repaint();
		} else if (totalPages() > 1 && now - pageShownNanos >= DWELL_MS * 1_000_000L) {
			fadingFrom = page;
			page = (page + 1) % totalPages();
			fadeStartNanos = now;
			repaint();
		}
	}

	// Overridable clock so the harness can drive the fade deterministically.
	long nowNanos() {
		return System.nanoTime();
	}

	@Override
	public void addNotify() {
		super.addNotify();
		// Re-added after a panel switch (removeNotify stopped the timer). Restart
		// the dwell from now so the page doesn't fade the instant it reappears.
		if (totalPages() > 1 && !timer.isRunning()) {
			fadingFrom = -1;
			pageShownNanos = nowNanos();
			timer.start();
		}
	}

	@Override
	public void removeNotify() {
		timer.stop();
		super.removeNotify();
	}

	@Override
	protected void paintComponent(Graphics g) {
		super.paintComponent(g);
		g.setColor(getBackground());
		g.fillRect(0, 0, getWidth(), getHeight());
		if (rows.isEmpty()) {
			return;
		}
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		if (fadingFrom >= 0) {
			// Dip the old page out, then the new one in; they never overlap (no text smear).
			double progress = (nowNanos() - fadeStartNanos) / (FADE_MS * 1_000_000.0);
			progress = Math.max(0.0, Math.min(1.0, progress));
			if (progress < 0.5) {
				paintPage(g2, fadingFrom, (float) (1.0 - progress * 2.0));
			} else {
				paintPage(g2, page, (float) (progress * 2.0 - 1.0));
			}
		} else {
			paintPage(g2, page, 1f);
		}
		g2.dispose();
	}

	private void paintPage(Graphics2D g2, int pageIndex, float alpha) {
		if (alpha <= 0f) {
			return;
		}
		Composite base = g2.getComposite();
		g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.min(1f, alpha)));
		FontMetrics nameMetrics = g2.getFontMetrics(Theme.BODY);
		FontMetrics pctMetrics = g2.getFontMetrics(numberFont);
		FontMetrics detailMetrics = g2.getFontMetrics(Theme.NUM_SMALL);
		int start = pageIndex * PAGE;
		int end = Math.min(start + PAGE, rows.size());
		for (int index = start; index < end; index++) {
			Row row = rows.get(index);
			int rowY = (index - start) * ROW_HEIGHT;
			int line1 = rowY + 14;
			int line2 = rowY + 29;
			if (row.icon != null) {
				g2.drawImage(row.icon, 0, rowY + (ROW_HEIGHT - ICON) / 2, ICON, ICON, null);
			}
			g2.setFont(Theme.BODY);
			int arrowX = getWidth() - nameMetrics.stringWidth("↗");
			g2.setColor(Theme.MUTED);
			g2.drawString("↗", arrowX, line1);
			g2.setColor(Theme.INK);
			g2.drawString(truncate(row.name, nameMetrics, arrowX - NAME_GAP - TEXT_X), TEXT_X, line1);
			g2.setFont(numberFont);
			g2.setColor(pctColor);
			int pctX = getWidth() - pctMetrics.stringWidth(row.pct);
			g2.drawString(row.pct, pctX, line2);
			if (row.detail != null) {
				g2.setFont(Theme.NUM_SMALL);
				g2.setColor(Theme.INK);
				g2.drawString(truncate(row.detail, detailMetrics, pctX - NAME_GAP - TEXT_X), TEXT_X, line2);
			}
		}
		g2.setComposite(base);
	}

	private static String truncate(String text, FontMetrics metrics, int maxWidth) {
		if (maxWidth <= 0 || metrics.stringWidth(text) <= maxWidth) {
			return text;
		}
		int ellipsisWidth = metrics.stringWidth("…");
		int end = text.length();
		while (end > 0 && metrics.stringWidth(text.substring(0, end)) + ellipsisWidth > maxWidth) {
			end--;
		}
		return text.substring(0, Math.max(0, end)) + "…";
	}

	static final class Row {
		private final String name;
		private final String pct;
		private final String detail;
		private final int itemId;
		private Image icon;

		Row(String name, String pct, String detail, int itemId) {
			this.name = name;
			this.pct = pct;
			this.detail = detail;
			this.itemId = itemId;
		}
	}
}

package app.geuncut.ui;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.BorderFactory;
import javax.swing.JLabel;

/** A small rounded badge/chip: coloured text on a translucent ground. */
class Pill extends JLabel {
	private final Color ground;
	private final Color border;

	Pill(String text, Color fg, Color ground, Color border) {
		super(text);
		this.ground = ground;
		this.border = border;
		setForeground(fg);
		setFont(Theme.NUM_SMALL);
		setBorder(BorderFactory.createEmptyBorder(1, 6, 2, 6));
		setOpaque(false);
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();
		if (ground != null) {
			g2.setColor(ground);
			g2.fillRoundRect(0, 0, w - 1, h - 1, h, h);
		}
		if (border != null) {
			g2.setColor(border);
			g2.drawRoundRect(0, 0, w - 1, h - 1, h, h);
		}
		g2.dispose();
		super.paintComponent(g);
	}
}

package app.geuncut.ui;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JPanel;

/** A panel that paints a rounded, optionally bordered background. */
class RoundedPanel extends JPanel {
	private final int arc;
	private Color fill;
	private final Color border;

	RoundedPanel(int arc, Color fill, Color border) {
		this.arc = arc;
		this.fill = fill;
		this.border = border;
		setOpaque(false);
	}

	void setFill(Color fill) {
		this.fill = fill;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();
		if (fill != null) {
			g2.setColor(fill);
			g2.fillRoundRect(0, 0, w - 1, h - 1, arc, arc);
		}
		if (border != null) {
			g2.setColor(border);
			g2.drawRoundRect(0, 0, w - 1, h - 1, arc, arc);
		}
		g2.dispose();
		super.paintComponent(g);
	}
}

package app.geuncut.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontFormatException;
import java.io.IOException;
import java.io.InputStream;

/**
 * GE Uncut brand palette and fonts for the panel, mirroring the website's
 * monochrome trading-desk theme: near-black surfaces, a near-white accent,
 * monospace numerals, and semantic colour only where it means something.
 */
final class Theme {
	private Theme() {
	}

	/** Panel colour mode. Dark is RuneLite's native look; light mirrors the website. */
	enum Mode {
		DARK, LIGHT
	}

	static Color SURFACE;
	static Color RAISED;
	static Color HOVER;
	static Color TRACK;
	static Color LINE;
	static Color LINE_STRONG;
	static Color INK;
	static Color WHITE;
	static Color MUTED;
	static Color FAINT;
	static Color UP;
	static Color DOWN;
	static Color AMBER;
	static Color INFO;
	static Color PILL_INK;

	private static Mode mode = Mode.DARK;

	static {
		apply(Mode.DARK);
	}

	static Mode mode() {
		return mode;
	}

	/** Repaint the palette for a mode. Call before rebuilding the panel. */
	static void apply(Mode target) {
		mode = target;
		if (target == Mode.LIGHT) {
			SURFACE = new Color(0xF4, 0xF4, 0xF3);
			RAISED = new Color(0xFF, 0xFF, 0xFF);
			HOVER = new Color(0xEC, 0xEC, 0xEA);
			TRACK = new Color(0xE7, 0xE7, 0xE4);
			LINE = new Color(0xE4, 0xE4, 0xE1);
			LINE_STRONG = new Color(0xD2, 0xD2, 0xCE);
			INK = new Color(0x14, 0x15, 0x1A);
			WHITE = new Color(0x0A, 0x0B, 0x0F);
			MUTED = new Color(0x49, 0x4C, 0x57);
			FAINT = new Color(0x6B, 0x6E, 0x7A);
			UP = new Color(0x15, 0x80, 0x3D);
			DOWN = new Color(0xC4, 0x1F, 0x1F);
			AMBER = new Color(0xB4, 0x53, 0x09);
			INFO = new Color(0x25, 0x63, 0xEB);
			PILL_INK = new Color(0xFF, 0xFF, 0xFF);
		} else {
			SURFACE = new Color(0x14, 0x14, 0x14);
			RAISED = new Color(0x1E, 0x1E, 0x1E);
			HOVER = new Color(0x2A, 0x2A, 0x2A);
			TRACK = new Color(0x14, 0x14, 0x14);
			LINE = new Color(0x2E, 0x2E, 0x2E);
			LINE_STRONG = new Color(0x3E, 0x3E, 0x3E);
			INK = new Color(0xED, 0xED, 0xF0);
			WHITE = new Color(0xFF, 0xFF, 0xFF);
			MUTED = new Color(0xC2, 0xC2, 0xCA);
			FAINT = new Color(0x9A, 0x9A, 0xA4);
			UP = new Color(0x2E, 0xC2, 0x7E);
			DOWN = new Color(0xF4, 0x57, 0x4D);
			AMBER = new Color(0xE8, 0xA1, 0x3C);
			INFO = new Color(0x4D, 0x9F, 0xFF);
			PILL_INK = new Color(0x10, 0x13, 0x0F);
		}
	}

	static Color soft(Color base) {
		return new Color(base.getRed(), base.getGreen(), base.getBlue(), 34);
	}


	// The website's faces, bundled so the panel matches it exactly: Inter for
	// text, JetBrains Mono for numerals. Falls back to logical fonts if a
	// resource is somehow missing.
	private static final Font INTER = load("/fonts/Inter-Regular.ttf", Font.SANS_SERIF);
	private static final Font INTER_SEMI = load("/fonts/Inter-SemiBold.ttf", Font.SANS_SERIF);
	private static final Font MONO = load("/fonts/JetBrainsMono-Regular.ttf", Font.MONOSPACED);
	private static final Font MONO_SEMI = load("/fonts/JetBrainsMono-Bold.ttf", Font.MONOSPACED);

	static final Font BODY = INTER.deriveFont(12.5f);
	static final Font BODY_BOLD = INTER_SEMI.deriveFont(12.5f);
	static final Font SMALL = INTER.deriveFont(11f);
	static final Font SMALL_BOLD = INTER_SEMI.deriveFont(11f);
	static final Font PILL = INTER_SEMI.deriveFont(9.5f);
	static final Font SECTION = INTER_SEMI.deriveFont(10.5f);
	static final Font NUM = MONO.deriveFont(12f);
	static final Font NUM_BOLD = MONO_SEMI.deriveFont(12f);
	static final Font NUM_LG = MONO_SEMI.deriveFont(14f);
	static final Font NUM_SMALL = MONO.deriveFont(11f);
	static final Font NUM_TINY = MONO.deriveFont(9.5f);
	static final Font NUM_HERO = MONO_SEMI.deriveFont(20f);

	private static Font load(String resource, String fallbackFamily) {
		try (InputStream in = Theme.class.getResourceAsStream(resource)) {
			if (in != null) {
				return Font.createFont(Font.TRUETYPE_FONT, in);
			}
		} catch (FontFormatException | IOException unreadable) {
			// Fall through to the logical-font fallback.
		}
		return new Font(fallbackFamily, Font.PLAIN, 12);
	}
}

