						+ "\"volume_spikes\":[{\"name\":\"Chocolate cake\",\"volume_ratio\":88.6}]}"));

		AtomicReference<Movers> received = new AtomicReference<>();
		CountDownLatch done = new CountDownLatch(1);
		api.fetchMovers(movers -> {
