        detailScroll.setBorder(BorderFactory.createEmptyBorder());
        detailScroll.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        detailScroll.getVerticalScrollBar().setPreferredSize(new Dimension(6, 0));
