    // ── Favourites ─────────────────────────────────────────────────────────────

    /**
     * Reads the comma-separated list of favourite item IDs from RuneLite config
     * and populates {@link #favouriteIds}.  Called once during {@link #init()}.
     */
    private void loadFavourites() {
        String csv = configManager.getConfiguration("osrjei", "favourites");
        if (csv == null || csv.isEmpty()) return;
        for (String part : csv.split(",")) {
            try {
                favouriteIds.add(Integer.parseInt(part.trim()));
            } catch (NumberFormatException ignored) { }
        }
        log.debug("[JEI] Loaded {} favourite(s)", favouriteIds.size());
    }

    /**
     * Persists {@link #favouriteIds} to RuneLite config as a comma-separated
     * string of item IDs.  Call after every change to the set.
     */
    private void saveFavourites() {
        String csv = favouriteIds.stream()
            .map(String::valueOf)
            .collect(Collectors.joining(","));
        configManager.setConfiguration("osrjei", "favourites", csv);
    }

    /** Toggles the given item's favourite status, updates the star button, and saves. */
    private void toggleFavourite(SearchItem item) {
        if (favouriteIds.contains(item.id)) {
            favouriteIds.remove(item.id);
        } else {
            favouriteIds.add(item.id);
        }
        updateStarButton(item);
        saveFavourites();

        // If the favourites grid is open, refresh it to reflect the change
        if (favToggle != null && favToggle.isSelected()) {
            List<SearchItem> favItems = buildFavouritesList();
            SwingUtilities.invokeLater(() -> populateGrid(favItems));
        }
    }

    /**
     * Updates the star button text and tooltip to reflect whether
     * {@code item} is currently in the favourites set.
     */
    private void updateStarButton(SearchItem item) {
        if (favouriteIds.contains(item.id)) {
            starButton.setText("★");
            starButton.setToolTipText("Remove from favourites");
        } else {
            starButton.setText("☆");
            starButton.setToolTipText("Add to favourites");
        }
    }

    /**
     * Builds the ordered list of favourite items by looking up each stored ID
     * in {@link #idIndex}.  O(k) where k = number of favourites.
     * Items not found (index not ready yet, or stale ID) are silently skipped.
     */
    private List<SearchItem> buildFavouritesList() {
        Map<Integer, SearchItem> idx = idIndex; // stable snapshot
        List<SearchItem> result = new ArrayList<>();
        for (int id : favouriteIds) {
            SearchItem si = idx.get(id);
            if (si != null) result.add(si);
        }
        return result;
    }

    // ── In-game right-click lookup ─────────────────────────────────────────────

    /**
     * Called by {@link JEIPlugin} when the player clicks "JEI Lookup" from an
     * item's right-click menu.  Must be called on the EDT.
     *
     * <p>Noted items (e.g. noted iron bar) share a name with the base item but
     * have a different ID.  We resolve the base item ID on the client thread
     * before searching the index so the lookup always succeeds for noted stacks.
     *
     * @param itemId the item ID from the menu event
     */
    public void lookupItem(int itemId) {
        // Resolve noted → base item on the client thread, then search + show on EDT
        clientThread.invokeLater(() -> {
            int resolvedId = itemId;
            try {
                net.runelite.api.ItemComposition comp =
                    itemManager.getItemComposition(itemId);
                // getNote() returns 799 if the item is a note; getLinkedNoteId()
                // gives the un-noted (base) item's ID
                if (comp != null && comp.getNote() == 799) {
                    resolvedId = comp.getLinkedNoteId();
                }
            } catch (Exception ignored) { }

            final int finalId = resolvedId;
            SwingUtilities.invokeLater(() -> {
                // O(1) lookup via idIndex
                SearchItem item = idIndex.get(finalId);
                if (item != null) {
                    navStack.clear();
                    backButton.setVisible(false);
                    gridCardLayout.show(gridCardPanel, "grid");
                    loadItemDetail(item);
                } else {
                    log.warn("[JEI] Item ID {} not found in item index", finalId);
                }
            });
        });
    }

    // ── Utilities ──────────────────────────────────────────────────────────────

    /**
     * Finds a SearchItem by exact (case-insensitive) name.
     * O(1) via {@link #nameIndex}; was previously O(n) linear scan.
     */
    private SearchItem findByName(String name) {
        if (name == null || name.isEmpty()) return null;
        return nameIndex.get(name.toLowerCase(Locale.ROOT));
    }

    private static String escHtml(String s) {
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private void openWiki() {
        if (selectedItemName.isEmpty()) return;
        try {
            String wikiName = selectedItemName.replace(" ", "_");
            Desktop.getDesktop().browse(new URI("https://oldschool.runescape.wiki/w/" + wikiName));
        } catch (Exception e) {
            log.warn("[JEI] Could not open wiki page: {}", e.getMessage());
        }
    }
}

package com.osr.jei;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;

/**
 * Entry point for the OSRS JEI plugin.
 *
 * This plugin adds a sidebar panel to RuneLite where you can:
 *   - Search any OSRS item by name
 *   - See its Grand Exchange price
 *   - See every monster that drops it (with rates)
 *   - Open the OSRS Wiki page for full details
 *
 * Right-clicking any item in the game (inventory, bank, equipment, ground)
 * shows a "JEI Lookup" option that jumps straight to that item's detail page
 * in the sidebar.
 */
@Slf4j
@PluginDescriptor(
    name        = "OSRS JEI",
    description = "Browse items, drop tables, and sources — inspired by JEI from Minecraft",
    tags        = {"item", "drops", "wiki", "browser", "search", "jei"}
)
public class JEIPlugin extends Plugin {

    @Inject private Client        client;
    @Inject private ClientToolbar clientToolbar;
    @Inject private JEIPanel      panel;

    private NavigationButton navButton;

    @Override
    protected void startUp() {
        // Build the Swing UI on the Event Dispatch Thread (required by Java Swing)
        SwingUtilities.invokeLater(() -> {
            try {
                panel.init();

                navButton = NavigationButton.builder()
                    .tooltip("OSRS JEI — Item Browser")
                    .icon(createIcon())
                    .priority(6)
                    .panel(panel)
                    .build();

                clientToolbar.addNavigation(navButton);
                log.info("OSRS JEI plugin started successfully");
            } catch (Exception e) {
                // Without this catch, Swing swallows the error silently — you'd never know it failed
                log.error("OSRS JEI failed to start", e);
            }
        });
    }

    @Override
    protected void shutDown() {
        SwingUtilities.invokeLater(() -> {
            clientToolbar.removeNavigation(navButton);
            log.info("OSRS JEI plugin stopped");
        });
    }

    // ── Right-click item lookup ────────────────────────────────────────────────

    /**
     * Adds a "JEI Lookup" entry to the right-click menu whenever an item's
     * "Examine" option is present — i.e. when the player right-clicks an item
     * in their inventory, bank, equipment, or on the ground.
     *
     * Clicking the entry selects the JEI sidebar panel and loads that item's
     * detail page (price, recipe, drop sources, wiki link).
     */
    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        int type = event.getType();

        // Fire on item Examine — inventory items and items on the ground.
        // (Bank items use widget-based menus with a different action type and
        // cannot be intercepted the same way without widget inspection.)
        if (type != MenuAction.EXAMINE_ITEM.getId()
                && type != MenuAction.EXAMINE_ITEM_GROUND.getId()) {
            return;
        }

        final int itemId = event.getIdentifier();

        // Insert our entry just above "Examine" (position -1 = last slot)
        client.createMenuEntry(-1)
            .setOption("<col=ff9040>JEI</col> Lookup")
            .setTarget(event.getTarget())           // keeps the coloured item name
            .setType(MenuAction.RUNELITE)
            .onClick(e -> SwingUtilities.invokeLater(() -> {
                // Open the JEI sidebar panel, then load the item detail
                clientToolbar.openPanel(navButton);
                panel.lookupItem(itemId);
            }));
    }

    // ── Config ─────────────────────────────────────────────────────────────────

    @Provides
    JEIConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(JEIConfig.class);
    }

    // ── Icon ───────────────────────────────────────────────────────────────────

    /**
     * Draws a simple 16x16 icon for the navigation button.
     * It's a golden square with "JEI" — replace with a real PNG later if you want.
     */
    private BufferedImage createIcon() {
        BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();

        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        // OSRS gold-ish background
        g.setColor(new Color(200, 160, 50));
        g.fillRoundRect(0, 0, 15, 15, 4, 4);

        // Dark border
        g.setColor(new Color(80, 60, 10));
        g.drawRoundRect(0, 0, 15, 15, 4, 4);

        // Label
        g.setColor(Color.BLACK);
        g.setFont(new Font("Arial", Font.BOLD, 7));
        g.drawString("JEI", 2, 10);

        g.dispose();
        return img;
    }
}

package com.osr.jei;

import java.awt.*;

/**
 * A FlowLayout variant that correctly reports its preferred height to a JScrollPane
 * so that items wrap to the next row instead of scrolling horizontally.
 *
 * The standard FlowLayout always returns a single-row height to
 * preferredLayoutSize(), which makes JScrollPane think no vertical scrolling is
 * needed.  This class fixes that by walking each "virtual" row and summing heights.
 *
 * Based on Rob Camick's WrapLayout:
 * https://tips4java.wordpress.com/2008/11/06/wrap-layout/
 */
public class WrapLayout extends FlowLayout {

    public WrapLayout() {
        super(LEFT, 2, 2);
    }

    public WrapLayout(int align, int hgap, int vgap) {
        super(align, hgap, vgap);
    }

    @Override
    public Dimension preferredLayoutSize(Container target) {
        return layoutSize(target, true);
    }

    @Override
    public Dimension minimumLayoutSize(Container target) {
        Dimension minimum = layoutSize(target, false);
        minimum.width -= (getHgap() + 1);
        return minimum;
    }

    private Dimension layoutSize(Container target, boolean preferred) {
        synchronized (target.getTreeLock()) {
            // On the first pass the container has zero width — walk up until we find
            // a parent that already has a real size so wrapping is calculated correctly.
            int targetWidth = target.getSize().width;
            Container parent = target;
            while (targetWidth == 0 && parent.getParent() != null) {
                parent = parent.getParent();
                targetWidth = parent.getSize().width;
            }
            if (targetWidth == 0) {
                targetWidth = Integer.MAX_VALUE;
            }

            int hgap = getHgap();
            int vgap = getVgap();
            Insets insets = target.getInsets();
            int horizontalInsetsAndGap = insets.left + insets.right + (hgap * 2);
            int maxWidth = targetWidth - horizontalInsetsAndGap;

            Dimension dim = new Dimension(0, 0);
            int rowWidth  = 0;
            int rowHeight = 0;

            int count = target.getComponentCount();
            for (int i = 0; i < count; i++) {
                Component m = target.getComponent(i);
                if (!m.isVisible()) continue;

                Dimension d = preferred ? m.getPreferredSize() : m.getMinimumSize();

                if (rowWidth + d.width > maxWidth) {
                    addRow(dim, rowWidth, rowHeight);
                    rowWidth  = 0;
                    rowHeight = 0;
                }

                if (rowWidth != 0) rowWidth += hgap;
                rowWidth  += d.width;
                rowHeight  = Math.max(rowHeight, d.height);
            }
            addRow(dim, rowWidth, rowHeight);

            dim.width  += horizontalInsetsAndGap;
            dim.height += insets.top + insets.bottom + vgap * 2;
            return dim;
        }
    }

    private void addRow(Dimension dim, int rowWidth, int rowHeight) {
        dim.width = Math.max(dim.width, rowWidth);
        if (dim.height > 0) dim.height += getVgap();
        dim.height += rowHeight;
    }
}

