		getEventSubscribers().forEach(eventBus::register);
	}

	@Override
	protected void shutDown()
	{
		remote.removeListeners();
		menuManager.get().removePlayerMenuItem(COPY_PLAYER);
		clientThread.invokeLater(() -> fashionManager.shutDown());
		clientToolbar.removeNavigation(navButton);
		if (developerMode)
		{
			overlayManager.remove(debugOverlay);
		}
		getEventSubscribers().forEach(eventBus::unregister);
	}

	@Subscribe
	public void onPlayerChanged(PlayerChanged event)
	{
		Player player = event.getPlayer();
		if (player != null && player == client.getLocalPlayer())
		{
			fashionManager.onPlayerChanged();
			if (panel != null)
			{
				panel.onPlayerChanged(player);
			}
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		fashionManager.loadRSProfile();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(FashionscapeConfig.GROUP))
		{
			return;
		}
		if (event.getKey().equals(FashionscapeConfig.KEY_EXCLUDE_MEMBERS))
		{
			// reload displayed results
			clientThread.invokeLater(() -> {
				panel.reloadResults();
				panel.refreshKitsPanel();
				randomizer.repopulateMemo();
			});
		}
		else if (event.getKey().equals(FashionscapeConfig.KEY_IMPORT_MENU_ENTRY))
		{
			refreshMenuEntries();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			hasLoggedIn = true;
		}
		else if (hasLoggedIn && event.getGameState() == GameState.LOGIN_SCREEN)
		{
			layers.resetRealInfo();
			hasLoggedIn = false;
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getMenuAction() == MenuAction.RUNELITE_PLAYER && event.getMenuOption().equals(COPY_PLAYER))
		{
			Player p = client.getTopLevelWorldView().players().byIndex(event.getId());
			if (p == null)
			{
				return;
			}
			fashionManager.importPlayer(p);
			panel.reloadResults();
		}
	}

	private void refreshMenuEntries()
	{
		if (config.copyMenuEntry())
		{
			menuManager.get().addPlayerMenuItem(COPY_PLAYER);
		}
		else
		{
			menuManager.get().removePlayerMenuItem(COPY_PLAYER);
		}
	}

	// registers/unregisters these at startup/shutdown
	private List<Object> getEventSubscribers()
	{
		return ImmutableList.of(configHelper, panel);
	}

}

package eq.uirs.fashionscape.remote;

import com.google.gson.Gson;
import eq.uirs.fashionscape.colors.ItemColors;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.function.BiConsumer;
import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.CacheControl;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

// handles fetching colors and item slot data from raw GitHub urls
@Singleton
@Slf4j
public class RemoteDataHandler
{
	private static final String BASE_URL = "https://raw.githubusercontent.com/equirs/fashionscape-data/";
	private static final String BRANCH_PROD = "master";
	private static final String BRANCH_DEV = "dev";

	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final boolean developerMode;
	private final List<BiConsumer<RemoteCategory, Boolean>> onReceiveDataListeners = new ArrayList<>();

	@Inject
	RemoteDataHandler(OkHttpClient okHttpClient, Gson baseGson, @Named("developerMode") boolean developerMode)
	{
		this.okHttpClient = okHttpClient;
		this.developerMode = developerMode;
		this.gson = baseGson.newBuilder()
			.registerTypeAdapter(ItemColors.class, new ItemColors.Deserializer())
			.create();
	}

	final Set<RemoteCategory> failedCategories = new HashSet<>();
	final Set<RemoteCategory> successCategories = new HashSet<>();

	public boolean hasFailed()
	{
		return !failedCategories.isEmpty();
	}

	public boolean hasSucceeded(RemoteCategory category)
	{
		return successCategories.contains(category);
	}

	public void fetch()
	{
		for (RemoteCategory category : RemoteCategory.values())
		{
			fetch(category);
		}
	}

	private void fetch(RemoteCategory category)
	{
		HttpUrl url = Objects.requireNonNull(HttpUrl.parse(BASE_URL)).newBuilder()
			.addPathSegment(developerMode ? BRANCH_DEV : BRANCH_PROD)
			.addPathSegment(category.jsonFile())
			.build();
		Request.Builder builder = new Request.Builder();
		// forcibly skip the cache in dev-mode
		if (developerMode)
		{
			builder.cacheControl(CacheControl.FORCE_NETWORK);
		}
		Request request = builder.url(url).build();
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(@Nonnull Call call, @Nonnull IOException e)
			{
				onFail();
			}

			@Override
			public void onResponse(@Nonnull Call call, @Nonnull Response response)
			{
				ResponseBody body = response.body();
				if (body == null)
				{
					onFail();
				}
				else
				{
					successCategories.add(category);
					onSuccess(category, body);
					response.close();
					onReceiveDataListeners.forEach(b -> b.accept(category, true));
				}
			}

			private void onFail()
			{
				failedCategories.add(category);
				onReceiveDataListeners.forEach(b -> b.accept(category, false));
			}
		});
	}

	private void onSuccess(RemoteCategory category, ResponseBody body)
	{
		failedCategories.remove(category);
		Reader reader = new BufferedReader(new InputStreamReader(body.byteStream()));
		Type type = category.deserializedType();
		switch (category)
		{
			case SLOT:
				RemoteData.setItemInfo(gson.fromJson(reader, type));
				break;
			case COLOR:
				RemoteData.setColors(gson.fromJson(reader, type));
				break;
			case ANIMATION:
				RemoteData.setAnimations(gson.fromJson(reader, type));
				break;
			case MISC:
				RemoteData.setMiscData(gson.fromJson(reader, type));
				break;
		}
	}

	/**
	 * Adds a listener that will be called any time a request succeeds/fails for any category.
	 */
	public void addOnReceiveDataListener(BiConsumer<RemoteCategory, Boolean> listener)
	{
		onReceiveDataListeners.add(listener);
	}

	public void removeListeners()
	{
		onReceiveDataListeners.clear();
	}
}

package eq.uirs.fashionscape.remote;

import eq.uirs.fashionscape.colors.GenderItemColors;
import eq.uirs.fashionscape.data.ItemSlotInfo;
import eq.uirs.fashionscape.data.MiscData;
import eq.uirs.fashionscape.data.anim.AllAnimationData;
import eq.uirs.fashionscape.data.anim.AnimationData;
import java.util.Map;
import java.util.Queue;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;

public class RemoteData
{
	// item id -> equipped slot and hidden slots
	public static final Map<Integer, ItemSlotInfo> ITEM_ID_TO_INFO = new ConcurrentHashMap<>();
	public static final Map<Integer, GenderItemColors> ITEM_ID_TO_COLORS = new ConcurrentHashMap<>();
	public static final Queue<AnimationData> ANIM_DATA = new ConcurrentLinkedQueue<>();
	public static MiscData MISC_DATA = null;

	static void setItemInfo(Map<Integer, ItemSlotInfo> info)
	{
		ITEM_ID_TO_INFO.clear();
		ITEM_ID_TO_INFO.putAll(info);
	}

	static void setColors(Map<Integer, GenderItemColors> colors)
	{
		ITEM_ID_TO_COLORS.clear();
		ITEM_ID_TO_COLORS.putAll(colors);
	}

	static void setAnimations(AllAnimationData allData)
	{
		ANIM_DATA.clear();
		ANIM_DATA.addAll(allData.values);
	}

	static void setMiscData(MiscData miscData)
	{
		MISC_DATA = miscData;
	}
}

package eq.uirs.fashionscape.remote;

import com.google.gson.reflect.TypeToken;
import eq.uirs.fashionscape.colors.GenderItemColors;
import eq.uirs.fashionscape.data.ItemSlotInfo;
import eq.uirs.fashionscape.data.MiscData;
import eq.uirs.fashionscape.data.anim.AllAnimationData;
import java.lang.reflect.Type;
import java.util.Map;

public enum RemoteCategory
{
	SLOT, COLOR, ANIMATION, MISC;

	private static final String COLOR_JSON = "colors.json";
	private static final String SLOT_JSON = "slots.json";
	private static final String ANIM_JSON = "anims.json";
	private static final String MISC_JSON = "misc.json";

	String jsonFile()
	{
		switch (this)
		{
			case SLOT:
				return SLOT_JSON;
			case COLOR:
				return COLOR_JSON;
			case ANIMATION:
				return ANIM_JSON;
			case MISC:
				return MISC_JSON;
			default:
				return "";
		}
	}

	Type deserializedType()
	{
		switch (this)
		{
			case SLOT:
				//@formatter:off
				return new TypeToken<Map<Integer, ItemSlotInfo>>(){}.getType();
				//@formatter:on
			case COLOR:
				//@formatter:off
				return new TypeToken<Map<Integer, GenderItemColors>>(){}.getType();
				//@formatter:on
			case ANIMATION:
				return AllAnimationData.class;
			case MISC:
				return MiscData.class;
			default:
				return null;
		}
	}
}

