	public String getDisplayName()
	{
		switch (this)
		{
			case NO_JAW:
				return "";
			case CLEAN_SHAVEN:
				return "Clean-shaven";
			case LONG_J:
				return "Long";
			case MEDIUM_J:
				return "Medium";
			case SHORT_J:
				return "Short";
		}
		return Kit.sentenceCaseName(this);
	}

	@Nullable
	public Integer getIconItemId(JawIcon icon)
	{
		return icons.get(icon);
	}

	@Override
	public boolean isHidden()
	{
		return false;
	}
}

