/**
 * Special base panel handling BA/SW icons since they're tied to jaw kits
 */
@Slf4j
public class JawIconPanel extends DropdownIconPanel
{
	private final FashionManager fashionManager;
	private final ItemManager itemManager;
	private final KitColorOpener kitColorOpener;

	JawIconPanel(BufferedImage image, ClientThread clientThread, FashionManager fashionManager, ItemManager itemManager,
	             KitColorOpener kitColorOpener)
	{
		super(image, clientThread);
		this.fashionManager = fashionManager;
		this.itemManager = itemManager;
		this.kitColorOpener = kitColorOpener;

		JPanel rightPanel = new JPanel(new BorderLayout());
		rightPanel.setBackground(nonHighlightColor);
		rightPanel.setBorder(new EmptyBorder(0, 5, 0, 0));
		highlightPanels.add(rightPanel);
		rightPanel.add(label, BorderLayout.CENTER);

		JPanel buttons = new JPanel(new GridLayout(1, 2, 2, 0));
		buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		setIcon(icon, image);
		icon.setBorder(new RoundedBorder(ColorScheme.LIGHT_GRAY_COLOR, ICON_CORNER_RADIUS));

		configureButton(lockButton);
		lockButton.addActionListener(e -> fashionManager.toggleIconLocked());
		buttons.add(lockButton);

		configureButton(xButton);
		xButton.setIcon(PanelUtil.icon("x"));
		xButton.addActionListener(e -> clientThread.invokeLater(fashionManager::revertIcon));
		buttons.add(xButton);

		optionsContainer.setLayout(new BorderLayout());
		optionsContainer.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		optionsContainer.setVisible(false);
		add(optionsContainer, BorderLayout.SOUTH);
		rightPanel.add(buttons, BorderLayout.EAST);
		add(rightPanel, BorderLayout.CENTER);

		refreshData();
	}

	void onIconChanged(IconChanged e)
	{
		if (e.getModelType() == ModelType.VIRTUAL)
		{
			refreshData();
		}
	}

	void onIconLockChanged(IconLockChanged e)
	{
		updateLockButton();
	}

	private void refreshData()
	{
		setIconName();
		updateIconImage();
		setIconTooltip();
		updateLockButton();
		updateXButton();
	}

	@Override
	void openDropdown(MouseEvent e)
	{
		kitColorOpener.openOptions(null, null);
	}

	@Override
	void tryClear()
	{
		// clear the icon just as pressing the "x" button would
		clientThread.invokeLater(fashionManager::revertIcon);
	}

	public void openOptions()
	{
		optionsContainer.removeAll();
		if (optionsContainer.isVisible())
		{
			optionsContainer.setVisible(false);
			return;
		}
		else
		{
			optionsContainer.setVisible(true);
		}

		JPanel iconsList = new JPanel();
		iconsList.setLayout(new GridBagLayout());
		iconsList.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		iconsList.setBorder(new EmptyBorder(10, 0, 0, 0));
		GridBagConstraints c = new GridBagConstraints();
		c.fill = GridBagConstraints.HORIZONTAL;
		c.anchor = GridBagConstraints.LINE_START;
		c.weightx = 1;
		c.weighty = 1;
		c.gridx = 0;
		c.gridy = 0;

		for (JawIcon jawIcon : JawIcon.values())
		{
			JLabel iconLabel = createIconLabel(jawIcon);
			iconsList.add(iconLabel, c);
			c.gridy++;
		}
		optionsContainer.add(iconsList, BorderLayout.CENTER);
		optionsContainer.updateUI();
	}

	private JLabel createIconLabel(JawIcon jawIcon)
	{
		JLabel iconLabel = new JLabel();
		iconLabel.setBorder(new EmptyBorder(5, 5, 0, 5));
		iconLabel.setText(jawIcon.getDisplayName());
		iconLabel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (!fashionManager.isIconLocked())
				{
					setCursor(new Cursor(Cursor.HAND_CURSOR));
					fashionManager.hoverOverIcon(jawIcon);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				setCursor(new Cursor(Cursor.DEFAULT_CURSOR));
				fashionManager.hoverAway();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				fashionManager.hoverSelectIcon(jawIcon);
			}
		});
		return iconLabel;
	}

	public void closeOptions()
	{
		optionsContainer.removeAll();
		optionsContainer.setVisible(false);
	}

	private void setIconName()
	{
		String iconName = "Not set";
		JawIcon jawIcon = fashionManager.virtualIcon();
		if (jawIcon != null)
		{
			iconName = jawIcon.getDisplayName();
		}
		label.setText(iconName);
	}

	private void updateIconImage()
	{
		JawIcon jawIcon = fashionManager.virtualIcon();
		if (jawIcon != null && jawIcon != JawIcon.NOTHING)
		{
			clientThread.invokeLater(() -> {
				try
				{
					ItemComposition itemComposition = itemManager.getItemComposition(jawIcon.getId());
					AsyncBufferedImage image = itemManager.getImage(itemComposition.getId());
					image.addTo(icon);
				}
				catch (Exception e)
				{
					return false;
				}
				return true;
			});
		}
		else
		{
			BufferedImage image = ImageUtil.loadImageResource(getClass(), "icon.png");
			setIcon(icon, image);
		}
	}

	private void updateXButton()
	{
		JawIcon jawIcon = fashionManager.virtualIcon();
		xButton.setEnabled(jawIcon != null);
		xButton.setToolTipText("Clear icon");
	}

	private void updateLockButton()
	{
		PanelUtil.applyLockButton(lockButton, fashionManager.isIconLocked(), "icon");
	}

	private void setIconTooltip()
	{
		StringBuilder sb = new StringBuilder();
		sb.append("Icon");
		JawIcon jawIcon = fashionManager.virtualIcon();
		if (jawIcon != null)
		{
			if (sb.length() > 0)
			{
				sb.append(": ");
			}
			sb.append(jawIcon.getDisplayName().toLowerCase());
		}
		icon.setToolTipText(sb.toString());
	}
}

package eq.uirs.fashionscape.core.utils;

import java.util.Collections;
import java.util.List;
import java.util.Random;

public class ListUtil
{
	/**
	 * Takes n random elements from the given list and returns them as a sublist.
	 * Returns the original list if n >= list size.
	 * Note that this function rearranges the list argument's contents.
	 * Implementation is based on the Fisher-Yates shuffle algorithm.
	 */
	public static <T> List<T> takeRandomSample(List<T> list, int n, Random random)
	{
		int size = list.size();
		if (n >= size)
		{
			return list;
		}
		for (int i = size - 1; i >= size - n; i--)
		{
			Collections.swap(list, i, random.nextInt(i + 1));
		}
		return list.subList(size - n, size);
	}
}

package eq.uirs.fashionscape.core.utils;

import eq.uirs.fashionscape.data.ItemSlotInfo;
import eq.uirs.fashionscape.remote.RemoteData;
import javax.annotation.Nullable;
import net.runelite.api.kit.KitType;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

public class ItemSlotUtil
{
	// only call from client thread
	@Nullable
	public static KitType getSlot(int itemId, ItemManager itemManager)
	{
		// see if external data can be used first
		KitType[] allKits = KitType.values();
		ItemSlotInfo slotInfo = RemoteData.ITEM_ID_TO_INFO.get(itemId);
		if (slotInfo != null && slotInfo.slot >= 0 && slotInfo.slot < allKits.length)
		{
			return allKits[slotInfo.slot];
		}
		ItemStats itemStats = itemManager.getItemStats(itemId);
		if (itemStats == null)
		{
			return null;
		}
		ItemEquipmentStats equipmentStats = itemStats.getEquipment();
		if (equipmentStats == null)
		{
			return null;
		}
		int slotIndex = equipmentStats.getSlot();
		if (slotIndex < 0 || slotIndex >= allKits.length)
		{
			return null;
		}
		return allKits[slotIndex];
	}
}

package eq.uirs.fashionscape.core.utils;

import com.google.gson.Gson;
import java.lang.reflect.Type;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class ConfigSerializer
{
	private static final Charset CHARSET = StandardCharsets.UTF_8;
	private final Gson gson;

	@Inject
	ConfigSerializer(Gson gson)
	{
		this.gson = gson;
	}

	public byte[] serialize(Object object)
	{
		return gson.toJson(object).getBytes(CHARSET);
	}

	@Nullable
	public <T> T deserialize(@Nullable byte[] bytes, Type type)
	{
		if (bytes == null)
		{
			return null;
		}
		return gson.fromJson(new String(bytes, CHARSET), type);
	}
}

package eq.uirs.fashionscape.core.utils;

import java.util.Map;

public class MapUtil
{
	/**
	 * Adds contents of `other` to this `map` as long as all keys in `other` are not present in `map`.
	 */
	public static <K, V> void putAllIfAllAbsent(Map<K, V> map, Map<K, V> other)
	{
		for (K key : map.keySet())
		{
			if (other.containsKey(key))
			{
				return;
			}
		}
		map.putAll(other);
	}
}

package eq.uirs.fashionscape.core.utils;

import eq.uirs.fashionscape.data.kit.Kit;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.runelite.api.kit.KitType;

public class KitUtil
{
	public static final Map<Integer, Kit> KIT_ID_TO_KIT = new HashMap<>();
	public static final Map<KitType, List<Kit>> KIT_TYPE_TO_KITS;

	static
	{
		KIT_TYPE_TO_KITS = Arrays.stream(KitType.values())
			.collect(Collectors.toMap(s -> s, s -> Arrays.asList(Kit.allInSlot(s, true))));
		for (KitType slot : KitType.values())
		{
			for (Kit value : Kit.allInSlot(slot, true))
			{
				Integer mascId = value.getKitId(0);
				if (mascId != null)
				{
					KIT_ID_TO_KIT.put(mascId, value);
				}
				Integer femId = value.getKitId(1);
				if (femId != null)
				{
					KIT_ID_TO_KIT.put(femId, value);
				}
			}
		}
	}
}

package eq.uirs.fashionscape.core;

import eq.uirs.fashionscape.core.event.KnownKitChanged;
import eq.uirs.fashionscape.data.kit.ArmsKit;
import eq.uirs.fashionscape.data.kit.BootsKit;
import eq.uirs.fashionscape.data.kit.HairKit;
import eq.uirs.fashionscape.data.kit.HandsKit;
import eq.uirs.fashionscape.data.kit.JawKit;
import eq.uirs.fashionscape.data.kit.LegsKit;
import eq.uirs.fashionscape.data.kit.TorsoKit;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.kit.KitType;
import net.runelite.client.eventbus.EventBus;

// when real player kit info is not known, default values should be shown, otherwise models will look broken
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class Fallbacks
{
	// body type A in-game
	private static final Map<KitType, Integer> MASC_KITS = new HashMap<>();
	// body type B in-game
	private static final Map<KitType, Integer> FEM_KITS = new HashMap<>();

	private final EventBus eventBus;

	static
	{
		MASC_KITS.put(KitType.HAIR, HairKit.BALD.getKitId(0));
		MASC_KITS.put(KitType.JAW, JawKit.GOATEE.getKitId(0));
		MASC_KITS.put(KitType.TORSO, TorsoKit.PLAIN.getKitId(0));
		MASC_KITS.put(KitType.ARMS, ArmsKit.REGULAR.getKitId(0));
		MASC_KITS.put(KitType.LEGS, LegsKit.PLAIN_L.getKitId(0));
		MASC_KITS.put(KitType.HANDS, HandsKit.PLAIN_H.getKitId(0));
		MASC_KITS.put(KitType.BOOTS, BootsKit.SMALL.getKitId(0));

		FEM_KITS.put(KitType.HAIR, HairKit.PIGTAILS.getKitId(1));
		FEM_KITS.put(KitType.JAW, JawKit.CLEAN_SHAVEN.getKitId(1));
		FEM_KITS.put(KitType.TORSO, TorsoKit.SIMPLE.getKitId(1));
		FEM_KITS.put(KitType.ARMS, ArmsKit.REGULAR.getKitId(1));
		FEM_KITS.put(KitType.LEGS, LegsKit.PLAIN_L.getKitId(1));
		FEM_KITS.put(KitType.HANDS, HandsKit.PLAIN_H.getKitId(1));
		FEM_KITS.put(KitType.BOOTS, BootsKit.SMALL.getKitId(1));
	}

	/**
	 * Produces the fallback kit id for the given slot+gender.
	 * Returns an effective equipment id of 0 if there is no suitable kit id.
	 * If `detectUnknown`, the UI will update, prompting the user to reveal this kit.
	 */
	public int getKit(KitType slot, Integer gender, boolean detectUnknown)
	{
		if (gender == null || slot == null)
		{
			return -FashionManager.KIT_OFFSET;
		}
		Map<KitType, Integer> map = gender == 1 ? FEM_KITS : MASC_KITS;
		int result = map.getOrDefault(slot, -FashionManager.KIT_OFFSET);
		if (detectUnknown && result > 0)
		{
			eventBus.post(new KnownKitChanged(true, slot));
		}
		return result;
	}
}

package eq.uirs.fashionscape.core;

import eq.uirs.fashionscape.data.color.ColorType;
import eq.uirs.fashionscape.data.kit.JawIcon;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import lombok.AllArgsConstructor;
import lombok.Data;
import net.runelite.api.kit.KitType;

/**
 * Contains all virtual equipment changes in a single operation.
 * It's not a full snapshot of the player info; it only contains adds/removes.
 * A single operation could be simple, like changing/removing individual items/kits,
 * or it could be complex, like copying an entire outfit from another player.
 * "out" fields are removed whereas "in" fields are added
 */
@Data
@AllArgsConstructor
public class Diff
{
	Map<KitType, SlotInfo> outSlots;
	Map<KitType, SlotInfo> inSlots;
	Map<ColorType, Integer> outColors;
	Map<ColorType, Integer> inColors;
	JawIcon outIcon;
	JawIcon inIcon;

	public static Diff empty()
	{
		return new Diff(new HashMap<>(), new HashMap<>(), new HashMap<>(), new HashMap<>(), null, null);
	}

	public static Diff ofSlots(Map<KitType, SlotInfo> outSlots, Map<KitType, SlotInfo> inSlots)
	{
		return new Diff(outSlots, inSlots, new HashMap<>(), new HashMap<>(), null, null);
	}

	public static Diff ofColor(ColorType type, Integer outColor, Integer inColor)
	{
		if (Objects.equals(outColor, inColor))
		{
			return Diff.empty();
		}
		Map<ColorType, Integer> outColors = new HashMap<>();
		outColors.put(type, outColor);
		Map<ColorType, Integer> inColors = new HashMap<>();
		inColors.put(type, inColor);
		return new Diff(new HashMap<>(), new HashMap<>(), outColors, inColors, null, null);
	}

	public static Diff ofIcon(JawIcon outIcon, JawIcon inIcon)
	{
		return new Diff(new HashMap<>(), new HashMap<>(), new HashMap<>(), new HashMap<>(), outIcon, inIcon);
	}

	// In the event of a collision, first takes priority over second
	public static Diff merge(Diff first, Diff second)
	{
		Map<KitType, SlotInfo> outSlots = new HashMap<>(second.outSlots);
		outSlots.putAll(first.outSlots);
		Map<KitType, SlotInfo> inSlots = new HashMap<>(second.inSlots);
		inSlots.putAll(first.inSlots);
		Map<ColorType, Integer> outColors = new HashMap<>(second.outColors);
		outColors.putAll(first.outColors);
		Map<ColorType, Integer> inColors = new HashMap<>(second.inColors);
		inColors.putAll(first.inColors);
		JawIcon outIcon = first.outIcon != null ? first.outIcon : second.outIcon;
		JawIcon inIcon = first.inIcon != null ? first.inIcon : second.inIcon;
		return new Diff(outSlots, inSlots, outColors, inColors, outIcon, inIcon);
	}

	public boolean isEmpty()
	{
		return equals(Diff.empty());
	}
}

package eq.uirs.fashionscape.core;

import eq.uirs.fashionscape.data.anim.AnimationData;
import eq.uirs.fashionscape.remote.RemoteData;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;

/**
 * Builds mappings of weapon ids to idle pose animation ids.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class IdleAnimations
{
	// standard for unarmed and most equipment
	public static final int DEFAULT = 808;

	private final ScheduledExecutorService executorService;

	private final Map<Integer, Integer> itemIdToAnim = new HashMap<>();

	@Nullable
	public Integer get(Integer itemId)
	{
		return itemId == null ? null : itemIdToAnim.get(itemId);
	}

	/**
	 * Queues a (weapon-slot) item to determine its idle anim id.
	 * Since this process can be quite slow (many regex/string matches), it's done in the background.
	 * This should only be called from the client thread, after the anims json has been fetched.
	 */
	public void queue(ItemComposition composition)
	{
		int itemId = composition.getId();
		String itemName = composition.getMembersName().toLowerCase();
		executorService.execute(() -> findAnimation(itemId, itemName));
	}

	private void findAnimation(int itemId, String itemName)
	{
		RemoteData.ANIM_DATA.stream()
			.filter(info -> isMatch(info, itemId, itemName))
			.findFirst()
			.ifPresent(info -> itemIdToAnim.put(itemId, info.animId));
	}

	private boolean isMatch(AnimationData info, int itemId, String itemName)
	{
		if (info.itemIds != null && info.itemIds.contains(itemId))
		{
			return true;
		}
		if (info.exactMatches != null && info.exactMatches.contains(itemName))
		{
			return true;
		}
		List<String> containsMatches = info.containsMatches;
		if (containsMatches != null && containsMatches.stream().anyMatch(itemName::contains))
		{
			return true;
		}
		List<String> regexMatches = info.regexMatches;
		if (regexMatches != null)
		{
			return regexMatches.stream()
				.map(Pattern::compile)
				.anyMatch(p -> p.matcher(itemName).find());
		}
		return false;
	}
}

package eq.uirs.fashionscape.core;

import com.google.common.collect.ImmutableSet;
import eq.uirs.fashionscape.FashionscapeConfig;
import eq.uirs.fashionscape.core.utils.ItemSlotUtil;
import eq.uirs.fashionscape.data.MiscData;
import eq.uirs.fashionscape.data.kit.BootsKit;
import eq.uirs.fashionscape.remote.RemoteData;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.kit.KitType;
import net.runelite.client.game.ItemManager;

/**
 * Builds sets of items to filter out (glitched items, duplicates, potentially members-only)
 */
@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class Exclusions
{
	private static final Pattern PAREN_REPLACE = Pattern.compile("\\(.*\\)");
	/**
	 * kit ids of boot-slot equipment that, when detected in-game, will disable the boots, weapon and shield slots
	 */
	public static final Set<Integer> DISABLE_ANIM_BOOTS = ImmutableSet.of(BootsKit.MINECART.getKitId(0),
		BootsKit.MINECART.getKitId(1));

	private final Set<Integer> bad = new HashSet<>();
	private final Set<Integer> dupes = new HashSet<>();
	private final Set<Integer> members = new HashSet<>();

	private final Client client;
	private final ItemManager itemManager;
	private final FashionscapeConfig config;
	private final IdleAnimations idleAnimations;

	@Value
	private static class ItemDupeData
	{
		int modelId;
		short[] colorsToReplace;
		short[] texturesToReplace;
		String strippedName;
	}

	/**
	 * populates excluded items after remote data is fetched.
	 * @return false if client doesn't have items populated
	 */
	public boolean loadAll()
	{
		// item count will be 0 if cache is not ready yet
		if (client.getItemCount() == 0)
		{
			return false;
		}
		// plugin checks for the presence of this before calling
		MiscData miscData = RemoteData.MISC_DATA;
		bad.addAll(miscData.badItemIds);
		miscData.badItemRanges.forEach(range -> {
			IntStream.range(range.startInclusive, range.endInclusive + 1)
				.forEach(bad::add);
		});
		List<Pattern> badRegexes = miscData.badItemRegexes.stream()
			.map(Pattern::compile)
			.collect(Collectors.toList());
		Set<ItemDupeData> itemUniques = new HashSet<>();
		for (int i = 0; i < client.getItemCount(); i++)
		{
			int canonical = itemManager.canonicalize(i);
			if (i != canonical || bad.contains(canonical))
			{
				continue;
			}
			KitType slot = ItemSlotUtil.getSlot(i, itemManager);
			if (slot != null)
			{
				ItemComposition itemComposition = itemManager.getItemComposition(canonical);
				if (slot == KitType.WEAPON)
				{
					idleAnimations.queue(itemComposition);
				}
				if (itemComposition.isMembers())
				{
					members.add(i);
				}
				String itemName = itemComposition.getMembersName().toLowerCase();
				if (miscData.badItemNames.contains(itemName))
				{
					bad.add(i);
					continue;
				}
				boolean foundBadContains = miscData.badItemContains.stream()
					.anyMatch(itemName::contains);
				if (foundBadContains)
				{
					bad.add(i);
					continue;
				}
				boolean foundBadRegex = badRegexes.stream()
					.anyMatch(regex -> regex.matcher(itemName).find());
				if (foundBadRegex)
				{
					bad.add(i);
					continue;
				}
				ItemDupeData itemDupeData = new ItemDupeData(
					itemComposition.getInventoryModel(),
					itemComposition.getColorToReplaceWith(),
					itemComposition.getTextureToReplaceWith(),
					stripName(itemName)
				);
				if (itemUniques.contains(itemDupeData))
				{
					dupes.add(canonical);
					continue;
				}
				itemUniques.add(itemDupeData);
			}
		}
		return true;
	}

	public Set<Integer> getAll()
	{
		Set<Integer> result = new HashSet<>(bad);
		result.addAll(dupes);
		if (config.excludeMembersItems())
		{
			result.addAll(members);
		}
		return result;
	}

	private String stripName(String name)
	{
		String noParens = PAREN_REPLACE.matcher(name).replaceAll("");
		return noParens.replaceAll("[^A-Za-z]+", "");
	}
}

package eq.uirs.fashionscape.core;

import eq.uirs.fashionscape.data.ItemSlotInfo;
import eq.uirs.fashionscape.data.kit.Kit;
import eq.uirs.fashionscape.remote.RemoteData;
import java.io.Serializable;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.NonNull;
import lombok.Value;
import net.runelite.api.kit.KitType;

/**
 * Collected data about the occupant of a single slot.
 * An instance may be an item, a kit, or nothing.
 */
@Value
public class SlotInfo implements Serializable
{
	int equipmentId;
	@NonNull
	KitType slot;
	// for items: hidden info is determined from wearpos values from cache
	@NonNull
	Set<KitType> hidden;

	public static SlotInfo item(int itemId, KitType slot, KitType... hidden)
	{
		return new SlotInfo(itemId + FashionManager.ITEM_OFFSET, slot,
			Arrays.stream(hidden).collect(Collectors.toSet()));
	}

	public static SlotInfo kit(Kit k, int gender)
	{
		return kit(k.getKitId(gender), k.getKitType());
	}

	public static SlotInfo kit(int kitId, KitType slot)
	{
		return new SlotInfo(kitId + FashionManager.KIT_OFFSET, slot, new HashSet<>());
	}

	public static SlotInfo nothing(KitType slot)
	{
		return new SlotInfo(0, slot, new HashSet<>());
	}

	/**
	 * Most general way to create new SlotInfo.
	 * Uses ExternalData to look up hidden slots in the case of items.
	 * Ensure that jaw slot items are converted to kit ids before calling, and that icon is handled separately.
	 */
	public static SlotInfo lookUp(int equipId, KitType slot)
	{
		if (equipId <= FashionManager.KIT_OFFSET)
		{
			return nothing(slot);
		}
		else if (equipId <= FashionManager.ITEM_OFFSET)
		{
			return kit(equipId - FashionManager.KIT_OFFSET, slot);
		}
		else
		{
			int itemId = equipId - FashionManager.ITEM_OFFSET;
			Map<Integer, ItemSlotInfo> idToSlotInfo = RemoteData.ITEM_ID_TO_INFO;
			ItemSlotInfo info = idToSlotInfo.get(itemId);
			if (info == null || info.hidden0 == null && info.hidden1 == null)
			{
				return item(itemId, slot);
			}
			KitType[] types = KitType.values();
			Set<KitType> hidden = new HashSet<>();
			if (info.hidden0 != null)
			{
				hidden.add(types[info.hidden0]);
			}
			if (info.hidden1 != null)
			{
				hidden.add(types[info.hidden1]);
			}
			return new SlotInfo(itemId + FashionManager.ITEM_OFFSET, slot, hidden);
		}
	}

	public int getItemId()
	{
		return equipmentId - FashionManager.ITEM_OFFSET;
	}

	public int getKitId()
	{
		return equipmentId - FashionManager.KIT_OFFSET;
	}

	public boolean isItem()
	{
		return equipmentId >= FashionManager.ITEM_OFFSET;
	}

	public boolean isKit()
	{
		return equipmentId >= FashionManager.KIT_OFFSET && equipmentId < FashionManager.ITEM_OFFSET;
	}

	public boolean isNothing()
	{
		return equipmentId == 0;
	}

	// whether the given slot is hidden while this model is active
	public boolean hides(KitType kit)
	{
		return hidden.contains(kit);
	}

	public Map<KitType, Integer> computeEquipment()
	{
		Map<KitType, Integer> result = new HashMap<>();
		result.put(slot, equipmentId);
		hidden.forEach(s -> result.put(s, 0));
		return result;
	}
}

package eq.uirs.fashionscape.core;

import com.google.common.collect.ImmutableList;
import eq.uirs.fashionscape.core.layer.Layers;
import eq.uirs.fashionscape.core.layer.Locks;
import eq.uirs.fashionscape.core.randomizer.Randomizer;
import eq.uirs.fashionscape.data.color.ColorType;
import eq.uirs.fashionscape.data.kit.JawIcon;
import eq.uirs.fashionscape.remote.RemoteCategory;
import eq.uirs.fashionscape.remote.RemoteDataHandler;
import java.util.List;
import java.util.Objects;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.kit.KitType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;

/**
 * Singleton entry point into fashionscape internals. The "brains" of the plugin.
 * Coordinates with other classes with more specific responsibilities.
 * Most of the UI should be going through this class, especially if undo/redo is desired.
 */
@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class FashionManager
{
	// item-only slots that can safely contain an equipment id of 0
	public static final List<KitType> ALLOWS_NOTHING_ITEMS = ImmutableList.of(KitType.HEAD, KitType.CAPE, KitType.AMULET,
		KitType.WEAPON, KitType.SHIELD);
	// slots which allow an equipment id of 0 when an item obscures it (hands/boots are possible but very rare)
	public static final List<KitType> ALLOWS_NOTHING_KITS = ImmutableList.of(KitType.HAIR, KitType.JAW, KitType.ARMS,
		KitType.HANDS, KitType.BOOTS);
	public static final int ITEM_OFFSET = PlayerComposition.ITEM_OFFSET;
	public static final int KIT_OFFSET = PlayerComposition.KIT_OFFSET;

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;

	@Getter
	private final Exporter exporter;

	@Getter
	private final Layers layers;

	@Getter
	private final Locks locks;

	private final History history;
	private final Randomizer randomizer;
	private final Exclusions exclusions;
	private final ConfigHelper configHelper;
	private final RemoteDataHandler remote;
	private final CompositionHelper compositionHelper;

	private boolean receivedDataAsync = false;
	private String lastKnownRSProfileKey = null;

	public void startUp()
	{
		if (hasFetchedRequiredData())
		{
			startUpPostFetch();
		}
		else
		{
			remote.addOnReceiveDataListener((c, s) -> {
				// prevents unintended duplicate calls. on subsequent starts, external::hasSucceeded will be true
				if (receivedDataAsync)
				{
					return;
				}
				if (hasFetchedRequiredData())
				{
					receivedDataAsync = true;
					startUpPostFetch();
				}
			});
		}
	}

	private boolean hasFetchedRequiredData()
	{
		return remote.hasSucceeded(RemoteCategory.SLOT) && remote.hasSucceeded(RemoteCategory.MISC);
	}

	private void startUpPostFetch()
	{
		clientThread.invokeLater(() -> {
			if (!exclusions.loadAll())
			{
				return false;
			}
			configHelper.migrateEquipmentInfo();
			doPreRefreshCheck();
			configHelper.loadFromConfig();
			refreshPlayer();
			return true;
		});
	}

	public void shutDown()
	{
		layers.revertToRealModels(client.getLocalPlayer());
	}

	public void onPlayerChanged()
	{
		doPreRefreshCheck();
		configHelper.loadFromConfig();
		refreshPlayer();
	}

	public void loadRSProfile()
	{
		configHelper.loadRSProfileConfig();
	}

	public boolean isSlotLocked(KitType slot)
	{
		return locks.get(slot) != null;
	}

	public boolean isKitLocked(KitType slot)
	{
		return locks.get(slot) == LockStatus.ALL;
	}

	// Note: this isn't a reliable check for whether an item can occupy this slot, due to other slot interactions
	public boolean isItemLocked(KitType slot)
	{
		return isSlotLocked(slot);
	}

	public boolean isColorLocked(ColorType type)
	{
		return locks.getColor(type);
	}

	public boolean isIconLocked()
	{
		return locks.isIcon();
	}

	public void toggleItemLocked(KitType slot)
	{
		locks.toggle(slot, LockStatus.ITEM);
	}

	public void toggleKitLocked(KitType slot)
	{
		locks.toggle(slot, LockStatus.ALL);
	}

	public void toggleColorLocked(ColorType type)
	{
		locks.toggle(type);
	}

	public void toggleIconLocked()
	{
		locks.toggleIcon();
	}

	public void shuffle()
	{
		history.append(randomizer.shuffle());
		refreshPlayer();
	}

	public void importSelf()
	{
		// first clear everything (without messing with layers) so that the imports derive from real models
		clientThread.invokeLater(() -> {
			layers.revertToRealModels(client.getLocalPlayer());
			importPlayer(client.getLocalPlayer());
		});
	}

	public void importPlayer(@Nullable Player player)
	{
		PlayerComposition composition = compositionHelper.get(player);
		if (composition == null)
		{
			return;
		}
		exporter.importPlayer(composition);
		clientThread.invokeLater(this::refreshPlayer);
	}

	// this should only be called from the client thread
	public void refreshPlayer()
	{
		Player player = client.getLocalPlayer();
		PlayerComposition composition = compositionHelper.getLocal();
		if (player == null || composition == null)
		{
			return;
		}
		int[] equipIds = layers.computeEquipment();
		for (int i = 0; i < equipIds.length; i++)
		{
			composition.getEquipmentIds()[i] = equipIds[i];
		}
		Integer poseAnim = layers.computeIdlePoseAnimation();
		if (poseAnim != null)
		{
			player.setIdlePoseAnimation(poseAnim);
		}
		int[] colors = layers.computeColors();
		for (int i = 0; i < colors.length; i++)
		{
			composition.getColors()[i] = colors[i];
		}
		composition.setHash();
	}

	/**
	 * Undoes the last action performed.
	 * Can only be called from the client thread.
	 */
	public void undo()
	{
		history.undo();
		refreshPlayer();
	}

	public boolean canUndo()
	{
		return history.undoSize() > 0;
	}

	/**
	 * Redoes the last action that was undone.
	 * Can only be called from the client thread.
	 */
	public void redo()
	{
		history.redo();
		refreshPlayer();
	}

	public boolean canRedo()
	{
		return history.redoSize() > 0;
	}

	public void doPreRefreshCheck()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		PlayerComposition composition = compositionHelper.getLocal();
		layers.deriveNonEquipment(composition, player.getIdlePoseAnimation());
		String profileKey = configManager.getRSProfileKey();
		if (!Objects.equals(lastKnownRSProfileKey, profileKey))
		{
			lastKnownRSProfileKey = profileKey;
			configHelper.loadRSProfileConfig();
		}
		if (remote.hasSucceeded(RemoteCategory.SLOT))
		{
			layers.deriveEquipment(composition);
		}
	}

	@Nullable
	public Integer virtualItemIdFor(KitType slot)
	{
		SlotInfo info = layers.getVirtualModels().getItems().get(slot);
		return info == null ? null : info.getItemId();
	}

	@Nullable
	public Integer virtualKitIdFor(KitType slot)
	{
		return layers.getVirtualModels().getKits().get(slot);
	}

	@Nullable
	public Integer virtualColorIdFor(ColorType type)
	{
		return layers.getVirtualModels().getColors().get(type);
	}

	public List<WeaponAnimMismatch> getWeaponAnimMismatches()
	{
		return layers.getWeaponAnimMismatches();
	}

	@Nullable
	public JawIcon virtualIcon()
	{
		return layers.getVirtualModels().getIcon();
	}

	public boolean isNothing(KitType slot)
	{
		SlotInfo info = layers.getVirtualModels().getItems().get(slot);
		return Objects.equals(info, SlotInfo.nothing(slot));
	}

	// this should only be called from the client thread
	public void revert(KitType slot, ColorType type)
	{
		Diff diff = Diff.empty();
		if (slot != null)
		{
			locks.set(slot, null);
			diff = Diff.merge(layers.set(slot, null, false), diff);
		}
		if (type != null)
		{
			locks.set(type, false);
			diff = Diff.merge(layers.setColor(type, null, false), diff);
		}
		history.append(diff);
		refreshPlayer();
	}

	// this should only be called from the client thread
	public void revertSlot(KitType slot)
	{
		locks.set(slot, null);
		Diff diff = layers.set(slot, null, false);
		history.append(diff);
		refreshPlayer();
	}

	// this should only be called from the client thread
	public void revertIcon()
	{
		locks.setIcon(false);
		Diff diff = layers.setIcon(null, false);
		history.append(diff);
		refreshPlayer();
	}

	public void hoverOverItem(KitType slot, int itemId)
	{
		SlotInfo info = itemId < 0 ? SlotInfo.nothing(slot) : SlotInfo.lookUp(itemId + ITEM_OFFSET, slot);
		if (locks.isAllowed(slot, info))
		{
			layers.set(slot, info, true);
			clientThread.invokeLater(this::refreshPlayer);
		}
	}

	public void hoverOverKit(KitType slot, int kitId)
	{
		SlotInfo info = SlotInfo.kit(kitId, slot);
		if (!isKitLocked(slot))
		{
			layers.set(slot, info, true);
			clientThread.invokeLater(this::refreshPlayer);
		}
	}

	public void hoverOverColor(ColorType type, Integer colorId)
	{
		layers.setColor(type, colorId, true);
		clientThread.invokeLater(this::refreshPlayer);
	}

	public void hoverOverIcon(JawIcon icon)
	{
		layers.setIcon(icon, true);
		clientThread.invokeLater(this::refreshPlayer);
	}

	public void hoverSelectItem(KitType slot, Integer itemId)
	{
		SlotInfo info = itemId < 0 ?
			SlotInfo.nothing(slot) : SlotInfo.lookUp(itemId + ITEM_OFFSET, slot);
		if (!locks.isAllowed(slot, info))
		{
			return;
		}
		layers.resetPreview();
		SlotInfo existing = layers.getVirtualModels().getItems().get(slot);
		// if re-selecting, clear the virtual slot
		SlotInfo finalInfo = Objects.equals(info, existing) ? null : info;
		Diff diff = layers.set(slot, finalInfo, false);
		history.append(diff);
		clientThread.invokeLater(this::refreshPlayer);
	}

	public void hoverSelectKit(KitType slot, int kitId)
	{
		SlotInfo info = SlotInfo.kit(kitId, slot);
		if (!locks.isAllowed(slot, info))
		{
			return;
		}
		layers.resetPreview();
		Integer existingId = layers.getVirtualModels().getKits().get(slot);
		// if re-selecting, clear the virtual slot
		SlotInfo finalInfo = Objects.equals(info.getKitId(), existingId) ? null : info;
		Diff diff = layers.set(slot, finalInfo, false);
		history.append(diff);
		clientThread.invokeLater(this::refreshPlayer);
	}

	public void hoverSelectColor(ColorType type, Integer colorId)
	{
		if (locks.getColor(type))
		{
			return;
		}
		layers.resetPreview();
		Integer existingId = layers.getVirtualModels().getColors().get(type);
		// if re-selecting, clear the virtual color
		Integer finalId = Objects.equals(colorId, existingId) ? null : colorId;
		Diff diff = layers.setColor(type, finalId, false);
		history.append(diff);
		clientThread.invokeLater(this::refreshPlayer);
	}

	public void hoverSelectIcon(JawIcon icon)
	{
		if (locks.isIcon())
		{
			return;
		}
		layers.resetPreview();
		JawIcon existingIcon = layers.getVirtualModels().getIcon();
		// if re-selecting, clear the virtual icon
		JawIcon finalIcon = Objects.equals(icon, existingIcon) ? null : icon;
		Diff diff = layers.setIcon(finalIcon, false);
		history.append(diff);
		clientThread.invokeLater(this::refreshPlayer);
	}

	public void hoverAway()
	{
		layers.resetPreview();
		clientThread.invokeLater(this::refreshPlayer);
	}

	public void clear(boolean removeLocks)
	{
		Diff diff = revertVirtualModels(removeLocks);
		history.append(diff);
		refreshPlayer();
	}

	/**
	 * In the event that slot data fails to fetch, users can clear out certain kit models themselves this way.
	 * If the slot is already set to "nothing", reverts to "not set"
	 */
	public void overrideKitWithNothing(KitType slot)
	{
		if (slot == null || !ALLOWS_NOTHING_KITS.contains(slot))
		{
			return;
		}
		SlotInfo oldInfo = layers.getVirtualModels().getItems().get(slot);
		boolean alreadyHasNothing = oldInfo != null && oldInfo.isNothing();
		SlotInfo newInfo = alreadyHasNothing ? null : SlotInfo.nothing(slot);
		Diff diff = layers.set(slot, newInfo, false);
		history.append(diff);
		refreshPlayer();
	}

	/**
	 * Reverts all item/kit slots, colors, and icon.
	 * Unless `removeLocks` is true, locked slots will remain.
	 * This can only be called on the client thread.
	 */
	private Diff revertVirtualModels(boolean removeLocks)
	{
		if (removeLocks)
		{
			locks.clear();
		}
		Diff diff = Diff.empty();
		for (KitType slot : KitType.values())
		{
			if (locks.isAllowed(slot, null))
			{
				diff = Diff.merge(layers.set(slot, null, false), diff);
			}
		}
		for (ColorType type : ColorType.values())
		{
			if (!locks.getColor(type))
			{
				diff = Diff.merge(layers.setColor(type, null, false), diff);
			}
		}
		if (!locks.isIcon())
		{
			diff = Diff.merge(layers.setIcon(null, false), diff);
		}
		return diff;
	}
}

package eq.uirs.fashionscape.core;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;

/**
 * Because fashionscape only operates on non-transformed players,
 * calls to get players' compositions is wrapped in this class,
 * which discards compositions if there's a non-default TransformedNpcId.
 */
@Singleton
@Slf4j
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class CompositionHelper
{
	private final Client client;

	@Nullable
	public PlayerComposition getLocal()
	{
		return get(client.getLocalPlayer());
	}

	public PlayerComposition get(@Nullable Player player)
	{
		if (player == null)
		{
			return null;
		}
		PlayerComposition composition = player.getPlayerComposition();
		if (composition == null || composition.getTransformedNpcId() != -1)
		{
			return null;
		}
		return composition;
	}
}

package eq.uirs.fashionscape.core;

// Locked slots must either limit only the item, or both kit+item
public enum LockStatus
{
	ITEM,
	ALL
}

package eq.uirs.fashionscape.core.model;

import eq.uirs.fashionscape.core.event.IconChanged;
import eq.uirs.fashionscape.core.layer.ModelType;
import eq.uirs.fashionscape.data.kit.JawIcon;
import javax.annotation.Nullable;
import lombok.Data;
import net.runelite.api.kit.KitType;
import net.runelite.client.eventbus.EventBus;

/**
 * Combined representation of all fashionscape-related model state: items, kits, colors, and icon.
 * Each ModelType maps to one instance of ModelInfo.
 */
@Data
public class ModelInfo
{
	private final Items items;
	private final Kits kits;
	private final Colors colors;
	@Nullable
	private JawIcon icon;

	private final ModelType modelType;
	private final EventBus eventBus;

	public ModelInfo(ModelType modelType, EventBus eventBus)
	{
		items = new Items(modelType, eventBus);
		kits = new Kits(modelType, eventBus);
		colors = new Colors(modelType, eventBus);
		this.eventBus = eventBus;
		this.modelType = modelType;
	}

	public JawIcon putIcon(@Nullable JawIcon icon)
	{
		JawIcon oldIcon = this.icon;
		this.icon = icon;
		eventBus.post(new IconChanged(icon, modelType));
		return oldIcon;
	}

	public boolean contains(KitType slot)
	{
		return items.containsKey(slot) || kits.containsKey(slot);
	}
}

package eq.uirs.fashionscape.core.model;

import com.google.common.collect.ImmutableMap;
import eq.uirs.fashionscape.core.SlotInfo;
import eq.uirs.fashionscape.core.event.ItemChanged;
import eq.uirs.fashionscape.core.layer.ModelType;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Getter;
import net.runelite.api.kit.KitType;
import net.runelite.client.eventbus.EventBus;

/**
 * State for each equipment slot, which can contain an item, "nothing", or be unset.
 * Kit ids are stored separately (in Kits class) because of potential overlap.
 */
@Data
@Getter(AccessLevel.PRIVATE)
public class Items
{
	private final ModelType modelType;
	private final EventBus eventBus;
	private final Map<KitType, SlotInfo> value = new HashMap<>();

	public ImmutableMap<KitType, SlotInfo> getAll()
	{
		return ImmutableMap.copyOf(value);
	}

	@Nullable
	public SlotInfo get(KitType slot)
	{
		return value.get(slot);
	}

	public boolean containsKey(KitType slot)
	{
		return get(slot) != null;
	}

	public SlotInfo remove(KitType slot)
	{
		return put(slot, null);
	}

	@Nullable
	public SlotInfo put(KitType slot, @Nullable SlotInfo info)
	{
		SlotInfo oldInfo = info == null ? value.remove(slot) : value.put(slot, info);
		eventBus.post(new ItemChanged(slot, modelType, info));
		return oldInfo;
	}

	public void putAll(Map<KitType, SlotInfo> other)
	{
		other.forEach(this::put);
	}

	public void clear()
	{
		Set<KitType> removes = new HashSet<>(value.keySet());
		removes.forEach(this::remove);
	}
}

package eq.uirs.fashionscape.core.model;

import com.google.common.collect.ImmutableMap;
import eq.uirs.fashionscape.core.event.ColorChanged;
import eq.uirs.fashionscape.core.layer.ModelType;
import eq.uirs.fashionscape.data.color.BootsColor;
import eq.uirs.fashionscape.data.color.ClothingColor;
import eq.uirs.fashionscape.data.color.ColorType;
import eq.uirs.fashionscape.data.color.Colorable;
import eq.uirs.fashionscape.data.color.HairColor;
import eq.uirs.fashionscape.data.color.SkinColor;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.BiFunction;
import java.util.stream.Collectors;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Setter;
import net.runelite.client.eventbus.EventBus;

/**
 * State for each color-able model on the player.
 */
@Data
@Setter(AccessLevel.PRIVATE)
public class Colors
{
	private final ModelType modelType;
	private final EventBus eventBus;
	// values are color ids, not rgb ints; see Colorable interface
	private final Map<ColorType, Integer> value = new HashMap<>();

	public ImmutableMap<ColorType, Integer> getAll()
	{
		return ImmutableMap.copyOf(value);
	}

	public Map<ColorType, Colorable> getAllColorable()
	{
		BiFunction<ColorType, Integer, Colorable> getColor = (type, id) -> {
			switch (type)
			{
				case HAIR:
					return HairColor.fromId(id);
				case TORSO:
					return ClothingColor.fromTorsoId(id);
				case LEGS:
					return ClothingColor.fromLegsId(id);
				case BOOTS:
					return BootsColor.fromId(id);
				case SKIN:
					return SkinColor.fromId(id);
			}
			return null;
		};
		return Arrays.stream(ColorType.values())
			.filter(value::containsKey)
			.collect(Collectors.toMap(t -> t, t -> getColor.apply(t, get(t))));
	}

	public Integer get(ColorType slot)
	{
		return value.get(slot);
	}

	public Integer remove(ColorType slot)
	{
		return put(slot, null);
	}

	public Integer put(ColorType slot, Integer colorId)
	{
		Integer oldId = colorId == null ? value.remove(slot) : value.put(slot, colorId);
		eventBus.post(new ColorChanged(slot, modelType, colorId));
		return oldId;
	}

	public void putAll(Map<ColorType, Integer> other)
	{
		other.forEach(this::put);
	}

	public void clear()
	{
		Set<ColorType> removes = new HashSet<>(value.keySet());
		removes.forEach(this::remove);
	}
}

package eq.uirs.fashionscape.core.model;

import com.google.common.collect.ImmutableMap;
import eq.uirs.fashionscape.core.FashionManager;
import eq.uirs.fashionscape.core.event.KitChanged;
import eq.uirs.fashionscape.core.layer.ModelType;
import eq.uirs.fashionscape.core.utils.KitUtil;
import eq.uirs.fashionscape.data.kit.JawIcon;
import eq.uirs.fashionscape.data.kit.JawKit;
import eq.uirs.fashionscape.data.kit.Kit;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Setter;
import net.runelite.api.kit.KitType;
import net.runelite.client.eventbus.EventBus;

/**
 * State for each built-in kit model on the player.
 * Values are kit ids. Zero is not allowed (Items class handles "nothing").
 * These may remain in place even if any equipped items obscure the models, since items take priority.
 */
@Data
@Setter(AccessLevel.PRIVATE)
public class Kits
{
	private final ModelType modelType;
	private final EventBus eventBus;
	// values are kit ids
	private final Map<KitType, Integer> value = new HashMap<>();

	public ImmutableMap<KitType, Integer> getAll()
	{
		return ImmutableMap.copyOf(value);
	}

	public Integer get(KitType slot)
	{
		return value.get(slot);
	}

	public boolean containsKey(KitType slot)
	{
		return get(slot) != null;
	}

	public Integer remove(KitType slot)
	{
		return put(slot, null);
	}

	public Integer put(KitType slot, Integer kitId)
	{
		Integer oldId = kitId == null ? value.remove(slot) : value.put(slot, kitId);
		eventBus.post(new KitChanged(slot, modelType, kitId));
		return oldId;
	}

	public void clear()
	{
		Set<KitType> removes = new HashSet<>(value.keySet());
		removes.forEach(this::remove);
	}

	/**
	 * Replaces any stored kit ids with new ones for the given gender.
	 * If `destructive`, the wrongly-gendered kits will be removed.
	 * Otherwise, will attempt to replace the kit id with an analog kit id.
	 */
	public void setGender(int gender, boolean destructive)
	{
		for (KitType slot : KitType.values())
		{
			replaceGenderedKit(slot, gender, destructive);
		}
	}

	private void replaceGenderedKit(KitType slot, int newGender, boolean destructive)
	{
		Integer kitId = get(slot);
		if (kitId != null)
		{
			// check whether the kit is already correct for this gender
			Kit kit = KitUtil.KIT_ID_TO_KIT.get(kitId);
			if (kit != null && Objects.equals(kit.getKitId(newGender), kitId))
			{
				return;
			}
		}
		else
		{
			// nothing in the slot -> no need to replace
			return;
		}
		if (destructive)
		{
			put(slot, null);
		}
		else
		{
			Kit kit = KitUtil.KIT_ID_TO_KIT.get(kitId);
			Integer newKitId = kit != null ? kit.getKitId(newGender) : null;
			put(slot, newKitId);
		}
	}

	/**
	 * Returns map of equipment ids for each slot. The jaw slot will combine with the icon argument.
	 */
	public Map<KitType, Integer> computeEquipment(@Nullable JawIcon icon)
	{
		return value.entrySet().stream()
			.collect(Collectors.toMap(Map.Entry::getKey, e -> {
				KitType slot = e.getKey();
				Integer kitId = e.getValue();
				return slot == KitType.JAW ? JawKit.getEquipmentId(kitId, icon) : kitId + FashionManager.KIT_OFFSET;
			}));
	}
}

