/**
 * Deals with saving/loading fashionscape to local files
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class Exporter
{
	public static final File OUTFITS_DIR = new File(RuneLite.RUNELITE_DIR, "outfits");
	public static final Pattern PROFILE_PATTERN = Pattern.compile("^(\\w+):(-?\\d+).*");

	private static final String KIT_SUFFIX = "_KIT";
	private static final String COLOR_SUFFIX = "_COLOR";
	private static final String ICON_KEY = "ICON";

	private final ClientThread clientThread;
	private final ChatMessageManager chatMessageManager;
	private final ItemManager itemManager;

	private final Layers layers;
	private final Locks locks;
	private final History history;
	private final Fallbacks fallbacks;

	public void parseImports(List<String> allLines)
	{
		Map<KitType, Integer> itemImports = new HashMap<>();
		Map<KitType, Integer> kitImports = new HashMap<>();
		Map<ColorType, Integer> colorImports = new HashMap<>();
		JawIcon icon = null;
		Set<KitType> nothings = new HashSet<>();
		for (String line : allLines)
		{
			if (line.trim().isEmpty())
			{
				continue;
			}
			Matcher matcher = PROFILE_PATTERN.matcher(line);
			if (matcher.matches())
			{
				String slotStr = matcher.group(1);
				// could be item id, kit id, or color id
				int id = Integer.parseInt(matcher.group(2));
				KitType itemSlot = itemSlotMatch(slotStr);
				KitType kitSlot = kitSlotMatch(slotStr);
				ColorType colorType = colorSlotMatch(slotStr);
				if (itemSlot != null)
				{
					if (id <= 0)
					{
						nothings.add(itemSlot);
					}
					else
					{
						itemImports.put(itemSlot, id);
					}
				}
				else if (kitSlot != null)
				{
					kitImports.put(kitSlot, id);
				}
				else if (colorType != null)
				{
					colorImports.put(colorType, id);
				}
				else if (slotStr.equals(ICON_KEY))
				{
					icon = JawIcon.fromId(id);
				}
				else
				{
					sendHighlightedMessage("Could not import line: " + line);
				}
			}
		}
		if (!itemImports.isEmpty() || !kitImports.isEmpty() || !colorImports.isEmpty())
		{
			performImport(itemImports, kitImports, colorImports, icon, nothings);
		}
	}


	@Nullable
	private KitType itemSlotMatch(String name)
	{
		try
		{
			return KitType.valueOf(name);
		}
		catch (Exception e)
		{
			return null;
		}
	}

	@Nullable
	private KitType kitSlotMatch(String name)
	{
		try
		{
			String k = name.replace(KIT_SUFFIX, "");
			return KitType.valueOf(k);
		}
		catch (Exception e)
		{
			return null;
		}
	}

	@Nullable
	private ColorType colorSlotMatch(String name)
	{
		try
		{
			String c = name.replace(COLOR_SUFFIX, "");
			return ColorType.valueOf(c);
		}
		catch (Exception e)
		{
			return null;
		}
	}

	public void importPlayer(PlayerComposition other)
	{
		int[] equipmentIds = other.getEquipmentIds();
		KitType[] slots = KitType.values();
		Map<KitType, Integer> equipIdImports = IntStream.range(0, equipmentIds.length).boxed()
			.collect(Collectors.toMap(i -> slots[i], i -> equipmentIds[i]));

		Map<KitType, Integer> itemImports = equipIdImports.entrySet().stream()
			.filter(e -> e.getValue() >= FashionManager.ITEM_OFFSET)
			.collect(Collectors.toMap(Map.Entry::getKey, e -> e.getValue() - FashionManager.ITEM_OFFSET));
		Map<KitType, Integer> kitImports = equipIdImports.entrySet().stream()
			.filter(e -> e.getValue() >= FashionManager.KIT_OFFSET && e.getValue() < FashionManager.ITEM_OFFSET)
			.collect(Collectors.toMap(Map.Entry::getKey, e -> e.getValue() - FashionManager.KIT_OFFSET));
		Set<KitType> nothingSlots = equipIdImports.entrySet().stream()
			.filter(e -> e.getValue() < FashionManager.KIT_OFFSET && FashionManager.ALLOWS_NOTHING_ITEMS.contains(e.getKey()))
			.map(Map.Entry::getKey)
			.collect(Collectors.toSet());

		int[] colors = other.getColors();
		ColorType[] types = ColorType.values();
		Map<ColorType, Integer> colorImports = IntStream.range(0, colors.length).boxed()
			.collect(Collectors.toMap(i -> types[i], i -> colors[i]));

		JawIcon icon = null;
		Integer jawItemId = itemImports.get(KitType.JAW);
		if (jawItemId != null)
		{
			icon = JawKit.iconFromItemId(jawItemId);
			itemImports.remove(KitType.JAW);
		}

		if (!itemImports.isEmpty() || !kitImports.isEmpty() || !colorImports.isEmpty() || !nothingSlots.isEmpty())
		{
			performImport(itemImports, kitImports, colorImports, icon, nothingSlots);
		}
	}

	/**
	 * Loads all given params into layers. This clears the user's locks.
	 *
	 * @param newItems     incoming item ids
	 * @param newKits      incoming kit ids
	 * @param newColors    incoming color ids
	 * @param icon         jaw icon (nullable)
	 * @param nothingSlots slots that should be set to "nothing" directly
	 */
	public void performImport(
		Map<KitType, Integer> newItems,
		Map<KitType, Integer> newKits,
		Map<ColorType, Integer> newColors,
		JawIcon icon,
		Set<KitType> nothingSlots)
	{
		clientThread.invokeLater(() -> {
			locks.clear();

			Diff diff = Diff.empty();

			// don't set to "nothing" if item already hides
			Set<KitType> remainingNothingSlots = new HashSet<>(nothingSlots);

			// track slots that haven't changed (will be unset later)
			Set<KitType> unsetSlots = new HashSet<>(Arrays.asList(KitType.values()));

			// import items onto player
			List<SlotInfo> items = newItems.entrySet().stream()
				.map(e -> SlotInfo.lookUp(e.getValue() + FashionManager.ITEM_OFFSET, e.getKey()))
				.collect(Collectors.toList());
			for (SlotInfo item : items)
			{
				diff = Diff.merge(layers.set(item.getSlot(), item, false), diff);
				unsetSlots.remove(item.getSlot());
				item.getHidden().forEach(i -> {
					unsetSlots.remove(i);
					remainingNothingSlots.remove(i);
				});
			}

			// import icon
			diff = Diff.merge(layers.setIcon(icon, false), diff);

			// import kits (requires known gender)
			Integer gender = layers.getGender();
			if (gender != null)
			{
				List<SlotInfo> kits = newKits.entrySet().stream()
					.map(e -> {
						KitType slot = e.getKey();
						Kit kit = KitUtil.KIT_ID_TO_KIT.get(e.getValue());
						// if no analog exists, use a fallback (don't notify UI that the player's slot is unknown)
						if (kit == null)
						{
							int kitId = fallbacks.getKit(slot, gender, false);
							kit = KitUtil.KIT_ID_TO_KIT.get(kitId);
						}
						return kit != null ? SlotInfo.kit(kit, gender) : SlotInfo.nothing(slot);
					})
					.filter(s -> !s.isNothing())
					.collect(Collectors.toList());
				for (SlotInfo kit : kits)
				{
					diff = Diff.merge(layers.set(kit.getSlot(), kit, false), diff);
					unsetSlots.remove(kit.getSlot());
				}
			}
			else if (!newKits.isEmpty())
			{
				sendHighlightedMessage("Not all imports could be loaded: can't determine your character's gender");
			}

			// set "nothing" where needed
			for (KitType slot : remainingNothingSlots)
			{
				diff = Diff.merge(layers.set(slot, SlotInfo.nothing(slot), false), diff);
				unsetSlots.remove(slot);
			}

			// unset any slot that hasn't been touched at all
			for (KitType slot : unsetSlots)
			{
				diff = Diff.merge(layers.set(slot, null, false), diff);
			}

			// finally, set/unset color ids
			for (ColorType type : ColorType.values())
			{
				diff = Diff.merge(layers.setColor(type, newColors.get(type), false), diff);
			}

			history.append(diff);
		});
	}

	public void export(File selected)
	{
		clientThread.invokeLater(() -> {
			try (PrintWriter out = new PrintWriter(selected))
			{
				List<String> exports = getExportsAsStrings();
				for (String line : exports)
				{
					out.println(line);
				}
				sendHighlightedMessage("Saved fashionscape to " + selected.getName());
			}
			catch (FileNotFoundException e)
			{
				log.warn("Could not find selected file for fashionscape export", e);
			}
		});
	}

	// this should only be called from the client thread
	@VisibleForTesting
	List<String> getExportsAsStrings()
	{
		ModelInfo modelInfo = layers.getVirtualModels();
		Set<Map.Entry<KitType, Integer>> itemEntries = modelInfo.getItems().getAll().entrySet().stream()
			.collect(Collectors.toMap(Map.Entry::getKey, i -> i.getValue().getItemId()))
			.entrySet();
		List<String> result = itemEntries.stream()
			.sorted(Comparator.comparingInt(Map.Entry::getValue))
			.map(e -> {
				KitType slot = e.getKey();
				int itemId = e.getValue();
				String prefix = slot.name() + ":";
				if (itemId < 0)
				{
					return prefix + "-1 (Nothing)";
				}
				else
				{
					String itemName = itemManager.getItemComposition(itemId).getMembersName();
					return prefix + itemId + " (" + itemName + ")";
				}
			})
			.collect(Collectors.toList());
		List<String> kits = modelInfo.getKits().getAll().entrySet().stream()
			.sorted(Comparator.comparingInt(Map.Entry::getValue))
			.map(e -> {
				KitType slot = e.getKey();
				Integer kitId = e.getValue();
				String kitName = KitUtil.KIT_ID_TO_KIT.get(kitId).getDisplayName();
				return slot.name() + KIT_SUFFIX + ":" + kitId + " (" + kitName + ")";
			})
			.collect(Collectors.toList());
		List<String> colors = modelInfo.getColors().getAll().entrySet().stream()
			.sorted(Comparator.comparingInt(Map.Entry::getValue))
			.map(e -> {
				ColorType type = e.getKey();
				int colorId = e.getValue();
				return Arrays.stream(type.getColorables())
					.filter(c -> c.getColorId(type) == colorId)
					.findFirst()
					.map(c -> type.name() + COLOR_SUFFIX + ":" + colorId + " (" + c.getDisplayName() + ")")
					.orElse("");
			})
			.collect(Collectors.toList());
		List<String> icons = new ArrayList<>();
		JawIcon icon = modelInfo.getIcon();
		if (icon != null)
		{
			icons.add(ICON_KEY + ":" + icon.getId() + " (" + icon.getDisplayName() + ")");
		}
		result.addAll(kits);
		result.addAll(colors);
		result.addAll(icons);
		return result;
	}

	private void sendHighlightedMessage(String message)
	{
		String chatMessage = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append(message)
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(chatMessage)
			.build());
	}
}

package eq.uirs.fashionscape.core.randomizer;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Determines the size of the queue for scoring the "best" matched item via randomizer request
 */
@Getter
@RequiredArgsConstructor
public enum RandomizerIntelligence
{
	NONE(1),
	LOW(10),
	MODERATE(50),
	HIGH(100),
	CURSED(50); // prefers mismatched colors

	private final int depth;
}

package eq.uirs.fashionscape.core.randomizer;

import com.google.common.annotations.VisibleForTesting;
import eq.uirs.fashionscape.FashionscapeConfig;
import eq.uirs.fashionscape.colors.ColorScorer;
import eq.uirs.fashionscape.core.Diff;
import eq.uirs.fashionscape.core.Exclusions;
import eq.uirs.fashionscape.core.FashionManager;
import eq.uirs.fashionscape.core.SlotInfo;
import eq.uirs.fashionscape.core.layer.Layers;
import eq.uirs.fashionscape.core.layer.Locks;
import eq.uirs.fashionscape.core.model.ModelInfo;
import eq.uirs.fashionscape.core.utils.ItemSlotUtil;
import eq.uirs.fashionscape.core.utils.KitUtil;
import eq.uirs.fashionscape.core.utils.ListUtil;
import eq.uirs.fashionscape.data.color.ColorType;
import eq.uirs.fashionscape.data.color.Colorable;
import eq.uirs.fashionscape.data.kit.JawIcon;
import eq.uirs.fashionscape.data.kit.JawKit;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.kit.KitType;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = {@Inject})
public class Randomizer
{
	private final Layers layers;
	private final Locks locks;
	private final FashionscapeConfig config;
	private final ColorScorer colorScorer;
	private final Client client;
	private final ItemManager itemManager;
	private final Exclusions exclusions;

	private final Map<KitType, List<SlotInfo>> slotToItemsMemo = new HashMap<>();
	private final Random random = new Random();

	@VisibleForTesting
	void setRandomSeed(long seed)
	{
		random.setSeed(seed);
	}

	public Diff shuffle()
	{
		if (slotToItemsMemo.isEmpty())
		{
			repopulateMemo();
		}

		RandomizerIntelligence intelligence = config.randomizerIntelligence();
		if (intelligence != RandomizerIntelligence.NONE)
		{
			computeLockedColorScores();
		}
		Diff diff = Diff.empty();
		// first, try to occupy all unlocked slots with items
		List<SlotInfo> slottedItems = findItems();
		for (SlotInfo item : slottedItems)
		{
			diff = Diff.merge(layers.set(item.getSlot(), item, false), diff);
		}

		// next, try to occupy remaining slots with random kits (no color scoring since they're recolor-able)
		List<SlotInfo> slottedKits = findKits(slottedItems);
		for (SlotInfo kit : slottedKits)
		{
			diff = Diff.merge(layers.set(kit.getSlot(), kit, false), diff);
		}

		// find the icon that most closely matches on color
		JawIcon icon = findIcon();
		if (icon != null)
		{
			diff = Diff.merge(layers.setIcon(icon, false), diff);
		}

		// lastly, shuffle the player's base model colors
		Map<ColorType, Colorable> colors = findColors();
		for (Map.Entry<ColorType, Colorable> entry : colors.entrySet())
		{
			ColorType colorType = entry.getKey();
			Colorable color = entry.getValue();
			diff = Diff.merge(layers.setColor(colorType, color.getColorId(colorType), false), diff);
		}
		return diff;
	}

	public void repopulateMemo()
	{
		slotToItemsMemo.clear();
		Set<Integer> skips = exclusions.getAll();
		for (int i = 0; i < client.getItemCount(); i++)
		{
			int canonical = itemManager.canonicalize(i);
			// can skip banknote/placeholder items since the canonical version will come up eventually
			if (i != canonical || skips.contains(canonical))
			{
				continue;
			}
			ItemComposition itemComposition = itemManager.getItemComposition(i);
			int itemId = itemComposition.getId();
			KitType slot = ItemSlotUtil.getSlot(itemId, itemManager);
			if (slot == null)
			{
				continue;
			}
			SlotInfo slotInfo = SlotInfo.lookUp(itemId + FashionManager.ITEM_OFFSET, slot);
			List<SlotInfo> itemsInSlot = slotToItemsMemo.getOrDefault(slot, new ArrayList<>());
			itemsInSlot.add(slotInfo);
			slotToItemsMemo.put(slot, itemsInSlot);
		}
	}

	private void computeLockedColorScores()
	{
		ModelInfo info = layers.getVirtualModels();
		Map<KitType, Integer> lockedItems = info.getItems().getAll().values().stream()
			.filter(i -> locks.contains(i.getSlot()))
			.collect(Collectors.toMap(SlotInfo::getSlot, SlotInfo::getItemId));
		if (locks.isIcon() && info.getIcon() != null && info.getIcon() != JawIcon.NOTHING)
		{
			// consider only the icon part of the model, not the built-in facial hair
			Integer iconItemId = JawKit.NO_JAW.getIconItemId(info.getIcon());
			if (iconItemId != null)
			{
				lockedItems.put(KitType.JAW, iconItemId);
			}
		}
		Map<ColorType, Colorable> lockedColors = info.getColors().getAllColorable().entrySet().stream()
			.filter(e -> locks.getColor(e.getKey()))
			.collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
		colorScorer.setPlayerInfo(lockedItems, lockedColors);
	}

	@VisibleForTesting
	List<SlotInfo> findItems()
	{
		List<KitType> remainingItemSlots = Arrays.stream(KitType.values())
			.filter(s -> !locks.contains(s))
			.collect(Collectors.toList());
		Collections.shuffle(remainingItemSlots, random);
		List<SlotInfo> result = new ArrayList<>();
		RandomizerIntelligence intelligence = config.randomizerIntelligence();
		while (!remainingItemSlots.isEmpty())
		{
			KitType slot = remainingItemSlots.remove(0);
			// skip jaw items, as these are handled later as icons
			if (slot == KitType.JAW)
			{
				continue;
			}
			// items in this slot cannot conflict with locked or already-filled slots
			Set<KitType> remainingSet = new HashSet<>(remainingItemSlots);
			List<SlotInfo> allCandidates = slotToItemsMemo.getOrDefault(slot, new ArrayList<>()).stream()
				.filter(slotInfo -> locks.isAllowed(slot, slotInfo) &&
					remainingSet.containsAll(slotInfo.getHidden()))
				.collect(Collectors.toList());
			if (!allCandidates.isEmpty())
			{
				List<SlotInfo> candidates = ListUtil.takeRandomSample(allCandidates, intelligence.getDepth(), random);
				int multiplier = intelligence == RandomizerIntelligence.CURSED ? -1 : 1;
				SlotInfo bestMatch = candidates.stream()
					.max(Comparator.comparingDouble(c -> multiplier * colorScorer.score(c.getItemId(), c.getSlot())))
					.orElse(candidates.get(0));
				result.add(bestMatch);
				// also remove slots that the match hides
				bestMatch.getHidden().forEach(remainingItemSlots::remove);
				colorScorer.addPlayerInfo(bestMatch.getSlot(), bestMatch.getItemId());
			}
		}
		return result;
	}

	@VisibleForTesting
	List<SlotInfo> findKits(List<SlotInfo> existingItems)
	{
		List<SlotInfo> result = new ArrayList<>();
		Integer gender = layers.getGender();
		if (gender != null && !config.excludeBaseModels())
		{
			// check locks and items from last step to ensure kit model can be shown
			List<KitType> remainingKitSlots = Arrays.stream(KitType.values())
				// kit id doesn't matter, just need to check if kit is allowed for current locks
				.filter(slot -> locks.isAllowed(slot, SlotInfo.kit(0, slot)) &&
					existingItems.stream().noneMatch(item -> item.getSlot() == slot || item.hides(slot)))
				.collect(Collectors.toList());
			Collections.shuffle(remainingKitSlots, random);
			while (!remainingKitSlots.isEmpty())
			{
				KitType slot = remainingKitSlots.remove(0);
				// only consider kits applicable to current gender
				List<SlotInfo> candidates = KitUtil.KIT_TYPE_TO_KITS.getOrDefault(slot, new ArrayList<>()).stream()
					.filter(k -> !k.isHidden() && k.getKitId(gender) != null && k != JawKit.NO_JAW)
					.map(k -> SlotInfo.kit(k, gender))
					.collect(Collectors.toList());
				if (!candidates.isEmpty())
				{
					result.add(candidates.get(random.nextInt(candidates.size())));
				}
			}
		}
		return result;
	}

	@VisibleForTesting
	JawIcon findIcon()
	{
		if (locks.isIcon() || config.excludeBaseModels())
		{
			return null;
		}
		JawIcon icon = JawIcon.NOTHING;
		List<JawIcon> icons = Arrays.asList(JawIcon.values());
		// score colors if intelligence is not minimal
		RandomizerIntelligence intelligence = config.randomizerIntelligence();
		if (intelligence != RandomizerIntelligence.NONE && intelligence != RandomizerIntelligence.CURSED)
		{
			Map<JawIcon, Double> scores = icons.stream()
				.collect(Collectors.toMap(i -> i, i -> {
					Integer itemId = JawKit.NO_JAW.getIconItemId(i);
					return itemId != null ? colorScorer.score(itemId, null) : 0;
				}));
			// use icon if >75% match
			icon = scores.entrySet().stream()
				.filter(e -> e.getValue() > 0.75)
				.max(Comparator.comparingDouble(Map.Entry::getValue))
				.map(Map.Entry::getKey)
				.orElse(JawIcon.NOTHING);
		}
		else if (random.nextDouble() > 0.33)
		{
			// since there aren't many icons, just prefer not showing one most of the time
			icon = icons.get(random.nextInt(icons.size()));
		}
		return icon;
	}

	@VisibleForTesting
	Map<ColorType, Colorable> findColors()
	{
		Map<ColorType, Colorable> result = new HashMap<>();
		if (config.excludeBaseModels())
		{
			return result;
		}
		RandomizerIntelligence intelligence = config.randomizerIntelligence();
		for (ColorType colorType : ColorType.values())
		{
			if (locks.getColor(colorType))
			{
				continue;
			}
			List<Colorable> colorables = Arrays.asList(colorType.getColorables().clone());
			Collections.shuffle(colorables, random);
			int limit;
			switch (intelligence)
			{
				case LOW:
					limit = Math.max(1, colorables.size() / 4);
					break;
				case MODERATE:
				case CURSED:
					limit = Math.max(1, colorables.size() / 2);
					break;
				case HIGH:
					limit = colorables.size();
					break;
				default:
					limit = 1;
			}
			int multiplier = intelligence == RandomizerIntelligence.CURSED ? -1 : 1;
			Colorable best = colorables.stream()
				.limit(limit)
				.max(Comparator.comparingDouble(c -> colorScorer.score(c, colorType) * multiplier))
				.orElse(colorables.get(0));
			result.put(colorType, best);
			colorScorer.addPlayerColor(colorType, best);
		}
		return result;
	}
}

package eq.uirs.fashionscape.core;

import eq.uirs.fashionscape.core.event.HistoryChanged;
import eq.uirs.fashionscape.core.layer.Layers;
import eq.uirs.fashionscape.core.layer.Locks;
import eq.uirs.fashionscape.data.color.ColorType;
import eq.uirs.fashionscape.data.kit.JawIcon;
import java.util.LinkedList;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.kit.KitType;
import net.runelite.client.eventbus.EventBus;

/**
 * Observable wrapper for user's undo / redo history of virtual models.
 */
@RequiredArgsConstructor(onConstructor_ = {@Inject})
@Singleton
@Slf4j
class History
{
	private static final int MAX_LIST_SIZE = 10;

	private final Layers layers;
	private final Locks locks;
	private final EventBus eventBus;

	private final LinkedList<Diff> undoHistory = new LinkedList<>();
	private final LinkedList<Diff> redoHistory = new LinkedList<>();

	void undo()
	{
		if (undoHistory.isEmpty())
		{
			return;
		}
		Diff last = undoHistory.removeLast();
		onUndo();
		Diff redo = restore(last);
		addRedoDiff(redo);
	}

	void redo()
	{
		if (redoHistory.isEmpty())
		{
			return;
		}
		Diff last = redoHistory.removeLast();
		onRedo();
		Diff restore = restore(last);
		addUndoDiff(restore);
	}

	void append(Diff diff)
	{
		if (diff.isEmpty())
		{
			return;
		}
		addUndoDiff(diff);
		redoHistory.clear();
		onRedo();
	}

	int undoSize()
	{
		return undoHistory.size();
	}

	int redoSize()
	{
		return redoHistory.size();
	}

	private void addUndoDiff(Diff diff)
	{
		if (diff.isEmpty())
		{
			return;
		}
		Diff lastUndo = undoHistory.peekLast();
		if (diff.equals(lastUndo))
		{
			return;
		}
		undoHistory.add(diff);
		while (undoHistory.size() > MAX_LIST_SIZE)
		{
			undoHistory.removeFirst();
		}
		onUndo();
	}

	private void addRedoDiff(Diff diff)
	{
		if (diff.isEmpty())
		{
			return;
		}
		Diff lastRedo = redoHistory.peekLast();
		if (diff.equals(lastRedo))
		{
			return;
		}
		redoHistory.add(diff);
		while (redoHistory.size() > MAX_LIST_SIZE)
		{
			redoHistory.removeFirst();
		}
		onRedo();
	}

	private void onUndo()
	{
		eventBus.post(new HistoryChanged(true, undoSize()));
	}

	private void onRedo()
	{
		eventBus.post(new HistoryChanged(false, redoSize()));
	}

	private Diff restore(Diff diff)
	{
		Diff result = Diff.empty();
		for (KitType slot : KitType.values())
		{
			// outSlots may not contain this slot, but even if not, inSlots may have changed
			SlotInfo info = diff.outSlots.get(slot);
			// put whatever went out back if it's different from inSlot (and if locks allow)
			if (!Objects.equals(info, diff.inSlots.get(slot)) && locks.isAllowed(slot, info))
			{
				result = Diff.merge(layers.set(slot, info, false), result);
			}
		}
		for (ColorType type : ColorType.values())
		{
			Integer colorId = diff.outColors.get(type);
			// put the colorId back if it's different from inColor and if unlocked
			if (!Objects.equals(colorId, diff.inColors.get(type)) && !locks.getColor(type))
			{
				result = Diff.merge(layers.setColor(type, colorId, false), result);
			}
		}
		JawIcon icon = diff.outIcon;
		if (!locks.isIcon())
		{
			result = Diff.merge(layers.setIcon(icon, false), result);
		}
		return result;
	}
}

