	@BeforeAll
	public static void populate()
	{
		Map<Integer, ItemSlotInfo> info = RemoteData.ITEM_ID_TO_INFO;
		info.put(ItemID.RUNE_MED_HELM, convert(TestData.runeMedHelm));
		info.put(ItemID.SLAYER_FACEMASK, convert(TestData.faceMask));
		info.put(ItemID.IRON_FULL_HELM, convert(TestData.ironFullHelm));
		info.put(ItemID.CASTLEWARS_CLOAK_SARADOMIN, convert(TestData.hoodedCloak));
		info.put(ItemID.WHITE_2H_SWORD, convert(TestData.white2hSword));
		info.put(ItemID.BEACHPARTY_BOXINGGLOVES_YELLOW, convert(TestData.beachBoxingGloves));
		info.put(ItemID.BRONZE_PLATEBODY, convert(TestData.bronzePlatebody));
		info.put(ItemID.PLAGUE_JACKET, convert(TestData.plagueJacket));
		info.put(ItemID.GAUNTLET_PLATELEGS_T3_HM, convert(TestData.corruptedLegs));

		RemoteData.MISC_DATA = new MiscData(
			new HashSet<>(),
			new ArrayList<>(),
			new HashSet<>(),
			new HashSet<>(),
			new HashSet<>(),
			ImmutableSet.of(ItemID.MAGIC_CARPET),
			new HashSet<>()
		);
	}

	private static ItemSlotInfo convert(SlotInfo i)
	{
		List<Integer> hides = i.getHidden().stream()
			.map(KitType::getIndex)
			.collect(Collectors.toList());
		return new ItemSlotInfo(
			i.getSlot().getIndex(),
			!hides.isEmpty() ? hides.get(0) : null,
			hides.size() > 1 ? hides.get(1) : null
		);
	}
}

package eq.uirs.fashionscape.core.utils;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.Test;

public class ListUtilTest
{
	private List<Integer> range(int n)
	{
		return IntStream.range(0, n).boxed().collect(Collectors.toCollection(ArrayList::new));
	}

	@Test
	void wholeListSampleReturnsOriginal()
	{
		List<Integer> list = range(5);
		assertSame(list, ListUtil.takeRandomSample(list, 5, new Random(0)));
		assertSame(list, ListUtil.takeRandomSample(list, 10, new Random(0)));
	}

	@Test
	void sampleNothing()
	{
		assertTrue(ListUtil.takeRandomSample(range(5), 0, new Random(0)).isEmpty());
	}

	@Test
	void takeSample()
	{
		List<Integer> list = range(10);
		List<Integer> sample = ListUtil.takeRandomSample(list, 4, new Random(0));
		assertEquals(4, sample.size());
		// should sample without replacement
		assertEquals(4, new HashSet<>(sample).size());
		// every element came from the source range
		assertTrue(list.containsAll(sample));
	}

	@Test
	void deterministicSample()
	{
		List<Integer> a = ListUtil.takeRandomSample(range(20), 6, new Random(1));
		List<Integer> b = ListUtil.takeRandomSample(range(20), 6, new Random(1));
		assertEquals(a, b);
	}
}

package eq.uirs.fashionscape.core.utils;

import com.google.common.collect.ImmutableMap;
import java.util.HashMap;
import java.util.Map;
import static org.junit.jupiter.api.Assertions.assertEquals;
import org.junit.jupiter.api.Test;

public class MapUtilTest
{
	@Test
	void noOverlapMerge()
	{
		Map<String, Integer> map = new HashMap<>(ImmutableMap.of("a", 1));
		MapUtil.putAllIfAllAbsent(map, ImmutableMap.of("b", 2, "c", 3));
		assertEquals(ImmutableMap.of("a", 1, "b", 2, "c", 3), map);
	}

	@Test
	void noOpWhenAnyKeysMatch()
	{
		Map<String, Integer> map = new HashMap<>(ImmutableMap.of("a", 1));
		MapUtil.putAllIfAllAbsent(map, ImmutableMap.of("a", 9, "b", 2));
		assertEquals(ImmutableMap.of("a", 1), map);
	}
}

package eq.uirs.fashionscape.core.utils;

import com.google.common.collect.ImmutableMap;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.Map;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import org.junit.jupiter.api.Test;

public class ConfigSerializerTest
{
	private final ConfigSerializer serializer = new ConfigSerializer(new Gson());

	@Test
	void thereAndBack()
	{
		Map<String, Integer> original = ImmutableMap.of("a", 1, "b", 2);
		Type type = new TypeToken<Map<String, Integer>>()
		{
		}.getType();
		byte[] bytes = serializer.serialize(original);
		assertEquals(original, serializer.deserialize(bytes, type));
	}

	@Test
	void nullBytes()
	{
		assertNull(serializer.deserialize(null, String.class));
	}
}

