					0,
					0,
					0,
					ItemID.MAGIC_CARPET + FashionManager.ITEM_OFFSET,
					fallback(KitType.TORSO),
					0,
					fallback(KitType.ARMS),
					fallback(KitType.LEGS),
					fallback(KitType.HAIR),
					fallback(KitType.HANDS),
					fallback(KitType.BOOTS),
					fallback(KitType.JAW)
				}
			),
			// all fallbacks but with jaw icon (covers edge case)
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(),
				JawIcon.NOTHING,
				ImmutableMap.of(),
				ImmutableMap.of(),
				JawIcon.SW_BLUE,
				new int[]{
					0,
					0,
					0,
					0,
					fallback(KitType.TORSO),
					0,
					fallback(KitType.ARMS),
					fallback(KitType.LEGS),
					fallback(KitType.HAIR),
					fallback(KitType.HANDS),
					fallback(KitType.BOOTS),
					// add icon to whatever fallback jaw is
					JawKit.getEquipmentId(fallback(KitType.JAW) - FashionManager.KIT_OFFSET, JawIcon.SW_BLUE)
				}
			)
		);
	}

	@ParameterizedTest
	@MethodSource("provideCases")
	void computes(Case c)
	{
		PlayerComposition composition = mock(PlayerComposition.class);
		when(composition.getGender()).thenReturn(0);
		when(composition.getColors()).thenReturn(new int[5]);
		layers.deriveNonEquipment(composition, 0);
		layers.deriveEquipment(composition);

		setKitsOnModels(c.realKits, layers.getRealModels());
		layers.getRealModels().getItems().putAll(c.realItems);
		layers.getRealModels().putIcon(c.realIcon);

		setKitsOnModels(c.virtualKits, layers.getVirtualModels());
		layers.getVirtualModels().getItems().putAll(c.virtualItems);
		layers.getVirtualModels().putIcon(c.virtualIcon);

		assertArrayEquals(c.equipIds, layers.computeEquipment());
		resetData();
	}
}

package eq.uirs.fashionscape.core;

import com.google.common.collect.ImmutableMap;
import eq.uirs.fashionscape.data.color.ColorType;
import eq.uirs.fashionscape.data.kit.JawIcon;
import net.runelite.api.kit.KitType;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.Test;

public class DiffTest
{
	@Test
	void unchangedColorIsEmpty()
	{
		assertTrue(Diff.ofColor(ColorType.HAIR, 5, 5).isEmpty());
		// null -> null is also a no-op
		assertTrue(Diff.ofColor(ColorType.HAIR, null, null).isEmpty());
	}

	@Test
	void colorChange()
	{
		Diff diff = Diff.ofColor(ColorType.HAIR, 1, 2);
		assertFalse(diff.isEmpty());
		assertEquals(1, diff.getOutColors().get(ColorType.HAIR));
		assertEquals(2, diff.getInColors().get(ColorType.HAIR));
	}

	@Test
	void slotChange()
	{
		Diff diff = Diff.ofSlots(
			ImmutableMap.of(KitType.LEGS, TestData.mimeLegs),
			ImmutableMap.of(KitType.LEGS, TestData.flaresLegs));
		assertFalse(diff.isEmpty());
		assertEquals(TestData.mimeLegs, diff.getOutSlots().get(KitType.LEGS));
		assertEquals(TestData.flaresLegs, diff.getInSlots().get(KitType.LEGS));
	}

	@Test
	void iconChange()
	{
		Diff diff = Diff.ofIcon(JawIcon.BA_ATTACKER, JawIcon.BA_HEALER);
		assertFalse(diff.isEmpty());
		assertEquals(JawIcon.BA_ATTACKER, diff.getOutIcon());
		assertEquals(JawIcon.BA_HEALER, diff.getInIcon());
	}

	@Test
	void mergeOfEmptiesIsEmpty()
	{
		assertTrue(Diff.merge(Diff.empty(), Diff.empty()).isEmpty());
	}

	@Test
	void mergeDisjointFields()
	{
		Diff slots = Diff.ofSlots(
			ImmutableMap.of(KitType.LEGS, TestData.mimeLegs),
			ImmutableMap.of(KitType.LEGS, TestData.flaresLegs));
		Diff color = Diff.ofColor(ColorType.HAIR, 1, 2);
		Diff merged = Diff.merge(slots, color);
		assertEquals(TestData.flaresLegs, merged.getInSlots().get(KitType.LEGS));
		assertEquals(2, merged.getInColors().get(ColorType.HAIR));
	}

	@Test
	void mergePrefersFirstDiffOnCollision()
	{
		Diff first = Diff.ofSlots(
			ImmutableMap.of(KitType.LEGS, TestData.mimeLegs),
			ImmutableMap.of(KitType.LEGS, TestData.flaresLegs));
		Diff second = Diff.ofSlots(
			ImmutableMap.of(KitType.LEGS, TestData.corruptedLegs),
			ImmutableMap.of(KitType.LEGS, SlotInfo.nothing(KitType.LEGS)));
		Diff merged = Diff.merge(first, second);
		assertEquals(TestData.mimeLegs, merged.getOutSlots().get(KitType.LEGS));
		assertEquals(TestData.flaresLegs, merged.getInSlots().get(KitType.LEGS));
	}

	@Test
	void iconMergeTakesFirstNonNull()
	{
		Diff withIcon = Diff.ofIcon(JawIcon.BA_ATTACKER, JawIcon.BA_HEALER);
		Diff withoutIcon = Diff.ofColor(ColorType.HAIR, 1, 2);
		assertEquals(JawIcon.BA_ATTACKER, Diff.merge(withIcon, withoutIcon).getOutIcon());
		assertEquals(JawIcon.BA_ATTACKER, Diff.merge(withoutIcon, withIcon).getOutIcon());
	}
}

package eq.uirs.fashionscape.core;

import com.google.common.collect.ImmutableMap;
import eq.uirs.fashionscape.base.BaseLayersTest;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Stream;
import lombok.Value;
import net.runelite.api.kit.KitType;
import static org.junit.jupiter.api.Assertions.assertEquals;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

public class LayersDiffTest extends BaseLayersTest
{
	@Value
	public static class Case
	{
		// setup
		Map<KitType, Integer> kits;
		Map<KitType, SlotInfo> items;
		// input
		KitType slot;
		SlotInfo info;
		// output
		Map<KitType, SlotInfo> outSlots;
	}

	public static Stream<Case> provideCases()
	{
		return Stream.of(
			// no change
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(),
				KitType.AMULET,
				null,
				ImmutableMap.of()),
			// simple amulet add
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(),
				KitType.AMULET,
				TestData.camulet,
				ImmutableMap.of()),
			// simple helm replace
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(KitType.HEAD, TestData.faceMask),
				KitType.HEAD,
				TestData.redPartyHat,
				ImmutableMap.of(KitType.HEAD, TestData.faceMask)),
			// boot item replaces kit
			new Case(
				ImmutableMap.of(KitType.BOOTS, TestData.smallBoots.getKitId()),
				ImmutableMap.of(),
				KitType.BOOTS,
				TestData.pinkBoots,
				ImmutableMap.of(KitType.BOOTS, TestData.smallBoots)),
			// torso kit replaces item (legs are unaffected)
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(KitType.TORSO, TestData.bronzePlatebody,
					KitType.LEGS, TestData.mimeLegs),
				KitType.TORSO,
				TestData.plainTorso,
				ImmutableMap.of(KitType.TORSO, TestData.bronzePlatebody)),
			// torso item replaces torso+arms kits
			new Case(
				ImmutableMap.of(
					KitType.TORSO, TestData.plainTorso.getKitId(),
					KitType.ARMS, TestData.thinStripeArms.getKitId()
				),
				ImmutableMap.of(),
				KitType.TORSO,
				TestData.bronzePlatebody,
				ImmutableMap.of(KitType.TORSO, TestData.plainTorso,
					KitType.ARMS, TestData.thinStripeArms)),
			// shield replaces 2h weapon
			new Case(
				ImmutableMap.of(),
				ImmutableMap.of(KitType.WEAPON, TestData.white2hSword),
				KitType.SHIELD,
				TestData.gildedKiteshield,
				ImmutableMap.of(KitType.WEAPON, TestData.white2hSword)),
			// weapon replaces shield and hands kit
			new Case(
				ImmutableMap.of(KitType.HANDS, TestData.bracersHands.getKitId()),
				ImmutableMap.of(KitType.SHIELD, TestData.gildedKiteshield),
				KitType.WEAPON,
				TestData.beachBoxingGloves,
				ImmutableMap.of(KitType.SHIELD, TestData.gildedKiteshield,
					KitType.HANDS, TestData.bracersHands)),
			// cloak replaces hair kit
			new Case(
				ImmutableMap.of(KitType.HAIR, TestData.curlsHair.getKitId()),
				ImmutableMap.of(),
				KitType.CAPE,
				TestData.hoodedCloak,
				ImmutableMap.of(KitType.HAIR, TestData.curlsHair)),
			// torso item replaces weapon (since both hide hands) and arms kit
			new Case(
				ImmutableMap.of(KitType.ARMS, TestData.thinStripeArms.getKitId()),
				ImmutableMap.of(KitType.WEAPON, TestData.beachBoxingGloves),
				KitType.TORSO,
				TestData.plagueJacket,
				ImmutableMap.of(KitType.WEAPON, TestData.beachBoxingGloves,
					KitType.ARMS, TestData.thinStripeArms))
		);
	}

	@ParameterizedTest
	@MethodSource("provideCases")
	void diffs(Case c)
	{
		setKitsOnModels(c.kits, layers.getVirtualModels());
		layers.getVirtualModels().getItems().putAll(c.items);
		Diff d = layers.set(c.slot, c.info, false);
		Map<KitType, SlotInfo> inSlots = new HashMap<>();
		if (c.info != null)
		{
			inSlots.put(c.slot, c.info);
		}
		assertEquals(Diff.ofSlots(c.outSlots, inSlots), d);
		resetData();
	}
}

package eq.uirs.fashionscape.core;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableSet;
import com.google.inject.Inject;
import eq.uirs.fashionscape.base.BaseLayersTest;
import eq.uirs.fashionscape.core.layer.Locks;
import eq.uirs.fashionscape.data.color.ColorType;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.stream.Stream;
import lombok.Value;
import net.runelite.api.kit.KitType;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

public class LocksTest extends BaseLayersTest
{
	@Value
	public static class AllowCase
	{
		// setup
		Map<KitType, LockStatus> locks;
		Set<SlotInfo> items;
		// input
		KitType slot;
		SlotInfo info;
	}

	@Value
	public static class DisallowCase
	{
		// setup
		Map<KitType, LockStatus> locks;
		Set<SlotInfo> items;
		// input
		KitType slot;
		SlotInfo info;
		// output
		Set<KitType> conflicts;
	}

	@Inject
	private Locks locks;

	public static Stream<AllowCase> provideAllows()
	{
		return Stream.of(
			// if there are no locks, any modification is allowed
			new AllowCase(new HashMap<>(), new HashSet<>(), KitType.AMULET, TestData.camulet),
			// if only item is locked, changing to kit is allowed
			new AllowCase(
				ImmutableMap.of(KitType.LEGS, LockStatus.ITEM),
				new HashSet<>(),
				KitType.LEGS,
				TestData.flaresLegs),
			// if only item is locked, unsetting a kit is allowed
			new AllowCase(
				ImmutableMap.of(KitType.LEGS, LockStatus.ITEM),
				ImmutableSet.of(TestData.flaresLegs),
				KitType.LEGS,
				null),
			// neither helm changes jaw
			new AllowCase(
				ImmutableMap.of(KitType.JAW, LockStatus.ALL),
				ImmutableSet.of(TestData.redPartyHat, TestData.daliJaw),
				KitType.HEAD,
				TestData.runeMedHelm),
			// helm affects neither hair nor jaw
			new AllowCase(
				ImmutableMap.of(KitType.JAW, LockStatus.ALL, KitType.HAIR, LockStatus.ALL),
				ImmutableSet.of(TestData.redPartyHat),
				KitType.HEAD,
				null),
			// changing to 1h weapon doesn't affect shield
			new AllowCase(
				ImmutableMap.of(KitType.SHIELD, LockStatus.ALL),
				new HashSet<>(),
				KitType.WEAPON,
				TestData.blackMace),
			// even though hair is locked, both helms hide hair
			new AllowCase(
				ImmutableMap.of(KitType.HAIR, LockStatus.ALL),
				ImmutableSet.of(TestData.runeMedHelm),
				KitType.HEAD,
				TestData.ironFullHelm),
			// plague jacket and boxing gloves both hide hands from different slots
			new AllowCase(
				ImmutableMap.of(KitType.HANDS, LockStatus.ALL),
				ImmutableSet.of(TestData.plagueJacket),
				KitType.WEAPON,
				TestData.beachBoxingGloves)
		);
	}

	@ParameterizedTest
	@MethodSource("provideAllows")
	void allowed(AllowCase c)
	{
		c.locks.forEach((key, value) -> locks.set(key, value));
		c.items.forEach(i -> layers.getVirtualModels().getItems().put(i.getSlot(), i));
		assertTrue(locks.isAllowed(c.slot, c.info));
		resetData();
	}

	public static Stream<DisallowCase> provideDisallows()
	{
		return Stream.of(
			// can't place item in a locked slot
			new DisallowCase(
				ImmutableMap.of(KitType.AMULET, LockStatus.ITEM),
				new HashSet<>(),
				KitType.AMULET,
				TestData.camulet,
				ImmutableSet.of(KitType.AMULET)),
			// if item is locked, unsetting it isn't allowed
			new DisallowCase(
				ImmutableMap.of(KitType.CAPE, LockStatus.ITEM),
				ImmutableSet.of(TestData.blueCape),
				KitType.CAPE,
				null,
				ImmutableSet.of(KitType.CAPE)),
			// if item is locked, changing item to kit isn't allowed
			new DisallowCase(
				ImmutableMap.of(KitType.LEGS, LockStatus.ITEM),
				ImmutableSet.of(TestData.mimeLegs),
				KitType.LEGS,
				TestData.flaresLegs,
				ImmutableSet.of(KitType.LEGS)),
			// changing torsos would change the locked arms slot
			new DisallowCase(
				ImmutableMap.of(KitType.ARMS, LockStatus.ALL),
				ImmutableSet.of(TestData.bronzePlatebody),
				KitType.TORSO,
				TestData.studdedBody,
				ImmutableSet.of(KitType.ARMS)),
			// removing torso would change both locked slots
			new DisallowCase(
				ImmutableMap.of(KitType.ARMS, LockStatus.ALL, KitType.TORSO, LockStatus.ALL),
				ImmutableSet.of(TestData.bronzePlatebody),
				KitType.TORSO,
				null,
				ImmutableSet.of(KitType.ARMS, KitType.TORSO)),
			// gauntlet legs would hide locked boots slot
			new DisallowCase(
				ImmutableMap.of(KitType.BOOTS, LockStatus.ITEM),
				ImmutableSet.of(TestData.pinkBoots),
				KitType.LEGS,
				TestData.corruptedLegs,
				ImmutableSet.of(KitType.BOOTS)),
			// changing shields would change the locked weapon slot
			new DisallowCase(
				ImmutableMap.of(KitType.WEAPON, LockStatus.ITEM),
				ImmutableSet.of(TestData.white2hSword),
				KitType.SHIELD,
				TestData.gildedKiteshield,
				ImmutableSet.of(KitType.WEAPON)),
			// changing jaw would change the locked hair slot, due to helm
			new DisallowCase(
				ImmutableMap.of(KitType.HAIR, LockStatus.ALL),
				ImmutableSet.of(TestData.ironFullHelm),
				KitType.JAW,
				TestData.daliJaw,
				ImmutableSet.of(KitType.HAIR)),
			// changing hair would change the locked cape slot
			new DisallowCase(
				ImmutableMap.of(KitType.CAPE, LockStatus.ALL),
				ImmutableSet.of(TestData.hoodedCloak),
				KitType.HAIR,
				TestData.curlsHair,
				ImmutableSet.of(KitType.CAPE)),
			// changing hair would change capes, which would change the locked head slot
			new DisallowCase(
				ImmutableMap.of(KitType.HEAD, LockStatus.ALL),
				ImmutableSet.of(TestData.hoodedCloak),
				KitType.HAIR,
				TestData.curlsHair,
				ImmutableSet.of(KitType.HEAD)),
			// head slot would technically be unchanged by this, but the cloak hides it and is thus tied to it
			new DisallowCase(
				ImmutableMap.of(KitType.HEAD, LockStatus.ALL),
				ImmutableSet.of(TestData.hoodedCloak),
				KitType.CAPE,
				null,
				ImmutableSet.of(KitType.HEAD)),
			// changing gloves would remove torso item and thereby change arms
			new DisallowCase(
				ImmutableMap.of(KitType.ARMS, LockStatus.ALL),
				ImmutableSet.of(TestData.plagueJacket),
				KitType.HANDS,
				TestData.leatherGloves,
				ImmutableSet.of(KitType.ARMS))
		);
	}

	@ParameterizedTest
	@MethodSource("provideDisallows")
	void disallowed(DisallowCase c)
	{
		c.locks.forEach((key, value) -> locks.set(key, value));
		c.items.forEach(i -> layers.getVirtualModels().getItems().put(i.getSlot(), i));
		assertEquals(c.conflicts, locks.conflictingSlots(c.slot, c.info));
		resetData();
	}

	@Override
	protected void resetData()
	{
		for (KitType k : KitType.values())
		{
			locks.set(k, null);
		}
		for (ColorType c : ColorType.values())
		{
			locks.set(c, false);
		}
		locks.setIcon(false);
		super.resetData();
	}
}

