    private static void save(SessionStore store, String acct, String id, String category,
                             String name, long start, long end, List<StoredTrip> trips) {
        StoredSession s = new StoredSession();
        s.id = id;
        s.accountHash = acct;
        s.category = category;
        s.name = name;
        s.startMillis = start;
        s.endMillis = end;
        s.trips = trips;
        store.save(s);
