        // 1 trip: looted 4 sharks (ate 3), gathered 5 logs (burned 2).
        Map<ItemKey, Integer> picked = new HashMap<>();
        picked.put(shark, 4);
        Map<ItemKey, Integer> gathered = new HashMap<>();
        gathered.put(logs, 5);
