        Trip t1 = new Trip("t1", 0, 3_600_000L, false, new HashMap<>(), new HashMap<>(),
                pickedA, new HashMap<>(), new HashMap<>(), gatheredA, new HashMap<>());
        // Trip B: gathered 40 logs only. 1h.
