	public static WealthSnapshot create(
		long bankValue,
		long inventoryValue,
		long equipmentValue,
		long coinsInHand,
		long lootingBagValue,
		long seedVaultValue,
		long groupStorageValue,
		Map<Integer, ItemSnapshot> breakdown)
	{
