    private boolean shownLoginHint = false;

    // Tracks whether we've shown the loaded-task-count banner this session
    private boolean shownVersionBanner = false;

    @Override
    protected void startUp() throws Exception
    {
        log.debug("Demonic Pacts Task Highlighter started - loaded {} tasks", TaskDatabase.getAllTasks().size());
        overlayManager.add(npcOverlay);
        overlayManager.add(itemOverlay);
        overlayManager.add(groundOverlay);
        overlayManager.add(tooltipOverlay);
        overlayManager.add(objectOverlay);
        overlayManager.add(xpTrimOverlay);
        overlayManager.add(spellbookOverlay);
        overlayManager.add(prayerOverlay);

        // Register the widget-based tracker to receive WidgetLoaded events
        eventBus.register(taskTracker);

        if (client.getGameState() == GameState.LOGGED_IN)
        {
            completedTaskManager.loadForCurrentProfile();
            hiddenTaskManager.loadForCurrentProfile();
            // If the plugin was enabled while already logged in, hint now (next tick)
            clientThread.invokeLater(this::showLoginHintIfNeeded);
        }
    }

    @Override
    protected void shutDown() throws Exception
    {
        overlayManager.remove(npcOverlay);
        overlayManager.remove(itemOverlay);
        overlayManager.remove(groundOverlay);
        overlayManager.remove(tooltipOverlay);
        overlayManager.remove(objectOverlay);
        overlayManager.remove(xpTrimOverlay);
        overlayManager.remove(spellbookOverlay);
        overlayManager.remove(prayerOverlay);
        eventBus.unregister(taskTracker);
        taskTracker.clear();
        completedTaskManager.onLogout();
        hiddenTaskManager.onLogout();
        shownLoginHint = false;
        log.debug("Demonic Pacts Task Highlighter stopped");
    }

    @Provides
    DemonicPactsConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(DemonicPactsConfig.class);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            completedTaskManager.loadForCurrentProfile();
            hiddenTaskManager.loadForCurrentProfile();
            clientThread.invokeLater(this::showVersionBannerIfNeeded);
            clientThread.invokeLater(this::showLoginHintIfNeeded);
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            taskTracker.clear();
            completedTaskManager.onLogout();
            hiddenTaskManager.onLogout();
            shownLoginHint = false;
            shownVersionBanner = false;
        }
    }

    /**
     * Shows a chat message once per login confirming which build is running.
     * The task count changes whenever the database is updated, so it works
     * as a quick "did my new build actually load?" signal in dev sessions.
     */
    private void showVersionBannerIfNeeded()
    {
        if (shownVersionBanner || client.getGameState() != GameState.LOGGED_IN || !isLeaguesWorld())
        {
            return;
        }
        shownVersionBanner = true;

        String message = new ChatMessageBuilder()
            .append(Color.MAGENTA, "[Demonic Pacts] ")
            .append(Color.WHITE, "Loaded " + TaskDatabase.getAllTasks().size() + " tasks.")
            .build();

        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
    }

    /**
     * Shows a chat message once per session reminding the player to open the
     * Leagues task log so the plugin can sync completed tasks via widget 657.
     */
    private void showLoginHintIfNeeded()
    {
        if (shownLoginHint || !config.showLoginHint() || client.getGameState() != GameState.LOGGED_IN || !isLeaguesWorld())
        {
            return;
        }
        shownLoginHint = true;

        String message = new ChatMessageBuilder()
            .append(Color.MAGENTA, "[Demonic Pacts] ")
            .append(Color.WHITE, "Open the Leagues task menu so completed tasks sync automatically.")
            .build();

        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
    }

    /**
     * Every game tick, sync widget tracker completions into CompletedTaskManager.
     * When the tracker reports newly-synced tasks (i.e. tasks completed before
     * the plugin was installed that just showed up from the task log widget),
     * emit a one-shot chat message so the player knows the sync worked.
     */
    @Subscribe
    public void onGameTick(net.runelite.api.events.GameTick event)
    {
        if (!config.autoDetectCompletion() || client.getGameState() != GameState.LOGGED_IN || !isLeaguesWorld())
        {
            return;
        }

        // Drain any tasks the widget tracker discovered since the last tick.
        // The tracker stores canonical TaskDatabase names already, so we can
        // mark them all completed in a single batch (one config-write) instead
        // of iterating ALL_TASKS and saving per task — that O(N) loop was
        // visible as client lag while the league task panel was open.
        Set<String> newlySynced = taskTracker.drainNewlySynced();
        if (newlySynced.isEmpty())
        {
            return;
        }
        completedTaskManager.markCompletedBatch(newlySynced);

        int count = newlySynced.size();
        String msg = new ChatMessageBuilder()
            .append(Color.MAGENTA, "[Demonic Pacts] ")
            .append(Color.WHITE, "Synced " + count + " completed task" + (count == 1 ? "" : "s") + " from your task log.")
            .build();
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null);
    }

    /**
     * Auto-detect task completion from league chat messages.
     * Game format: "Congratulations, you've completed an easy task: TASK NAME"
     */
    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (!config.autoDetectCompletion() || !isLeaguesWorld())
        {
            return;
        }

        if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
        {
            return;
        }

        String message = Text.removeTags(event.getMessage());

        if ((message.contains("you've completed") || message.contains("you have completed")) && message.contains("task"))
        {
            int colonIdx = message.lastIndexOf(':');
            if (colonIdx >= 0 && colonIdx < message.length() - 1)
            {
                String taskName = message.substring(colonIdx + 1).trim();
                if (taskName.endsWith("."))
                {
                    taskName = taskName.substring(0, taskName.length() - 1).trim();
                }

                // Try exact match
                for (DemonicPactsTask task : TaskDatabase.getAllTasks())
                {
                    if (task.getName().equalsIgnoreCase(taskName))
                    {
                        completedTaskManager.markCompleted(task.getName());
                        taskTracker.addCompleted(task.getName());
                        log.debug("Chat-detected task completion: {}", task.getName());
                        return;
                    }
                }

                // Fuzzy match
                for (DemonicPactsTask task : TaskDatabase.getAllTasks())
                {
                    if (message.toLowerCase().contains(task.getName().toLowerCase()))
                    {
                        completedTaskManager.markCompleted(task.getName());
                        taskTracker.addCompleted(task.getName());
                        log.debug("Chat-detected task completion (fuzzy): {}", task.getName());
                        return;
                    }
                }
            }
        }
    }

    // =========================================================================
    // Hide Task menu
    // =========================================================================

    private static final String HIDE_MENU_TEXT = "Hide task";
    private static final String COMPLETE_MENU_TEXT = "Mark complete";

    /**
     * Inject a red "Hide task: <Name>" menu entry for each task matching the
     * hovered NPC, item (inventory/bank/equipment/ground), or game object.
     * Hidden tasks still appear in this menu with prefix "Unhide task" so the
     * player can reverse the action from the same context.
     */
    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (!config.enableHideTaskMenu() || !isLeaguesWorld())
        {
            return;
        }

        MenuEntry entry = event.getMenuEntry();
        MenuAction type = entry.getType();
        String cleanTarget = Text.removeTags(entry.getTarget()).trim();

        // Inject on Examine entries for NPCs, world objects, and ground items.
        // For inventory/bank/equipment, the Examine action type is different
        // (CC_OP_LOW_PRIORITY with "Examine" as the option text) so we match
        // by option text as well. Also inject on widget-action entries
        // ("Cast", "Activate", etc.) so spells and prayers get the same
        // hide-task option as the rest of the highlight surfaces.
        String optionLower = Text.removeTags(entry.getOption()).toLowerCase();
        boolean isExamine = type == MenuAction.EXAMINE_NPC
            || type == MenuAction.EXAMINE_OBJECT
            || type == MenuAction.EXAMINE_ITEM_GROUND
            || type == MenuAction.EXAMINE_ITEM
            || (type == MenuAction.CC_OP_LOW_PRIORITY
                && "examine".equals(optionLower));
        boolean isWidgetAction = (type == MenuAction.CC_OP || type == MenuAction.CC_OP_LOW_PRIORITY)
            && (optionLower.startsWith("cast")
                || optionLower.startsWith("activate")
                || optionLower.startsWith("reactivate")
                || optionLower.startsWith("deactivate")
                || optionLower.startsWith("toggle"));
        if (!isExamine && !isWidgetAction)
        {
            return;
        }

        Set<DemonicPactsTask> matches = new HashSet<>();

        // NPC tasks
        NPC npc = entry.getNpc();
        if (npc != null && npc.getName() != null)
        {
            matches.addAll(TaskDatabase.findNpcTasks(npc.getName()));
            // Fishing spots are NPCs but tasks are mapped via object keywords —
            // gated to fishing-spot-like names since findObjectTasks now falls
            // back to ITEM_TASKS (which would over-match generic NPC names).
            if (npc.getName().toLowerCase().contains("fishing spot"))
            {
                matches.addAll(TaskDatabase.findObjectTasks(npc.getName()));
            }
        }

        // Inventory / bank / equipment: resolve by item ID when available
        int itemId = entry.getItemId();
        if (itemId >= 0)
        {
            try
            {
                String resolvedName = itemManager.getItemComposition(itemId).getName();
                if (resolvedName != null && !resolvedName.isEmpty() && !"null".equals(resolvedName))
                {
                    matches.addAll(TaskDatabase.findItemTasks(resolvedName));
                }
            }
            catch (Exception ignored) {}
        }

        // Item tasks (ground examine gives item name via target)
        if (!cleanTarget.isEmpty())
        {
            matches.addAll(TaskDatabase.findItemTasks(cleanTarget));
            matches.addAll(TaskDatabase.findObjectTasks(cleanTarget));
            // Also try NPC lookup by target text as a fallback
            if (npc == null)
            {
                matches.addAll(TaskDatabase.findNpcTasks(cleanTarget));
            }
        }

        if (matches.isEmpty())
        {
            return;
        }

        // Check existing menu entries to avoid injecting duplicate "Hide task" lines
        // when the game fires onMenuEntryAdded multiple times (e.g. stacks of ground items).
        MenuEntry[] existing = client.getMenuEntries();

        for (DemonicPactsTask task : matches)
        {
            // Skip already-hidden tasks so players can't unhide from the right-click menu.
            // They must use the "Unhide All Tasks" config toggle instead.
            if (hiddenTaskManager.isHidden(task))
            {
                continue;
            }

            // Skip completed tasks — no point offering to hide something already done.
            if (completedTaskManager.isCompleted(task))
            {
                continue;
            }

            // Skip tasks whose region the user has disabled — they wouldn't see
            // the highlight anyway, so offering to hide is just noise.
            if (!isTaskRegionEnabled(task))
            {
                continue;
            }

            // Dedup: don't add the same Hide task entry twice in the same menu cycle
            boolean alreadyThere = false;
            String wantTarget = "<col=ffaa00>" + task.getName() + "</col>";
            for (MenuEntry me : existing)
            {
                if (me.getType() == MenuAction.RUNELITE
                    && wantTarget.equals(me.getTarget())
                    && me.getOption() != null
                    && me.getOption().contains(HIDE_MENU_TEXT))
                {
                    alreadyThere = true;
                    break;
                }
            }
            if (alreadyThere)
            {
                continue;
            }

            client.createMenuEntry(-1)
                .setOption("<col=ff0000>" + HIDE_MENU_TEXT + "</col>")
                .setTarget(wantTarget)
                .setType(MenuAction.RUNELITE)
                .onClick(e -> hiddenTaskManager.hide(task.getName()));
        }
    }

    /**
     * When the player ticks the "Unhide All Tasks" config box, clear the
     * hidden-task set for this account and reset the toggle so it can be used
     * again later.
     */
    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"demonicpactstaskhighlighter".equals(event.getGroup()))
        {
            return;
        }
        if ("unhideAllTasks".equals(event.getKey()) && "true".equals(event.getNewValue()))
        {
            int count = hiddenTaskManager.getHiddenCount();
            hiddenTaskManager.clearAll();
            configManager.setConfiguration("demonicpactstaskhighlighter", "unhideAllTasks", false);

            String msg = new ChatMessageBuilder()
                .append(Color.MAGENTA, "[Demonic Pacts] ")
                .append(Color.WHITE, "Unhid " + count + " task" + (count == 1 ? "" : "s") + ".")
                .build();
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null);
        }
    }

    // =========================================================================
    // World gating
    // =========================================================================

    /**
     * Returns true if the player is currently on a Leagues / seasonal world.
     * The plugin's whole purpose is highlighting Demonic Pacts league tasks,
     * so on regular worlds it stays out of the way: no highlights, no
     * tooltips, no menu injections, no chat banners. Players logging into
     * the main game shouldn't see plugin behaviour.
     */
    public boolean isLeaguesWorld()
    {
        Set<WorldType> wt = client.getWorldType();
        return wt != null && wt.contains(WorldType.SEASONAL);
    }

    // =========================================================================
    // Region filtering
    // =========================================================================

    /**
     * Returns true if the given task's area is currently enabled in the
     * Regions config section. "General" tasks are always shown since they
     * aren't tied to any unlock.
     */
    public boolean isTaskRegionEnabled(DemonicPactsTask task)
    {
        if (task == null)
        {
            return true;
        }
        String area = task.getArea();
        if (area == null || area.isEmpty() || "General".equalsIgnoreCase(area))
        {
            return true;
        }
        switch (area.toLowerCase())
        {
            case "asgarnia":   return config.regionAsgarnia();
            case "desert":     return config.regionDesert();
            case "fremennik":  return config.regionFremennik();
            case "kandarin":   return config.regionKandarin();
            case "karamja":    return config.regionKaramja();
            case "kourend":    return config.regionKourend();
            case "morytania":  return config.regionMorytania();
            case "tirannwn":   return config.regionTirannwn();
            case "varlamore":  return config.regionVarlamore();
            case "wilderness": return config.regionWilderness();
            default:           return true; // Unknown area — show by default
        }
    }

    /**
     * Convenience: filter a list of tasks down to those in enabled regions.
     * Returns a new list — the input is not modified.
     */
    public java.util.List<DemonicPactsTask> filterByEnabledRegions(java.util.List<DemonicPactsTask> tasks)
    {
        java.util.List<DemonicPactsTask> result = new java.util.ArrayList<>();
        for (DemonicPactsTask task : tasks)
        {
            if (isTaskRegionEnabled(task))
            {
                result.add(task);
            }
        }
        return result;
    }
}

package com.demonicpacts;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/**
 * Mirror of DemonicPactsSpellbookOverlay for the prayer book. Outlines
 * prayer icons that match outstanding "Activate X" / "Use the X Prayer"
 * tasks. Configurable via DemonicPactsConfig#highlightSpellbook (we
 * piggy-back on the same toggle since spells and prayers are the same
 * conceptual highlight surface).
 */
@Slf4j
public class DemonicPactsPrayerOverlay extends Overlay
{
    // Standard prayer book widget group (resizable).
    private static final int PRAYER_GROUP = 541;
    // Ruinous Powers (League / Necromancy spellbook variant) — included for
    // safety; harmless if not present in the player's account.
    private static final int RUINOUS_PRAYER_GROUP = 916;

    private static final Color OUTLINE_COLOR = new Color(255, 255, 0, 200);

    private final Client client;
    private final DemonicPactsConfig config;
    private final DemonicPactsPlugin plugin;

    @Inject
    DemonicPactsPrayerOverlay(Client client, DemonicPactsConfig config, DemonicPactsPlugin plugin)
    {
        this.client = client;
        this.config = config;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isLeaguesWorld() || !config.highlightSpellbook())
        {
            return null;
        }

        Set<String> keywords = collectIncompletePrayerKeywords();
        if (keywords.isEmpty())
        {
            return null;
        }

        graphics.setStroke(new BasicStroke(2f));
        graphics.setColor(OUTLINE_COLOR);

        for (int groupId : new int[]{PRAYER_GROUP, RUINOUS_PRAYER_GROUP})
        {
            Widget root = client.getWidget(groupId, 0);
            if (root == null || root.isHidden())
            {
                continue;
            }
            scanRecursive(graphics, root, keywords);
        }
        return null;
    }

    /**
     * Collect the names of prayers the player still has outstanding tasks
     * for. Tasks like "Activate Piety" / "Use the Piety Prayer" yield "piety"
     * after stripping the verb prefix and trailing " prayer".
     */
    private Set<String> collectIncompletePrayerKeywords()
    {
        Set<String> out = new HashSet<>();
        CompletedTaskManager mgr = plugin.getCompletedTaskManager();
        HiddenTaskManager hidden = plugin.getHiddenTaskManager();
        String[] prefixes = {"activate ", "use the ", "reactivate "};
        for (DemonicPactsTask task : TaskDatabase.getAllTasks())
        {
            if (mgr.isCompleted(task)) continue;
            if (hidden.isHidden(task)) continue;
            // Respect the per-region toggles so disabling a region also
            // hides the prayer circles for prayers scoped to it.
            if (!plugin.isTaskRegionEnabled(task)) continue;

            String n = task.getName();
            if (n == null) continue;
            String lower = n.toLowerCase(Locale.ROOT);
            for (String prefix : prefixes)
            {
                if (!lower.startsWith(prefix)) continue;
                String rest = lower.substring(prefix.length()).trim();
                if (rest.endsWith(" prayer"))
                {
                    rest = rest.substring(0, rest.length() - " prayer".length()).trim();
                }
                else if (!lower.contains("prayer"))
                {
                    // Skip non-prayer activate-tasks (e.g. "Activate the Statue
                    // of Ates"). Only keep verbs that look prayer-related.
                    break;
                }
                if (!rest.isEmpty())
                {
                    out.add(rest);
                }
                break;
            }
        }
        return out;
    }

    private void scanRecursive(Graphics2D graphics, Widget parent, Set<String> keywords)
    {
        scanArray(graphics, parent.getStaticChildren(), keywords);
        scanArray(graphics, parent.getDynamicChildren(), keywords);
        scanArray(graphics, parent.getNestedChildren(), keywords);
    }

    private void scanArray(Graphics2D graphics, Widget[] arr, Set<String> keywords)
    {
        if (arr == null) return;
        for (Widget w : arr)
        {
            if (w == null || w.isHidden()) continue;
            String name = w.getName();
            if (name != null && !name.isEmpty())
            {
                String cleaned = name.replaceAll("<[^>]*>", "").trim().toLowerCase(Locale.ROOT);
                if (keywords.contains(cleaned))
                {
                    drawOutline(graphics, w);
                }
            }
            scanRecursive(graphics, w, keywords);
        }
    }

    private void drawOutline(Graphics2D graphics, Widget w)
    {
        Rectangle b = w.getBounds();
        if (b == null || b.width <= 0 || b.height <= 0) return;
        graphics.drawOval(b.x - 1, b.y - 1, b.width + 1, b.height + 1);
    }
}

package com.demonicpacts;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Draws a coloured circle around spell icons in the magic spellbook when the
 * player has outstanding "Cast X" tasks for those spells.
 *
 * Strategy: walk all known spellbook widget groups (standard / ancient /
 * lunar / arceuus), check each child widget's getName() against a set of
 * task keywords compiled from incomplete TaskType.SPELL tasks, and outline
 * matches. Best-effort first attempt — if Jagex names a spell widget
 * differently in any spellbook we may need to add aliases.
 */
@Slf4j
public class DemonicPactsSpellbookOverlay extends Overlay
{
    // Standard spellbook widget IDs (resizable client). The spellbook has
    // separate group IDs depending on which spellbook is active.
    private static final int[] SPELLBOOK_GROUPS = {
        218,  // Standard / modern
        217,  // Ancient
        430,  // Lunar
        220,  // Arceuus
    };

    private static final Color OUTLINE_COLOR = new Color(255, 0, 255, 200);

    private final Client client;
    private final DemonicPactsConfig config;
    private final DemonicPactsPlugin plugin;

    @Inject
    DemonicPactsSpellbookOverlay(Client client, DemonicPactsConfig config, DemonicPactsPlugin plugin)
    {
        this.client = client;
        this.config = config;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isLeaguesWorld() || !config.highlightSpellbook())
        {
            return null;
        }

        // Build a set of spell keywords from outstanding SPELL-type tasks.
        // Cheap to recompute every frame at this scale — there aren't many
        // SPELL tasks in the database.
        Set<String> spellKeywords = collectIncompleteSpellKeywords();
        if (spellKeywords.isEmpty())
        {
            return null;
        }

        graphics.setStroke(new BasicStroke(2f));
        graphics.setColor(OUTLINE_COLOR);

        for (int groupId : SPELLBOOK_GROUPS)
        {
            Widget root = client.getWidget(groupId, 0);
            if (root == null || root.isHidden())
            {
                continue;
            }
            drawMatchingChildren(graphics, root, spellKeywords);
        }
        return null;
    }

    private Set<String> collectIncompleteSpellKeywords()
    {
        Set<String> out = new HashSet<>();
        CompletedTaskManager mgr = plugin.getCompletedTaskManager();
        HiddenTaskManager hidden = plugin.getHiddenTaskManager();
        for (DemonicPactsTask task : TaskDatabase.getAllTasks())
        {
            String name = task.getName();
            // Accept any task named "Cast X" regardless of TaskType so newer
            // tasks I added with TaskType.ACTIVITY (Claws of Guthix, Saradomin
            // Strike, etc.) still light up.
            boolean nameMatch = name != null && name.toLowerCase(Locale.ROOT).startsWith("cast ");
            if (!nameMatch && task.getType() != TaskType.SPELL)
            {
                continue;
            }
            if (mgr.isCompleted(task)) continue;
            if (hidden.isHidden(task)) continue;
            // Respect the per-region toggles so disabling a region also turns
            // off the spell circles for tasks scoped to it.
            if (!plugin.isTaskRegionEnabled(task)) continue;

            if (task.getMatchKeywords() != null)
            {
                for (String kw : task.getMatchKeywords())
                {
                    if (kw != null && !kw.isEmpty())
                    {
                        out.add(kw.toLowerCase(Locale.ROOT));
                    }
                }
            }
            if (nameMatch)
            {
                out.add(name.substring(5).toLowerCase(Locale.ROOT));
            }
        }
        return out;
    }

    /**
     * Recursively scan widget children. The spellbook tree typically has
     * spell icons as static or nested children; we match by widget name.
     */
    private void drawMatchingChildren(Graphics2D graphics, Widget parent, Set<String> keywords)
    {
        scanArray(graphics, parent.getStaticChildren(), keywords);
        scanArray(graphics, parent.getDynamicChildren(), keywords);
        scanArray(graphics, parent.getNestedChildren(), keywords);
    }

    private void scanArray(Graphics2D graphics, Widget[] arr, Set<String> keywords)
    {
        if (arr == null)
        {
            return;
        }
        for (Widget w : arr)
        {
            if (w == null || w.isHidden())
            {
                continue;
            }
            String name = w.getName();
            if (name != null && !name.isEmpty())
            {
                String cleaned = name.replaceAll("<[^>]*>", "").trim().toLowerCase(Locale.ROOT);
                if (keywords.contains(cleaned))
                {
                    drawOutline(graphics, w);
                }
            }
            // Recurse — some spellbook variants nest icons in sub-containers.
            drawMatchingChildren(graphics, w, keywords);
        }
    }

    private void drawOutline(Graphics2D graphics, Widget w)
    {
        Rectangle b = w.getBounds();
        if (b == null || b.width <= 0 || b.height <= 0)
        {
            return;
        }
        // Draw an oval rather than a rect for spells, since spell icons are
        // round in the OSRS UI.
        graphics.drawOval(b.x - 1, b.y - 1, b.width + 1, b.height + 1);
    }
}

package com.demonicpacts;

import lombok.Builder;
import lombok.Value;

@Value
@Builder
public class DemonicPactsTask
{
    String name;
    String description;
    String area;
    TaskDifficulty difficulty;
    TaskType type;
    String requirements;
    /**
     * Keywords to match against in-game entity names (NPC names, item names, etc.)
     * Matching is case-insensitive.
     */
    String[] matchKeywords;
    int quantity;
}

package com.demonicpacts;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import javax.inject.Inject;
import java.awt.*;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class DemonicPactsTooltipOverlay extends Overlay
{
    private static final Pattern SKILL_REQ_PATTERN = Pattern.compile(
        "\\b(Attack|Defence|Strength|Hitpoints|Ranged|Prayer|Magic|Runecraft|Construction|Agility|Herblore|Thieving|Crafting|Fletching|Slayer|Hunter|Mining|Smithing|Fishing|Cooking|Firemaking|Woodcutting|Farming)\\s+(\\d+)\\+?");

    private final Client client;
    private final DemonicPactsConfig config;
    private final TooltipManager tooltipManager;
    private final ItemManager itemManager;
    private final DemonicPactsPlugin plugin;

    @Inject
    DemonicPactsTooltipOverlay(Client client, DemonicPactsConfig config, TooltipManager tooltipManager, ItemManager itemManager, DemonicPactsPlugin plugin)
    {
        this.client = client;
        this.config = config;
        this.tooltipManager = tooltipManager;
        this.itemManager = itemManager;
        this.plugin = plugin;
        setPosition(OverlayPosition.TOOLTIP);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGHEST);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isLeaguesWorld() || !config.showTooltips())
        {
            return null;
        }

        MenuEntry[] menuEntries = client.getMenuEntries();
        if (menuEntries.length == 0)
        {
            return null;
        }

        // Check the top (hovered) entry first
        MenuEntry topEntry = menuEntries[menuEntries.length - 1];
        String topTarget = topEntry.getTarget().replaceAll("<[^>]*>", "").trim();

        // 1. Check NPC tasks via entry.getNpc()
        NPC npc = topEntry.getNpc();
        if (npc != null && npc.getName() != null)
        {
            List<DemonicPactsTask> tasks = TaskDatabase.findNpcTasks(npc.getName());
            if (tasks.isEmpty())
            {
                // Fishing spots and similar are NPCs but tasks are keyed to object
                // names via OBJECT_TO_TASK_KEYWORDS. Try the object lookup too.
                tasks = TaskDatabase.findObjectTasks(npc.getName());
            }
            if (!tasks.isEmpty() && isNpcVisible(npc))
            {
                String text = buildTooltipText(tasks, npc.getName());
                if (text != null) tooltipManager.add(new Tooltip(text));
                return null;
            }
        }

        // 2. Check top entry target against both databases
        if (!topTarget.isEmpty())
        {
            String text = tryBuildTooltip(topTarget, topEntry);
            if (text != null)
            {
                tooltipManager.add(new Tooltip(text));
                return null;
            }
        }

        // 3. If top entry didn't match (e.g. "Walk here" on stacked ground items),
        //    scan ALL menu entries for task-related items/NPCs
        for (int i = menuEntries.length - 2; i >= 0; i--)
        {
            MenuEntry entry = menuEntries[i];
            String entryTarget = entry.getTarget().replaceAll("<[^>]*>", "").trim();

            if (entryTarget.isEmpty())
            {
                continue;
            }

            // Check NPC
            NPC entryNpc = entry.getNpc();
            if (entryNpc != null && entryNpc.getName() != null)
            {
                List<DemonicPactsTask> tasks = TaskDatabase.findNpcTasks(entryNpc.getName());
                if (!tasks.isEmpty() && isNpcVisible(entryNpc))
                {
                    String text = buildTooltipText(tasks, entryNpc.getName());
                    if (text != null)
                    {
                        tooltipManager.add(new Tooltip(text));
                        return null;
                    }
                }
            }

            // Check items
            String text = tryBuildTooltip(entryTarget, entry);
            if (text != null)
            {
                tooltipManager.add(new Tooltip(text));
                return null;
            }
        }

        return null;
    }

    /**
     * Try to build a tooltip for a given target name, checking item ID, item name,
     * NPC, and world object databases. Gated by RenderedHighlights so we only
     * show a tooltip for entities the overlays are actually drawing a highlight
     * on right now.
     */
    private String tryBuildTooltip(String cleanTarget, MenuEntry entry)
    {
        RenderedHighlights rh = plugin.getRenderedHighlights();
        MenuAction type = entry.getType();

        // Skip all player-targeting menu actions — players wearing gear or having
        // certain names can accidentally match item/NPC databases, and there are
        // no tasks where the subject is "that other player".
        if (isPlayerAction(type))
        {
            return null;
        }

        // Widget-action fast path (spells, prayers, anywhere a "Cast / Activate
        // / Toggle" option appears on a widget). The regular item / NPC /
        // object visibility gates were designed for world entities and don't
        // apply here, so we look up and return directly when the option text
        // matches a known widget-action verb. Gated by the spellbook toggle so
        // the user can turn this off.
        if (isWidgetActionEntry(entry) && config.highlightSpellbook())
        {
            List<DemonicPactsTask> tasks = TaskDatabase.findItemTasks(cleanTarget);
            if (!tasks.isEmpty())
            {
                return buildTooltipText(tasks, cleanTarget);
            }
        }

        // Try item ID first (for inventory/bank items)
        if (type == MenuAction.CC_OP || type == MenuAction.CC_OP_LOW_PRIORITY)
        {
            int itemId = entry.getItemId();
            if (itemId >= 0)
            {
                try
                {
                    String itemName = itemManager.getItemComposition(itemId).getName();
                    List<DemonicPactsTask> tasks = TaskDatabase.findItemTasks(itemName);
                    if (!tasks.isEmpty() && isItemVisible(itemName))
                    {
                        return buildTooltipText(tasks, itemName);
                    }
                }
                catch (Exception ignored) {}
            }
        }

        // Try ground item actions — require the ground item to actually be highlighted
        if (isGroundItemAction(entry))
        {
            List<DemonicPactsTask> tasks = TaskDatabase.findItemTasks(cleanTarget);
            if (!tasks.isEmpty() && isGroundVisible(entry, cleanTarget))
            {
                return buildTooltipText(tasks, cleanTarget);
            }
        }

        // Fallback: try clean target against NPC database (with visibility)
        List<DemonicPactsTask> npcTasks = TaskDatabase.findNpcTasks(cleanTarget);
        if (!npcTasks.isEmpty())
        {
            // No precise NPC reference here — use name-level check
            if (rh.isNpcRenderedByName(cleanTarget) || !config.onePerType())
            {
                return buildTooltipText(npcTasks, cleanTarget);
            }
        }

        List<DemonicPactsTask> itemTasks = TaskDatabase.findItemTasks(cleanTarget);
        if (!itemTasks.isEmpty() && isItemVisible(cleanTarget))
        {
            return buildTooltipText(itemTasks, cleanTarget);
        }

        // World objects — must pass category toggle AND (if onePerType on) be the rendered one
        List<DemonicPactsTask> objectTasks = TaskDatabase.findObjectTasks(cleanTarget);
        if (!objectTasks.isEmpty() && isObjectVisible(entry, cleanTarget))
        {
            return buildTooltipText(objectTasks, cleanTarget);
        }

        return null;
    }

    /**
     * An NPC is "visible" for tooltip purposes if the NPC overlay is actually
     * drawing a highlight on it this frame.
     */
    private boolean isNpcVisible(NPC npc)
    {
        if (!config.highlightNpcs())
        {
            return false;
        }
        // When onePerType is off, every matching NPC is rendered so tooltip is fine.
        if (!config.onePerType())
        {
            return true;
        }
        return plugin.getRenderedHighlights().isNpcRendered(npc.getIndex());
    }

    /**
     * An item (inventory/bank/equipment) is "visible" if the item overlay drew
     * a border on it this frame. One Per Type doesn't apply to items (causes
     * flicker at high framerates) so any matching item is considered visible.
     */
    private boolean isItemVisible(String itemName)
    {
        return config.highlightItems();
    }

    /**
     * Ground-item visibility: when onePerType is on, tie the hovered tile to
     * the rendered set. Strict — no fallbacks, otherwise one rendered pile
     * would unlock tooltips on every pile of the same name.
     */
    private boolean isGroundVisible(MenuEntry entry, String itemName)
    {
        if (!config.highlightGroundItems())
        {
            return false;
        }
        if (!config.onePerType())
        {
            return true;
        }
        WorldPoint wp = entryToWorldPoint(entry);
        if (wp == null)
        {
            return false;
        }
        // 2-tile tolerance same as objects — handles stacked piles that spread
        // across adjacent tiles plus coord-rounding between menu entry and mark.
        return plugin.getRenderedHighlights().isGroundRenderedNear(wp.getX(), wp.getY(), itemName, 2);
    }

    /**
     * World-object visibility: first check the category toggle (so hovering a
     * tree with "Highlight Trees" off shows nothing), then check the per-tile
     * rendered set if onePerType is on. Strict — must match the exact rendered
     * tile.
     */
    private boolean isObjectVisible(MenuEntry entry, String objectName)
    {
        if (!config.highlightObjects())
        {
            return false;
        }
        if (!shouldShowCategory(objectName))
        {
            return false;
        }
        if (!config.onePerType())
        {
            return true;
        }
        WorldPoint wp = entryToWorldPoint(entry);
        if (wp == null)
        {
            return false;
        }
        // 2-tile tolerance handles multi-tile scenery (trees occupy 2x2 areas,
        // big rocks can span 2+ tiles) and small coord-rounding between the
        // menu entry and the overlay's marked tile.
        return plugin.getRenderedHighlights().isObjectRenderedNear(wp.getX(), wp.getY(), objectName, 2);
    }

    /**
     * Mirror of ObjectOverlay.shouldShowCategory so the tooltip respects the
     * same per-category toggles as the visual overlay.
     */
    private boolean shouldShowCategory(String objectName)
    {
        if (objectName == null)
        {
            return true;
        }
        String n = objectName.toLowerCase();
        if (n.contains("tree")
            || n.equals("oak") || n.equals("willow") || n.equals("yew")
            || n.equals("maple") || n.equals("magic") || n.equals("teak")
            || n.equals("mahogany") || n.equals("redwood") || n.equals("blisterwood")
            || n.equals("padri") || n.equals("juniper"))
        {
            return config.highlightTrees();
        }
        if (n.contains("rocks") || n.endsWith(" rock"))
        {
            return config.highlightRocks();
        }
        if (n.contains("fishing spot"))
        {
            return config.highlightFishingSpots();
        }
        if (n.contains("patch") || n.contains("allotment"))
        {
            return config.highlightPatches();
        }
        return true;
    }

    /**
     * Resolve a MenuEntry's param0/param1 (scene-local tile coords) into a
     * WorldPoint for matching against RenderedHighlights. Returns null if the
     * conversion isn't possible.
     */
    private WorldPoint entryToWorldPoint(MenuEntry entry)
    {
        try
        {
            int sceneX = entry.getParam0();
            int sceneY = entry.getParam1();
            if (sceneX < 0 || sceneY < 0 || sceneX >= 104 || sceneY >= 104)
            {
                return null;
            }
            return WorldPoint.fromScene(client, sceneX, sceneY, client.getPlane());
        }
        catch (Throwable ignored)
        {
            return null;
        }
    }

    private boolean isGroundItemAction(MenuEntry entry)
    {
        MenuAction type = entry.getType();
        return type == MenuAction.GROUND_ITEM_FIRST_OPTION
            || type == MenuAction.GROUND_ITEM_SECOND_OPTION
            || type == MenuAction.GROUND_ITEM_THIRD_OPTION
            || type == MenuAction.GROUND_ITEM_FOURTH_OPTION
            || type == MenuAction.GROUND_ITEM_FIFTH_OPTION
            || type == MenuAction.EXAMINE_ITEM_GROUND;
    }

    private boolean isPlayerAction(MenuAction type)
    {
        return type == MenuAction.PLAYER_FIRST_OPTION
            || type == MenuAction.PLAYER_SECOND_OPTION
            || type == MenuAction.PLAYER_THIRD_OPTION
            || type == MenuAction.PLAYER_FOURTH_OPTION
            || type == MenuAction.PLAYER_FIFTH_OPTION
            || type == MenuAction.PLAYER_SIXTH_OPTION
            || type == MenuAction.PLAYER_SEVENTH_OPTION
            || type == MenuAction.PLAYER_EIGHTH_OPTION;
    }

    /**
     * Recognise spell / prayer widget-interaction menu entries. The option is
     * the verb shown to the player ("Cast" / "Activate" / etc.) and the type
     * is a generic component-click action. We treat any of these as
     * candidates for the widget-action tooltip path.
     */
    private boolean isWidgetActionEntry(MenuEntry entry)
    {
        MenuAction type = entry.getType();
        if (type != MenuAction.CC_OP && type != MenuAction.CC_OP_LOW_PRIORITY)
        {
            return false;
        }
        String optionLower = entry.getOption() == null ? ""
            : entry.getOption().replaceAll("<[^>]*>", "").trim().toLowerCase();
        // startsWith because some spells use "Cast (offensive)" / "Cast
        // (autocast)" and prayers can have "Activate (toggle)" variants.
        return optionLower.startsWith("cast")
            || optionLower.startsWith("activate")
            || optionLower.startsWith("reactivate")
            || optionLower.startsWith("deactivate")
            || optionLower.startsWith("toggle");
    }

    private String buildTooltipText(List<DemonicPactsTask> tasks, String entityName)
    {
        CompletedTaskManager ctm = plugin.getCompletedTaskManager();
        HiddenTaskManager htm = plugin.getHiddenTaskManager();
        StringBuilder sb = new StringBuilder();
        sb.append("<col=ffaa00>\u2694 Demonic Pacts League Task</col>");

        int shown = 0;
        for (int i = 0; i < tasks.size(); i++)
        {
            DemonicPactsTask task = tasks.get(i);
            boolean completed = ctm.isCompleted(task);
            boolean hidden = htm.isHidden(task);

            // Skip hidden tasks unless the player wants them faded
            if (hidden && !config.showHiddenInTooltip())
            {
                continue;
            }

            // Skip completed tasks unless configured to show them
            if (completed && config.hideCompleted() && !config.showCompletedInTooltip())
            {
                continue;
            }

            // Skip tasks in disabled regions — tooltip stays in sync with the overlay
            if (!plugin.isTaskRegionEnabled(task))
            {
                continue;
            }

            if (shown > 0)
            {
                sb.append("<br>---");
            }
            shown++;

            String hexColor = String.format("%06x", task.getDifficulty().getColor().getRGB() & 0xFFFFFF);

            // Show checkmark or X for completion status
            String statusIcon = completed ? "\u2714 " : (hidden ? "\u2300 " : "");
            String strikePrefix = (completed || hidden) ? "<col=666666>" : "";
            String strikeSuffix = (completed || hidden) ? "</col>" : "";

            sb.append("<br>").append(strikePrefix)
                .append(statusIcon)
                .append("<col=").append(hexColor).append(">")
                .append("[").append(task.getDifficulty().name()).append("]</col> ")
                .append(task.getName())
                .append(strikeSuffix);

            if (completed)
            {
                sb.append("<br><col=00ff00>COMPLETED</col>");
                continue;
            }
            if (hidden)
            {
                sb.append("<br><col=999999>HIDDEN</col>");
                continue;
            }

            sb.append("<br><col=b0b0b0>").append(task.getDescription()).append("</col>");

            if (config.showPoints())
            {
                sb.append("<br><col=ffffff>Points: </col><col=00ff00>")
                    .append(task.getDifficulty().getPoints()).append("</col>");
            }

            if (config.showArea() && !task.getArea().isEmpty())
            {
                sb.append("<br><col=ffffff>Area: </col><col=66ccff>")
                    .append(task.getArea()).append("</col>");
            }

            if (config.showRequirements() && task.getRequirements() != null && !task.getRequirements().isEmpty())
            {
                sb.append("<br><col=ffffff>Requires: </col>")
                    .append(formatRequirements(task.getRequirements()));
            }

            if (task.getQuantity() > 1)
            {
                sb.append("<br><col=ffffff>Quantity: </col><col=ffff00>")
                    .append(task.getQuantity()).append("</col>");
            }
        }

        if (shown == 0)
        {
            return null;
        }

        return sb.toString();
    }

    /**
     * Wrap each skill-level token (e.g. "Defence 60", "Hunter 29+") in a green
     * or red color tag based on the player's real level vs the required level.
     * Non-skill text (quest names, connectors) is left uncolored.
     */
    private String formatRequirements(String requirements)
    {
        Matcher m = SKILL_REQ_PATTERN.matcher(requirements);
        StringBuilder out = new StringBuilder();
        int last = 0;
        while (m.find())
        {
            out.append(requirements, last, m.start());
            int reqLevel = Integer.parseInt(m.group(2));
            int playerLevel = client.getRealSkillLevel(Skill.valueOf(m.group(1).toUpperCase()));
            String color = playerLevel >= reqLevel ? "00ff00" : "ff6666";
            out.append("<col=").append(color).append(">").append(m.group()).append("</col>");
            last = m.end();
        }
        out.append(requirements.substring(last));
        return out.toString();
    }
}

package com.demonicpacts;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Outlines skill orbs in the resizable stats tab when the player's XP for that
 * skill crosses any of the league task XP milestones (99 / 25M / 35M / 50M /
 * 100M / 200M). Implements GitHub issue #18.
 *
 * Skill widget detection is best-effort: we walk the dynamic children of the
 * stats container (widget group 320) and match each child's name against
 * known skill names. If Jagex changes the widget structure later we may need
 * to revisit. Configurable via DemonicPactsConfig#xpTrimEnabled.
 */
@Slf4j
public class DemonicPactsXpTrimOverlay extends Overlay
{
    // Resizable-layout stats tab group ID. 320:0 is the root container.
    private static final int STATS_GROUP_ID = 320;

    // Milestone XP thresholds and matching outline colours, in ascending
    // order. The highest milestone the player has crossed wins.
    private static final int[] MILESTONE_XP = {
        13_034_431,   // 99
        25_000_000,   // 25M
        35_000_000,   // 35M
        50_000_000,   // 50M
        100_000_000,  // 100M
        200_000_000,  // 200M
    };

    private static final Color[] MILESTONE_COLORS = {
        new Color(102, 204, 102),   // 99   — green
        new Color(102, 204, 255),   // 25M  — light blue
        new Color(180, 102, 255),   // 35M  — purple
        new Color(255, 153, 51),    // 50M  — orange
        new Color(255, 215, 0),     // 100M — gold
        new Color(255, 51, 51),     // 200M — red
    };

    private final Client client;
    private final DemonicPactsConfig config;
    private final DemonicPactsPlugin plugin;

    // Maps lowercased Skill.getName() to the enum value. Built once.
    private final Map<String, Skill> skillByName;

    @Inject
    DemonicPactsXpTrimOverlay(Client client, DemonicPactsConfig config, DemonicPactsPlugin plugin)
    {
        this.client = client;
        this.config = config;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);

        skillByName = new HashMap<>();
        for (Skill s : Skill.values())
        {
            if (s.getName() != null)
            {
                skillByName.put(s.getName().toLowerCase(Locale.ROOT), s);
            }
        }
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isLeaguesWorld() || !config.xpTrimEnabled())
        {
            return null;
        }

        Widget root = client.getWidget(STATS_GROUP_ID, 0);
        if (root == null || root.isHidden())
        {
            return null;
        }

        Widget[] children = root.getDynamicChildren();
        if (children == null || children.length == 0)
        {
            children = root.getStaticChildren();
        }
        if (children == null)
        {
            return null;
        }

        graphics.setStroke(new BasicStroke(2f));
        for (Widget child : children)
        {
            if (child == null)
            {
                continue;
            }
            String name = child.getName();
            if (name == null || name.isEmpty())
            {
                continue;
            }
            // Widget names sometimes come back like "<col=...>Attack</col>" —
            // strip tags before matching.
            String cleaned = name.replaceAll("<[^>]*>", "").trim().toLowerCase(Locale.ROOT);
            Skill skill = skillByName.get(cleaned);
            if (skill == null)
            {
                continue;
            }
            int xp = client.getSkillExperience(skill);
            int tier = -1;
            for (int i = 0; i < MILESTONE_XP.length; i++)
            {
                if (xp >= MILESTONE_XP[i])
                {
                    tier = i;
                }
            }
            if (tier < 0)
            {
                continue;
            }
            Rectangle bounds = child.getBounds();
            if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
            {
                continue;
            }
            graphics.setColor(MILESTONE_COLORS[tier]);
            graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
        }
        return null;
    }
}

package com.demonicpacts;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Tracks tasks the player has explicitly hidden via the right-click menu.
 * Hidden tasks are filtered out of all highlights and tooltips, similar to
 * completed tasks but managed separately so the player can choose to skip a
 * task without pretending they finished it.
 *
 * Persisted per RuneScape account via ConfigManager's RSProfile scope.
 */
@Slf4j
@Singleton
public class HiddenTaskManager
{
    private static final String CONFIG_GROUP = "demonicpactstaskhighlighter";
    private static final String CONFIG_KEY = "hiddenTasks";

    private final ConfigManager configManager;
    private final Set<String> hiddenTasks = new HashSet<>();

    @Inject
    public HiddenTaskManager(ConfigManager configManager)
    {
        this.configManager = configManager;
    }

    public void loadForCurrentProfile()
    {
        hiddenTasks.clear();
        String saved = configManager.getRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY);
        if (saved != null && !saved.isEmpty())
        {
            for (String taskName : saved.split("\\|"))
            {
                String trimmed = taskName.trim();
                if (!trimmed.isEmpty())
                {
                    hiddenTasks.add(trimmed);
                }
            }
        }
        log.debug("Loaded {} hidden tasks for current profile", hiddenTasks.size());
    }

    public void onLogout()
    {
        hiddenTasks.clear();
    }

    private void save()
    {
        String joined = String.join("|", hiddenTasks);
        configManager.setRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY, joined);
    }

    public boolean isHidden(String taskName)
    {
        return hiddenTasks.contains(taskName);
    }

    public boolean isHidden(DemonicPactsTask task)
    {
        return hiddenTasks.contains(task.getName());
    }

    public void hide(String taskName)
    {
        if (hiddenTasks.add(taskName))
        {
            save();
            log.debug("Hid task: {}", taskName);
        }
    }

    public void unhide(String taskName)
    {
        if (hiddenTasks.remove(taskName))
        {
            save();
            log.debug("Unhid task: {}", taskName);
        }
    }

    public void clearAll()
    {
        hiddenTasks.clear();
        save();
        log.debug("Cleared all hidden tasks for current profile");
    }

    public Set<String> getHiddenTasks()
    {
        return Collections.unmodifiableSet(hiddenTasks);
    }

    public int getHiddenCount()
    {
        return hiddenTasks.size();
    }

    /**
     * Returns only tasks that are NOT hidden.
     */
    public List<DemonicPactsTask> filterVisible(List<DemonicPactsTask> tasks)
    {
        List<DemonicPactsTask> result = new ArrayList<>();
        for (DemonicPactsTask task : tasks)
        {
            if (!isHidden(task))
            {
                result.add(task);
            }
        }
        return result;
    }
}

package com.demonicpacts;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;

/**
 * Reads task completion status from the League Tasks panel (widget group 657).
 *
 * Strategy: walk the entire widget tree under group 657 recursively and collect
 * every widget whose text color matches the "completed" orange (0xF47113). This
 * is resilient to Jagex reshuffling child indexes between client updates — we
 * don't care where in the tree the row lives as long as the color is right and
 * the cleaned text matches a known task name in TaskDatabase.
 *
 * The panel inflates its rows asynchronously after opening, so we also re-sync
 * on every GameTick while the panel is visible to catch rows that weren't
 * present when the first WidgetLoaded fired.
 */
@Slf4j
@Singleton
public class LeagueTaskCompletionTracker
{
    private static final int TASK_LOG_GROUP_ID = 657;
    private static final int COLOR_COMPLETE = 0xF47113;

    private final Set<String> completedTaskNames = new HashSet<>();
    // Parallel lowercased set for O(1) case-insensitive isComplete lookups.
    // The original isComplete walked the whole set fuzzily on every check —
    // with 1,592 tasks queried per game tick that became the dominant cost
    // when the task panel was open.
    private final Set<String> completedTaskNamesLower = new HashSet<>();
    private final Set<String> newlySyncedSinceLastDrain = new HashSet<>();

    // Cheap fingerprint of the panel state from last sync. We skip the
    // (expensive) widget tree walk on ticks where the fingerprint hasn't
    // changed, which is the vast majority of ticks while the panel is open.
    private int lastPanelFingerprint = 0;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() != TASK_LOG_GROUP_ID)
        {
            return;
        }
        // Force a sync on the next client thread tick — initial open of the
        // panel is always interesting, regardless of fingerprint state.
        lastPanelFingerprint = 0;
        clientThread.invokeLater(this::syncFromTaskLog);
    }

    /**
     * Re-sync only when the panel has actually changed since the last walk.
     * The widget's dynamic children change when the player switches area
     * tabs, scrolls, or changes filters; we use the count of dynamic
     * children (combined with the root child count) as a cheap fingerprint
     * so we skip the expensive depth-first walk on ticks where nothing has
     * changed. Earlier this method ran the full walk every game tick while
     * the panel was open and that was the dominant cost.
     */
    @Subscribe
    public void onGameTick(net.runelite.api.events.GameTick event)
    {
        Widget root = client.getWidget(TASK_LOG_GROUP_ID, 0);
        if (root == null || root.isHidden())
        {
            return;
        }
        int fingerprint = computePanelFingerprint(root);
        if (fingerprint == lastPanelFingerprint)
        {
            return;
        }
        syncFromTaskLog();
    }

    /**
     * Cheap, top-level-only fingerprint of the task panel state. Counts
     * static + dynamic child arrays at the root rather than walking the
     * full subtree, so it's O(1) per tick. When the player scrolls,
     * switches tabs, or filters, dynamic-children counts shift and we
     * trigger a re-sync.
     */
    private static int computePanelFingerprint(Widget root)
    {
        int h = 17;
        Widget[] s = root.getStaticChildren();
        Widget[] d = root.getDynamicChildren();
        Widget[] n = root.getNestedChildren();
        h = h * 31 + (s == null ? 0 : s.length);
        h = h * 31 + (d == null ? 0 : d.length);
        h = h * 31 + (n == null ? 0 : n.length);
        return h;
    }

    /**
     * Walk the entire widget 657 tree and collect every widget whose text color
     * is the completed orange (0xF47113). Match the cleaned text against known
     * tasks; the widget text may be either the task name or its description
     * depending on which column we hit, so we try both lookup directions.
     */
    private void syncFromTaskLog()
    {
        Widget root = client.getWidget(TASK_LOG_GROUP_ID, 0);
        if (root == null)
        {
            return;
        }

        int before = completedTaskNames.size();

        Deque<Widget> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty())
        {
            Widget w = stack.pop();
            if (w == null)
            {
                continue;
            }

            if (w.getTextColor() == COLOR_COMPLETE)
            {
                String cleaned = cleanTaskName(w.getText());
                if (!cleaned.isEmpty())
                {
                    String matched = matchKnownTask(cleaned);
                    if (matched != null && completedTaskNames.add(matched))
                    {
                        completedTaskNamesLower.add(matched.toLowerCase());
                        newlySyncedSinceLastDrain.add(matched);
                    }
                }
            }

            pushChildren(stack, w.getStaticChildren());
            pushChildren(stack, w.getDynamicChildren());
            pushChildren(stack, w.getNestedChildren());
        }

        int added = completedTaskNames.size() - before;
        if (added > 0)
        {
            log.debug("Task log sync: +{} newly completed (total {})", added, completedTaskNames.size());
        }

        // Remember the fingerprint of the panel we just walked so we can skip
        // identical state on subsequent ticks.
        lastPanelFingerprint = computePanelFingerprint(root);
    }

    private static void pushChildren(Deque<Widget> stack, Widget[] children)
    {
        if (children == null)
        {
            return;
        }
        for (Widget child : children)
        {
            if (child != null)
            {
                stack.push(child);
            }
        }
    }

    /**
     * Resolve widget text (which may be either a task name or description) to
     * the canonical task name from TaskDatabase. Returns null if no match.
     *
     * Hot path: this runs for every "completed"-coloured widget in the task
     * panel on every game tick. We use O(1) hash-map lookups for the common
     * exact-name and exact-description cases, and only fall back to a linear
     * fuzzy contains scan when both exact lookups miss (which is rare in
     * practice — Jagex's widget text matches our task names directly).
     */
    private static String matchKnownTask(String widgetText)
    {
        String target = widgetText.trim();
        if (target.isEmpty())
        {
            return null;
        }
        String targetLower = target.toLowerCase();

        String matched = TaskDatabase.findCanonicalNameByLowerName(targetLower);
        if (matched != null)
        {
            return matched;
        }
        matched = TaskDatabase.findCanonicalNameByLowerDesc(targetLower);
        if (matched != null)
        {
            return matched;
        }

        // Fuzzy fallback for minor wording drift ("the"/"a" omissions etc.).
        // Only iterates ALL_TASKS once when both exact lookups have already
        // failed.
        for (DemonicPactsTask task : TaskDatabase.getAllTasks())
        {
            String nameLower = task.getName().toLowerCase();
            if (nameLower.length() < 4)
            {
                continue; // too short — high risk of false positives
            }
            if (targetLower.contains(nameLower) || nameLower.contains(targetLower))
            {
                return task.getName();
            }
        }

        return null;
    }

    /**
     * Strip HTML/colour tags, trim whitespace, and drop a trailing period so the
     * widget text matches what we have in TaskDatabase.
     */
    private static String cleanTaskName(String raw)
    {
        if (raw == null)
        {
            return "";
        }
        String s = raw.replaceAll("<[^>]*>", "").trim();
        if (s.endsWith("."))
        {
            s = s.substring(0, s.length() - 1).trim();
        }
        return s;
    }

    /**
     * Check if a task is completed. Both producer paths (widget sync and chat
     * parsing) store the canonical TaskDatabase name, and callers pass the
     * canonical name too, so an exact (case-insensitive) hash-set check is
     * sufficient. This is on the hot path — called once per task per game
     * tick from DemonicPactsPlugin#onGameTick.
     */
    public boolean isComplete(String taskName)
    {
        if (taskName == null)
        {
            return false;
        }
        String target = cleanTaskName(taskName);
        if (target.isEmpty())
        {
            return false;
        }
        if (completedTaskNames.contains(target))
        {
            return true;
        }
        return completedTaskNamesLower.contains(target.toLowerCase());
    }

    public Set<String> getCompleted()
    {
        return completedTaskNames;
    }

    public void addCompleted(String taskName)
    {
        if (taskName != null)
        {
            String cleaned = cleanTaskName(taskName);
            if (!cleaned.isEmpty())
            {
                if (completedTaskNames.add(cleaned))
                {
                    completedTaskNamesLower.add(cleaned.toLowerCase());
                }
            }
        }
    }

    public void clear()
    {
        completedTaskNames.clear();
        completedTaskNamesLower.clear();
        newlySyncedSinceLastDrain.clear();
        lastPanelFingerprint = 0;
    }

    public int getCompletedCount()
    {
        return completedTaskNames.size();
    }

    /**
     * Returns the set of tasks discovered via widget sync since the last call
     * and atomically clears the buffer. Used by the plugin to emit a single
     * "synced N tasks" chat message per batch without double-counting.
     */
    public Set<String> drainNewlySynced()
    {
        if (newlySyncedSinceLastDrain.isEmpty())
        {
            return java.util.Collections.emptySet();
        }
        Set<String> copy = new HashSet<>(newlySyncedSinceLastDrain);
        newlySyncedSinceLastDrain.clear();
        return copy;
    }
}

package com.demonicpacts;

import javax.inject.Singleton;
import java.util.HashSet;
import java.util.Set;

/**
 * Shared per-frame record of which entities each overlay actually drew a
 * highlight for. Lets the tooltip overlay suppress tooltips on entities that
 * the category / onePerType filters kept off-screen, so hovered tooltips stay
 * in sync with the visible highlights.
 *
 * Each overlay clears its own slice at the start of its render() and marks
 * what it actually drew. Overlays run on the EDT so locking isn't needed.
 */
@Singleton
public class RenderedHighlights
{
    // NPCs: tracked by the stable per-scene index.
    private final Set<Integer> renderedNpcIndices = new HashSet<>();
    // NPCs also tracked by lowercase name for fallback lookups in the tooltip.
    private final Set<String> renderedNpcNames = new HashSet<>();

    // World objects: "world_x:world_y:lowercase_object_name"
    private final Set<String> renderedObjectKeys = new HashSet<>();

    // Ground items: "world_x:world_y:lowercase_item_name"
    private final Set<String> renderedGroundKeys = new HashSet<>();

    // Inventory / bank / equipment items: "parent_widget_id:lowercase_item_name"
    private final Set<String> renderedItemKeys = new HashSet<>();

    public void clearNpcs()
    {
        renderedNpcIndices.clear();
        renderedNpcNames.clear();
    }

    public void markNpc(int npcIndex)
    {
        renderedNpcIndices.add(npcIndex);
    }

    public void markNpcName(String name)
    {
        if (name != null)
        {
            renderedNpcNames.add(name.toLowerCase());
        }
    }

    public boolean isNpcRendered(int npcIndex)
    {
        return renderedNpcIndices.contains(npcIndex);
    }

    public boolean isNpcRenderedByName(String name)
    {
        return name != null && renderedNpcNames.contains(name.toLowerCase());
    }

    public void clearObjects()
    {
        renderedObjectKeys.clear();
    }

    public void markObject(int worldX, int worldY, String objectName)
    {
        renderedObjectKeys.add(buildWorldKey(worldX, worldY, objectName));
    }

    public boolean isObjectRendered(int worldX, int worldY, String objectName)
    {
        return renderedObjectKeys.contains(buildWorldKey(worldX, worldY, objectName));
    }

    /**
     * Lenient check: is there a rendered object with this name within a small
     * tile radius of (worldX, worldY)? Covers cases where the menu entry's
     * scene coords and the gameObject's scene coords differ by a tile due to
     * multi-tile objects or orientation.
     */
    public boolean isObjectRenderedNear(int worldX, int worldY, String objectName, int radius)
    {
        if (objectName == null) return false;
        String lowerName = objectName.toLowerCase();
        for (int dx = -radius; dx <= radius; dx++)
        {
            for (int dy = -radius; dy <= radius; dy++)
            {
                if (renderedObjectKeys.contains(buildWorldKey(worldX + dx, worldY + dy, lowerName)))
                {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Softer check for tooltip usage: is any object with this name currently
     * rendered anywhere? Useful when the tooltip can't easily pinpoint the
     * hovered tile but the overlay decided to keep the whole category off.
     */
    public boolean isAnyObjectRendered(String objectName)
    {
        if (objectName == null) return false;
        String suffix = ":" + objectName.toLowerCase();
        for (String key : renderedObjectKeys)
        {
            if (key.endsWith(suffix))
            {
                return true;
            }
        }
        return false;
    }

    public void clearGround()
    {
        renderedGroundKeys.clear();
    }

    public void markGround(int worldX, int worldY, String itemName)
    {
        renderedGroundKeys.add(buildWorldKey(worldX, worldY, itemName));
    }

    public boolean isGroundRendered(int worldX, int worldY, String itemName)
    {
        return renderedGroundKeys.contains(buildWorldKey(worldX, worldY, itemName));
    }

    /** Lenient check within a tile radius — same rationale as isObjectRenderedNear. */
    public boolean isGroundRenderedNear(int worldX, int worldY, String itemName, int radius)
    {
        if (itemName == null) return false;
        String lowerName = itemName.toLowerCase();
        for (int dx = -radius; dx <= radius; dx++)
        {
            for (int dy = -radius; dy <= radius; dy++)
            {
                if (renderedGroundKeys.contains(buildWorldKey(worldX + dx, worldY + dy, lowerName)))
                {
                    return true;
                }
            }
        }
        return false;
    }

    public boolean isAnyGroundRendered(String itemName)
    {
        if (itemName == null) return false;
        String suffix = ":" + itemName.toLowerCase();
        for (String key : renderedGroundKeys)
        {
            if (key.endsWith(suffix))
            {
                return true;
            }
        }
        return false;
    }

    public void clearItems()
    {
        renderedItemKeys.clear();
    }

    public void markItem(int parentWidgetId, String itemName)
    {
        renderedItemKeys.add(parentWidgetId + ":" + itemName.toLowerCase());
    }

    public boolean isItemRendered(int parentWidgetId, String itemName)
    {
        return renderedItemKeys.contains(parentWidgetId + ":" + itemName.toLowerCase());
    }

    public boolean isAnyItemRendered(String itemName)
    {
        if (itemName == null) return false;
        String suffix = ":" + itemName.toLowerCase();
        for (String key : renderedItemKeys)
        {
            if (key.endsWith(suffix))
            {
                return true;
            }
        }
        return false;
    }

    private static String buildWorldKey(int worldX, int worldY, String name)
    {
        return worldX + ":" + worldY + ":" + (name == null ? "" : name.toLowerCase());
    }
}

