    // =========================================================================
    // Lookup map construction
    // =========================================================================

    private static void buildLookupMaps()
    {
        for (DemonicPactsTask task : ALL_TASKS)
        {
            // Populate widget-scanner lookup tables for every task (independent of
            // whether the task has match keywords).
            if (task.getName() != null)
            {
                CANONICAL_NAME_BY_LOWER_NAME.put(task.getName().toLowerCase(), task.getName());
            }
            if (task.getDescription() != null)
            {
                CANONICAL_NAME_BY_LOWER_DESC.put(task.getDescription().toLowerCase(), task.getName());
            }

            if (task.getMatchKeywords() == null) continue;

            Map<String, List<DemonicPactsTask>> targetMap;
            switch (task.getType())
            {
                case DEFEAT_NPC:
                    targetMap = NPC_TASKS;
                    break;
                case EQUIP_ITEM:
                case CRAFT_ITEM:
                case CATCH_ITEM:
                case COOK_ITEM:
                case MINE_ITEM:
                case CHOP_ITEM:
                case BURN_ITEM:
                case CLEAN_ITEM:
                    targetMap = ITEM_TASKS;
                    break;
                default:
                    // Put misc keyword-bearing tasks into both maps for broader matching
                    for (String kw : task.getMatchKeywords())
                    {
                        String key = kw.toLowerCase();
                        ITEM_TASKS.computeIfAbsent(key, k -> new ArrayList<>()).add(task);
                        NPC_TASKS.computeIfAbsent(key, k -> new ArrayList<>()).add(task);
                    }
                    continue;
            }

            for (String kw : task.getMatchKeywords())
            {
                String key = kw.toLowerCase();
                targetMap.computeIfAbsent(key, k -> new ArrayList<>()).add(task);
            }
        }

        // Build OBJECT_TASKS by mapping world object names to their corresponding tasks.
        // We include COOK/SMELT/etc. tasks here because the player may need to gather
        // the raw material from this object even if the only task referencing it is
        // a downstream one (e.g. "Cook 100 Sharks" implies "fish sharks here first").
        for (Map.Entry<String, String[]> entry : OBJECT_TO_TASK_KEYWORDS.entrySet())
        {
            String objectName = entry.getKey();
            for (String itemKeyword : entry.getValue())
            {
                List<DemonicPactsTask> tasks = ITEM_TASKS.get(itemKeyword.toLowerCase());
                if (tasks != null)
                {
                    OBJECT_TASKS.computeIfAbsent(objectName, k -> new ArrayList<>()).addAll(tasks);
                }
            }
        }

        // For spell / prayer / generic widget tasks named "Cast X" / "Activate
        // X" / "Use the X (prayer|spell)", derive the in-game widget name (X)
        // and add the task under that name in ITEM_TASKS. Lets the existing
        // tooltip + hide-task code handle hovers over spell and prayer widgets
        // without having to teach those code paths about TaskType.SPELL /
        // TaskType.PRAYER specifically.
        String[] verbPrefixes = {"cast ", "activate ", "use the ", "reactivate "};
        String[] suffixesToStrip = {" spell", " prayer"};
        for (DemonicPactsTask task : ALL_TASKS)
        {
            String name = task.getName();
            if (name == null) continue;
            String lower = name.toLowerCase();
            for (String prefix : verbPrefixes)
            {
                if (!lower.startsWith(prefix)) continue;
                String rest = name.substring(prefix.length()).trim();
                String restLower = rest.toLowerCase();
                for (String suffix : suffixesToStrip)
                {
                    if (restLower.endsWith(suffix))
                    {
                        rest = rest.substring(0, rest.length() - suffix.length()).trim();
                        restLower = rest.toLowerCase();
                    }
                }
                if (rest.isEmpty()) break;
                List<DemonicPactsTask> bucket = ITEM_TASKS.computeIfAbsent(restLower, k -> new ArrayList<>());
                // Avoid double-listing tasks that already keyword the derived
                // name (e.g. "Use the Piety Prayer" with explicit keyword
                // "Piety" — the standard buildLookupMaps loop has already
                // inserted the task under "piety", so the derive step would
                // duplicate it and the tooltip would render the same line
                // twice).
                if (!bucket.contains(task))
                {
                    bucket.add(task);
                }
                break;
            }
        }
    }

    // =========================================================================
    // Public API
    // =========================================================================

    public static List<DemonicPactsTask> getAllTasks()
    {
        return Collections.unmodifiableList(ALL_TASKS);
    }

    /**
     * Find tasks matching an NPC name (case-insensitive).
     */
    public static List<DemonicPactsTask> findNpcTasks(String npcName)
    {
        if (npcName == null) return Collections.emptyList();
        List<DemonicPactsTask> tasks = NPC_TASKS.get(npcName.toLowerCase());
        return tasks != null ? tasks : Collections.emptyList();
    }

    /**
     * Find tasks matching an item name (case-insensitive).
     */
    public static List<DemonicPactsTask> findItemTasks(String itemName)
    {
        if (itemName == null) return Collections.emptyList();
        if (ITEM_BLOCKLIST.contains(itemName.toLowerCase())) return Collections.emptyList();
        List<DemonicPactsTask> tasks = ITEM_TASKS.get(itemName.toLowerCase());
        return tasks != null ? tasks : Collections.emptyList();
    }

    /**
     * Check if any task matches this NPC name.
     */
    public static boolean isTaskNpc(String npcName)
    {
        return npcName != null && NPC_TASKS.containsKey(npcName.toLowerCase());
    }

    /**
     * Check if any task matches this item name.
     */
    public static boolean isTaskItem(String itemName)
    {
        return itemName != null && ITEM_TASKS.containsKey(itemName.toLowerCase());
    }

    /**
     * Find tasks matching a world object name (rocks, trees, patches, stalls,
     * statues, chests, etc.). Case-insensitive.
     *
     * Lookup order:
     *   1. OBJECT_TASKS — explicitly bridged via OBJECT_TO_TASK_KEYWORDS
     *      (e.g. "iron rocks" -> tasks that keyword "iron ore").
     *   2. ITEM_TASKS — many tasks keyword the in-world object directly
     *      ("Gem Stall", "Silver Stall", "Statue (Ates)", "Chest (moon key)").
     *      Without this fallback those tasks got tooltips on hover but no
     *      highlight, since the tooltip path checks ITEM_TASKS too while the
     *      object overlay only checked OBJECT_TASKS.
     *   3. NPC_TASKS — same idea for objects that share a name with an NPC
     *      task keyword (rare, but covers things like fishing-spot variants).
     *
     * The ITEM_BLOCKLIST is honoured so genuinely noisy ingredient items
     * (chisel, knife, ammo mould, vial of water) still don't produce
     * highlights when they happen to match a scenery name.
     */
    public static List<DemonicPactsTask> findObjectTasks(String objectName)
    {
        if (objectName == null) return Collections.emptyList();
        String key = objectName.toLowerCase();
        List<DemonicPactsTask> tasks = OBJECT_TASKS.get(key);
        if (tasks != null && !tasks.isEmpty()) return tasks;

        if (!ITEM_BLOCKLIST.contains(key))
        {
            tasks = ITEM_TASKS.get(key);
            if (tasks != null && !tasks.isEmpty()) return tasks;
        }

        tasks = NPC_TASKS.get(key);
        if (tasks != null && !tasks.isEmpty()) return tasks;

        return Collections.emptyList();
    }

    /**
     * Check if any task matches this world object name. Mirrors the same
     * three-map lookup order as findObjectTasks so the menu-injection code
     * doesn't disagree with the highlight code about which objects are
     * task-relevant.
     */
    public static boolean isTaskObject(String objectName)
    {
        if (objectName == null) return false;
        String key = objectName.toLowerCase();
        if (OBJECT_TASKS.containsKey(key)) return true;
        if (!ITEM_BLOCKLIST.contains(key) && ITEM_TASKS.containsKey(key)) return true;
        return NPC_TASKS.containsKey(key);
    }

    /**
     * Get tasks filtered by difficulty.
     */
    public static List<DemonicPactsTask> getTasksByDifficulty(TaskDifficulty difficulty)
    {
        return ALL_TASKS.stream()
            .filter(t -> t.getDifficulty() == difficulty)
            .collect(Collectors.toList());
    }

    /**
     * Get tasks filtered by area.
     */
    public static List<DemonicPactsTask> getTasksByArea(String area)
    {
        return ALL_TASKS.stream()
            .filter(t -> t.getArea().equalsIgnoreCase(area))
            .collect(Collectors.toList());
    }

    /**
     * O(1) lookup of canonical task name by lowercased name (used by the
     * league-task widget scanner). Returns null if no exact match.
     */
    public static String findCanonicalNameByLowerName(String lowerName)
    {
        return lowerName == null ? null : CANONICAL_NAME_BY_LOWER_NAME.get(lowerName);
    }

    /**
     * O(1) lookup of canonical task name by lowercased description (some
     * widget columns render the task description rather than the name).
     */
    public static String findCanonicalNameByLowerDesc(String lowerDesc)
    {
        return lowerDesc == null ? null : CANONICAL_NAME_BY_LOWER_DESC.get(lowerDesc);
    }
}

