    // PROFIT / LOSS SECTION

    private void buildProfitLossSection(JPanel container, SpellData spell)
    {
        JLabel plHeader = new JLabel("Profit / Loss");
        plHeader.setFont(detailBoldFont());
        plHeader.setForeground(TEXT_HIGHLIGHT);
        plHeader.setAlignmentX(Component.LEFT_ALIGNMENT);
        container.add(plHeader);
        container.add(Box.createVerticalStrut(ELEMENT_GAP));

        if (spell.getName().equals("High Level Alchemy") || spell.getName().equals("Low Level Alchemy"))
        {
            buildAlchProfitSection(container, spell);
        }
        else
        {
            buildGenericConversionSection(container, spell);
        }
    }

    private void buildAlchProfitSection(JPanel container, SpellData spell)
    {
        boolean isHighAlch = spell.getName().equals("High Level Alchemy");

        JLabel hint = new JLabel("Search for an item to alch:");
        hint.setFont(detailFont());
        hint.setForeground(TEXT_MUTED);
        hint.setAlignmentX(Component.LEFT_ALIGNMENT);
        container.add(hint);
        container.add(Box.createVerticalStrut(ELEMENT_GAP));

        JTextField alchSearchField = new JTextField();
        alchSearchField.setBackground(PANEL);
        alchSearchField.setForeground(TEXT_PRIMARY);
        alchSearchField.setCaretColor(TEXT_PRIMARY);
        alchSearchField.setFont(inputFont());
        alchSearchField.setBorder(inputBorder());
        alchSearchField.setMaximumSize(new Dimension(Integer.MAX_VALUE, INPUT_HEIGHT));
        alchSearchField.setAlignmentX(Component.LEFT_ALIGNMENT);
        container.add(alchSearchField);
        container.add(Box.createVerticalStrut(ELEMENT_GAP));

        JPanel resultsPanel = new JPanel();
        resultsPanel.setLayout(new BoxLayout(resultsPanel, BoxLayout.Y_AXIS));
        resultsPanel.setBackground(PANEL_EXPANDED);
        resultsPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        container.add(resultsPanel);

        Timer debounceTimer = new Timer(400, null);
        debounceTimer.setRepeats(false);

        alchSearchField.addKeyListener(new KeyAdapter()
        {
            @Override
            public void keyReleased(KeyEvent e)
            {
                debounceTimer.stop();
                debounceTimer.addActionListener(evt ->
                {
                    String query = alchSearchField.getText().trim();
                    if (query.length() < 2)
                    {
                        resultsPanel.removeAll();
                        resultsPanel.revalidate();
                        resultsPanel.repaint();
                        return;
                    }
                    searchAndDisplayAlchItems(query, resultsPanel, isHighAlch);
                });
                debounceTimer.restart();
            }
        });
    }

    private void searchAndDisplayAlchItems(String query, JPanel resultsPanel, boolean isHighAlch)
    {
        resultsPanel.removeAll();

        clientThread.invokeLater(() ->
        {
            final java.util.List<ItemSearchRow> rows = new java.util.ArrayList<>();
            try
            {
                itemManager.search(query).stream().limit(8).forEach(result ->
                {
                    int itemId = result.getId();
                    try
                    {
                        ItemComposition comp = itemManager.getItemComposition(itemId);
                        calculator.cacheItemPrice(itemId);
                        int alchValue = isHighAlch ? comp.getHaPrice() : comp.getPrice();
                        rows.add(new ItemSearchRow(itemId, comp.getName(), alchValue));
                    }
                    catch (Exception ignored) {}
                });
            }
            catch (Exception ignored) {}

            SwingUtilities.invokeLater(() -> renderAlchResults(rows, resultsPanel, isHighAlch));
        });
    }

    private static class ItemSearchRow
    {
        final int itemId;
        final String name;
        final int alchValue;
        ItemSearchRow(int itemId, String name, int alchValue)
        {
            this.itemId = itemId;
            this.name = name;
            this.alchValue = alchValue;
        }
    }

    private void renderAlchResults(java.util.List<ItemSearchRow> rows, JPanel resultsPanel, boolean isHighAlch)
    {
        resultsPanel.removeAll();
        boolean useGear = config.useEquippedGear();
        SpellData alchSpell = SpellDatabase.getAllSpells().stream()
            .filter(s -> s.getName().equals(isHighAlch ? "High Level Alchemy" : "Low Level Alchemy"))
            .findFirst().orElse(null);
        long runeCost = alchSpell != null ? calculator.calculateCastCost(alchSpell, useGear) : 0;

        for (ItemSearchRow r : rows)
        {
            int gePrice = calculator.getItemPrice(r.itemId);
            long profit = r.alchValue - gePrice - runeCost;

            String details = "GE: " + formatGp(gePrice) + " - " +
                (isHighAlch ? "HA" : "LA") + ": " + formatGp(r.alchValue) +
                " - Runes: " + formatGp(runeCost);

            JPanel row = buildCardRow(
                r.name, details, TEXT_MUTED,
                (profit >= 0 ? "+" : "") + formatGp(profit) + " gp",
                profit >= 0 ? PROFIT : LOSS
            );

            resultsPanel.add(row);
            resultsPanel.add(Box.createVerticalStrut(ROW_GAP));
        }

        resultsPanel.revalidate();
        resultsPanel.repaint();
    }

    private void buildGenericConversionSection(JPanel container, SpellData spell)
    {
        java.util.List<ConversionPreset> presets = ConversionPreset.getPresetsForSpell(spell.getName());

        if (presets != null && !presets.isEmpty())
        {
            for (ConversionPreset preset : presets)
            {
                addPresetResult(container, spell, preset);
            }
        }
        else
        {
            JLabel noPresets = new JLabel("No preset conversions for this spell");
            noPresets.setFont(detailFont());
            noPresets.setForeground(TEXT_MUTED);
            noPresets.setAlignmentX(Component.LEFT_ALIGNMENT);
            container.add(noPresets);
        }
    }

    private void addPresetResult(JPanel container, SpellData spell, ConversionPreset preset)
    {
        CostCalculator.PresetResult result = calculator.calculatePresetProfit(spell, preset, config.useEquippedGear());

        // The card itself — a vertical stack of table rows
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBackground(PANEL);
        card.setBorder(rowBorder());
        card.setMaximumSize(new Dimension(Integer.MAX_VALUE, Short.MAX_VALUE));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);

        // Header row: shows what this conversion produces
        if (result.isXpOnly)
        {
            JLabel header = new JLabel("Cast cost breakdown");
            header.setFont(detailBoldFont());
            header.setForeground(TEXT_PRIMARY);
            header.setAlignmentX(Component.LEFT_ALIGNMENT);
            card.add(header);
        }
        else
        {
            JPanel header = buildNameQtyLabel(preset.getOutputName(), preset.getOutputQty(), PANEL, true);
            card.add(header);
        }
        card.add(Box.createVerticalStrut(ELEMENT_GAP));

        // Input rows
        for (ConversionPreset.ItemInput input : preset.getInputs())
        {
            long itemPrice = (long) calculator.getItemPrice(input.getItemId()) * input.getQuantity();
            JLabel itemIcon = buildItemIconLabel(input.getItemId());
            addItemLineItem(card, itemIcon, input.getName(), input.getQuantity(), formatGp(itemPrice) + " gp", TEXT_MUTED);
        }

        // Runes row (no icon since runes are aggregated across types)
        addLineItem(card, null, "Runes", formatGp(result.runeCost) + " gp", TEXT_MUTED);

        // Optional fee row (Plank Make charges an NPC fee)
        if (result.extraFee > 0)
        {
            addLineItem(card, null, "Fee", formatGp(result.extraFee) + " gp", TEXT_MUTED);
        }

        // Divider
        card.add(Box.createVerticalStrut(2));
        JSeparator divider = new JSeparator();
        divider.setForeground(BORDER);
        divider.setBackground(BORDER);
        divider.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
        divider.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.add(divider);
        card.add(Box.createVerticalStrut(ELEMENT_GAP));

        if (result.isXpOnly)
        {
            // XP-only conversions (Reanimate spells): show total cost
            addLineItem(card, null, "Total cost", formatGp(result.totalCost()) + " gp", TEXT_HIGHLIGHT);
        }
        else
        {
            // Output value (with output item icon)
            JLabel outputIcon = buildItemIconLabel(preset.getOutputItemId());
            addItemLineItem(card, outputIcon, preset.getOutputName(), preset.getOutputQty(), formatGp(result.outputValue) + " gp", TEXT_PRIMARY);

            // Profit row — colored green or red, no icon
            card.add(Box.createVerticalStrut(2));
            String profitText = (result.profit >= 0 ? "+" : "") + formatGp(result.profit) + " gp";
            Color profitColor = result.profit >= 0 ? PROFIT : LOSS;
            addLineItem(card, null, "Profit", profitText, profitColor);
        }

        container.add(card);
        container.add(Box.createVerticalStrut(ROW_GAP));
    }

    /**
     * Adds a single line item to a card: optional icon on the left, label in middle,
     * value on the right. Pass null for the icon if no image is needed.
     */
    private void addLineItem(JPanel card, JLabel icon, String label, String value, Color valueColor)
    {
        JPanel row = new JPanel(new BorderLayout(INLINE_GAP, 0));
        row.setBackground(card.getBackground());
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Short.MAX_VALUE));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);

        // Icon column — always reserve space so labels align across all rows
        JPanel iconCol = new JPanel(new BorderLayout());
        iconCol.setBackground(card.getBackground());
        iconCol.setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
        if (icon != null)
        {
            iconCol.add(icon, BorderLayout.CENTER);
            forwardMouseEventsToParent(icon);
        }
        row.add(iconCol, BorderLayout.WEST);

        JLabel labelComp = new JLabel(label);
        labelComp.setFont(detailFont());
        labelComp.setForeground(TEXT_MUTED);
        configureTruncation(labelComp, label);
        forwardMouseEventsToParent(labelComp);
        row.add(labelComp, BorderLayout.CENTER);

        JLabel valueComp = new JLabel(value);
        valueComp.setFont(detailFont());
        valueComp.setForeground(valueColor);
        valueComp.setHorizontalAlignment(SwingConstants.RIGHT);
        configureTruncation(valueComp, value);
        forwardMouseEventsToParent(valueComp);
        row.add(valueComp, BorderLayout.EAST);

        card.add(row);
    }

    /**
     * Adds a named item line to a card: [icon] Name x[qty]  [value] — name in
     * white, the "x[qty]" suffix muted, matching the rune breakdown style.
     */
    private void addItemLineItem(JPanel card, JLabel icon, String name, int quantity, String value, Color valueColor)
    {
        JPanel row = new JPanel(new BorderLayout(INLINE_GAP, 0));
        row.setBackground(card.getBackground());
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Short.MAX_VALUE));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel iconCol = new JPanel(new BorderLayout());
        iconCol.setBackground(card.getBackground());
        iconCol.setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
        if (icon != null)
        {
            iconCol.add(icon, BorderLayout.CENTER);
            forwardMouseEventsToParent(icon);
        }
        row.add(iconCol, BorderLayout.WEST);

        JPanel nameQty = buildNameQtyLabel(name, quantity, card.getBackground(), false);
        row.add(nameQty, BorderLayout.CENTER);

        JLabel valueComp = new JLabel(value);
        valueComp.setFont(detailFont());
        valueComp.setForeground(valueColor);
        valueComp.setHorizontalAlignment(SwingConstants.RIGHT);
        configureTruncation(valueComp, value);
        forwardMouseEventsToParent(valueComp);
        row.add(valueComp, BorderLayout.EAST);

        card.add(row);
    }

    /**
     * Builds a 24x24 JLabel for an item icon. Loads asynchronously via
     * ItemManager and shows the image when ready. Returns a blank label if
     * the item ID is invalid (negative).
     */
    private JLabel buildItemIconLabel(int itemId)
    {
        JLabel label = new JLabel();
        label.setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
        label.setMinimumSize(new Dimension(ICON_SIZE, ICON_SIZE));
        label.setMaximumSize(new Dimension(ICON_SIZE, ICON_SIZE));
        label.setHorizontalAlignment(SwingConstants.CENTER);
        label.setVerticalAlignment(SwingConstants.CENTER);

        if (itemId < 0) return label;

        try
        {
            AsyncBufferedImage asyncImg = itemManager.getImage(itemId);
            // Scale to ICON_SIZE after load — addTo() sets native size which clips.
            asyncImg.onLoaded(() ->
            {
                Image scaled = asyncImg.getScaledInstance(ICON_SIZE, ICON_SIZE, Image.SCALE_SMOOTH);
                SwingUtilities.invokeLater(() -> label.setIcon(new ImageIcon(scaled)));
            });
        }
        catch (Exception ignored) {}

        return label;
    }

    // UTILITIES

    public void updatePrices()
    {
        if (!initialized) return;
        rebuildGearEffects();
        refreshSpellList();
    }

    private long safeCost(SpellData spell, boolean useGear)
    {
        try
        {
            return calculator.calculateCastCost(spell, useGear);
        }
        catch (Exception ex)
        {
            return Long.MAX_VALUE;
        }
    }

    /**
     * Returns the highest profit value across all conversion presets for a P&L
     * spell, used for sort-by-profit. Returns Long.MIN_VALUE for spells with no
     * presets (so they sort to the bottom). Skips XP-only conversions like
     * Reanimate spells, since those don't have a meaningful "profit" value.
     *
     * Note: For High/Low Alchemy, this returns 0 since alch profit depends on
     * which item the user searches — there's no fixed best-case to sort by.
     */
    private long bestProfit(SpellData spell, boolean useGear)
    {
        if (!spell.hasProfitLoss()) return Long.MIN_VALUE;

        // Alch spells have no fixed presets; treat profit as 0 for sorting purposes
        if (spell.getName().equals("High Level Alchemy") || spell.getName().equals("Low Level Alchemy"))
        {
            return 0;
        }

        java.util.List<ConversionPreset> presets = ConversionPreset.getPresetsForSpell(spell.getName());
        if (presets == null || presets.isEmpty()) return Long.MIN_VALUE;

        long best = Long.MIN_VALUE;
        for (ConversionPreset preset : presets)
        {
            try
            {
                CostCalculator.PresetResult result = calculator.calculatePresetProfit(spell, preset, useGear);
                if (result.isXpOnly) continue; // Reanimation etc. have no profit value
                if (result.profit > best) best = result.profit;
            }
            catch (Exception ignored) {}
        }
        return best;
    }

    private static String formatGp(long amount)
    {
        if (Math.abs(amount) >= 10_000_000)
        {
            return String.format("%.1fM", amount / 1_000_000.0);
        }
        else if (Math.abs(amount) >= 100_000)
        {
            return String.format("%.0fK", amount / 1_000.0);
        }
        else if (Math.abs(amount) >= 10_000)
        {
            return String.format("%.1fK", amount / 1_000.0);
        }
        return String.format("%,d", amount);
    }

    private void styleComboBox(JComboBox<?> combo)
    {
        combo.setBackground(PANEL);
        combo.setForeground(TEXT_PRIMARY);
        combo.setFont(dropdownFont());
        combo.setBorder(new javax.swing.border.MatteBorder(1, 1, 1, 1, BORDER));
    }
}

package com.castcalc;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

@Slf4j
@PluginDescriptor(
    name = "Cast Calc",
    description = "Calculate the GP cost of every spell cast with live GE prices, rune-saving gear detection, and profit/loss for utility spells.",
    tags = {"magic", "runes", "cost", "calculator", "alchemy", "high alch", "tan leather", "profit", "ge"}
)
public class CastCalcPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private CastCalcConfig config;

    @Inject
    private ItemManager itemManager;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private SpriteManager spriteManager;

    private CostCalculator calculator;
    private CastCalcPanel panel;
    private NavigationButton navButton;
    private ScheduledFuture<?> priceRefreshTask;

    @Override
    protected void startUp()
    {
        calculator = new CostCalculator(client, itemManager);
        panel = new CastCalcPanel(client, config, calculator, itemManager, clientThread, spriteManager);

        BufferedImage icon;
        try
        {
            icon = ImageUtil.loadImageResource(getClass(), "cast_calc_icon.png");
        }
        catch (Exception e)
        {
            log.debug("Icon not found, using blank placeholder");
            icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        }

        navButton = NavigationButton.builder()
            .tooltip("Cast Calc")
            .icon(icon)
            .priority(8)
            .panel(panel)
            .build();

        clientToolbar.addNavigation(navButton);

        // Warm up the price cache on the client thread, THEN initialize the panel.
        // clientThread.invokeLater will queue until the client thread is alive.
        clientThread.invokeLater(() ->
        {
            try
            {
                calculator.refreshPriceCache();
                RuneSavingGear.updateCache(client);
                // Push current Magic level if already logged in when plugin starts
                if (client.getGameState() == GameState.LOGGED_IN)
                {
                    int magicLevel = client.getRealSkillLevel(Skill.MAGIC);
                    SwingUtilities.invokeLater(() -> panel.setCurrentMagicLevel(magicLevel));
                }
            }
            catch (Exception e)
            {
                log.warn("Failed initial cache warmup", e);
            }
            SwingUtilities.invokeLater(() ->
            {
                panel.initialize();
                panel.updatePrices();
            });
        });

        // Periodic price refresh — runs on client thread, then updates UI
        priceRefreshTask = executor.scheduleAtFixedRate(
            () -> clientThread.invokeLater(() ->
            {
                try
                {
                    calculator.refreshPriceCache();
                    RuneSavingGear.updateCache(client);
                }
                catch (Exception e)
                {
                    log.debug("Periodic price refresh failed", e);
                }
                SwingUtilities.invokeLater(() -> panel.updatePrices());
            }),
            5, 5, TimeUnit.MINUTES
        );

        log.info("Cast Calc started");
    }

    @Override
    protected void shutDown()
    {
        clientToolbar.removeNavigation(navButton);

        if (priceRefreshTask != null)
        {
            priceRefreshTask.cancel(true);
            priceRefreshTask = null;
        }

        log.info("Cast Calc stopped");
    }

    @Provides
    CastCalcConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(CastCalcConfig.class);
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (event.getSkill() == Skill.MAGIC)
        {
            int level = client.getRealSkillLevel(Skill.MAGIC);
            SwingUtilities.invokeLater(() -> panel.setCurrentMagicLevel(level));
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == net.runelite.api.InventoryID.EQUIPMENT.getId())
        {
            RuneSavingGear.updateCache(client);
            SwingUtilities.invokeLater(() -> panel.updatePrices());
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            calculator.refreshPriceCache();
            RuneSavingGear.updateCache(client);
            int level = client.getRealSkillLevel(Skill.MAGIC);
            SwingUtilities.invokeLater(() ->
            {
                panel.setCurrentMagicLevel(level);
                panel.updatePrices();
            });
        }
    }
}

package com.castcalc;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.border.Border;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.Color;
import java.awt.Font;

/**
 * Centralized style configuration for the Cast Calc panel.
 *
 * Think of this like a CSS file or design tokens. When you change a value here,
 * the change propagates everywhere that uses it.
 *
 * Organized by section:
 *   - COLORS        : color tokens
 *   - TYPOGRAPHY    : font sizes and font factories
 *   - SPACING       : padding and gap values
 *   - LAYOUT        : fixed widths, column reservations
 *   - COMPONENTS    : pre-built borders and helpers
 *
 */
public final class CastCalcStyle
{
    private CastCalcStyle() {} // utility class, no instances

    // COLORS

    public static final Color BACKGROUND       = ColorScheme.DARK_GRAY_COLOR;
    public static final Color PANEL            = ColorScheme.DARKER_GRAY_COLOR;
    public static final Color PANEL_HOVER      = ColorScheme.DARKER_GRAY_HOVER_COLOR;
    public static final Color PANEL_EXPANDED   = ColorScheme.DARKER_GRAY_HOVER_COLOR;
    public static final Color BORDER           = ColorScheme.MEDIUM_GRAY_COLOR;

    public static final Color TEXT_PRIMARY     = Color.WHITE;
    public static final Color TEXT_MUTED       = ColorScheme.LIGHT_GRAY_COLOR;
    public static final Color TEXT_HIGHLIGHT   = ColorScheme.TEXT_COLOR;
    public static final Color TEXT_PROFIT_TAG  = ColorScheme.TEXT_COLOR; // for P&L subtitle

    public static final Color PROFIT           = ColorScheme.GRAND_EXCHANGE_PRICE;
    public static final Color LOSS             = ColorScheme.GRAND_EXCHANGE_ALCH;
    public static final Color COST_PL          = ColorScheme.GRAND_EXCHANGE_PRICE;

    // TYPOGRAPHY

    /** Used for the panel title ("Cast Calc"). */
    public static final int TITLE_SIZE         = 16;

    /** Used for section headers (selected spell name, "Profit / Loss Calculator"). */
    public static final int SECTION_SIZE       = 14;

    /** Used for everything else: rows, subtitles, labels, dropdowns. */
    public static final int BASE_SIZE          = 14;

    /** Used for dropdown menus and combo boxes. Defaults to BASE_SIZE. */
    public static final int DROPDOWN_FONT_SIZE = 16;

    /** Used for text inputs (search fields). Defaults to BASE_SIZE. */
    public static final int INPUT_FONT_SIZE    = 14;

    /** Expanded-card detail text size when the "Small" setting is active (default). */
    public static final int DETAIL_SIZE_SMALL  = 14;

    /** Expanded-card detail text size when the "Large" setting is active. */
    public static final int DETAIL_SIZE_LARGE  = 16;

    public static Font titleFont()
    {
        return FontManager.getRunescapeBoldFont().deriveFont((float) TITLE_SIZE);
    }

    public static Font sectionFont()
    {
        return FontManager.getRunescapeBoldFont().deriveFont((float) SECTION_SIZE);
    }

    public static Font baseFont()
    {
        return FontManager.getRunescapeFont().deriveFont((float) BASE_SIZE);
    }

    public static Font boldFont()
    {
        return FontManager.getRunescapeBoldFont().deriveFont((float) BASE_SIZE);
    }

    public static Font baseFont(int size)
    {
        return FontManager.getRunescapeFont().deriveFont((float) size);
    }

    public static Font boldFont(int size)
    {
        return FontManager.getRunescapeBoldFont().deriveFont((float) size);
    }

    public static Font dropdownFont()
    {
        return FontManager.getRunescapeFont().deriveFont((float) DROPDOWN_FONT_SIZE);
    }

    public static Font inputFont()
    {
        return FontManager.getRunescapeFont().deriveFont((float) INPUT_FONT_SIZE);
    }

    /**
     * Produces an HTML-wrapped string that JLabel will word-wrap, with
     * the base font size baked in (setFont() alone doesn't size HTML content).
     */
    public static String wrapText(String text, int widthPx, boolean bold)
    {
        String weight = bold ? "bold" : "normal";
        return "<html><body style='width:" + widthPx + "px; font-size:" + BASE_SIZE
            + "pt; font-weight:" + weight + "'>" + escapeHtml(text) + "</body></html>";
    }

    private static String escapeHtml(String s)
    {
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    // SPACING

    /** Padding inside each spell row. */
    public static final int ROW_PADDING_VERTICAL   = 8;
    public static final int ROW_PADDING_HORIZONTAL = 10;

    /** Padding inside the outer panel. */
    public static final int PANEL_PADDING          = 8;

    /** Gap between stacked rows. */
    public static final int ROW_GAP                = 2;

    /** Gap between major sections (header → list, list → detail). */
    public static final int SECTION_GAP            = 8;

    /** Gap between related elements within a section. */
    public static final int ELEMENT_GAP            = 4;

    /** Horizontal gap between adjacent inline elements (dropdown columns, label + value). */
    public static final int INLINE_GAP             = 6;

    /** Gap between a row icon and its text labels. */
    public static final int ICON_TEXT_GAP          = 4;

    /** Vertical padding for empty-state and loading messages. */
    public static final int EMPTY_STATE_PADDING    = 12;

    // LAYOUT

    /** Height of text input fields (search, alch search). */
    public static final int INPUT_HEIGHT           = 32;

    /** Height of dropdown rows (spellbook filter, category filter, sort). */
    public static final int DROPDOWN_HEIGHT        = 28;

    /** Size of icons throughout the panel (spell list rows, P&L table inputs/outputs), in pixels. */
    public static final int ICON_SIZE              = 20;

    /**
     * Width reserved for the cost/profit column on the right side of rows.
     * Needs to fit strings like "+1,234 gp" at current font size.
     */
    public static final int COST_COLUMN_WIDTH      = 110;

    /**
     * Width of the wrapping text column in the main spell list.
     * Panel is ~225px wide, minus padding, minus COST_COLUMN_WIDTH.
     */
    public static final int SPELL_ROW_TEXT_WIDTH   = 90;

    /**
     * Width of wrapping text in preset rows (inside the P&L section).
     */
    public static final int PRESET_ROW_TEXT_WIDTH  = 90;

    /**
     * Width of wrapping text in alch search result rows (has item icon on left).
     */
    public static final int ALCH_ROW_TEXT_WIDTH    = 85;

    // COMPONENTS

    /** Standard border for a card-style row: 1px outline + inner padding. */
    public static Border rowBorder()
    {
        return new CompoundBorder(
            new MatteBorder(1, 1, 1, 1, BORDER),
            new EmptyBorder(ROW_PADDING_VERTICAL, ROW_PADDING_HORIZONTAL,
                            ROW_PADDING_VERTICAL, ROW_PADDING_HORIZONTAL)
        );
    }

    /** Lighter border for the gear effects panel at the top. */
    public static Border headerChipBorder()
    {
        return new CompoundBorder(
            new MatteBorder(1, 1, 1, 1, BORDER),
            new EmptyBorder(4, 6, 4, 6)
        );
    }

    /** Padding for text input fields (search, etc.). */
    public static Border inputBorder()
    {
        return new CompoundBorder(
            new MatteBorder(1, 1, 1, 1, BORDER),
            new EmptyBorder(6, 8, 6, 8)
        );
    }
}

package com.castcalc;

import net.runelite.api.ItemID;

import java.util.*;

/**
 * Pre-built conversion presets for P&L-eligible spells.
 * Each preset maps a spell name to its possible input→output conversions.
 * Supports multi-input conversions (e.g., Superheat steel = iron ore + 2 coal).
 */
public class ConversionPreset
{
    private final String label;
    private final List<ItemInput> inputs;
    private final int outputItemId;
    private final String outputName;
    private final int outputQty;
    private final int extraGpCost;

    public ConversionPreset(String label, int outputItemId, String outputName,
                            int outputQty, int extraGpCost, ItemInput... inputs)
    {
        this.label = label;
        this.outputItemId = outputItemId;
        this.outputName = outputName;
        this.outputQty = outputQty;
        this.extraGpCost = extraGpCost;
        this.inputs = Arrays.asList(inputs);
    }

    public String getLabel()
    {
        return label;
    }

    public List<ItemInput> getInputs()
    {
        return inputs;
    }

    public int getOutputItemId()
    {
        return outputItemId;
    }

    public String getOutputName()
    {
        return outputName;
    }

    public int getOutputQty()
    {
        return outputQty;
    }

    public int getExtraGpCost()
    {
        return extraGpCost;
    }

    public static class ItemInput
    {
        private final int itemId;
        private final String name;
        private final int quantity;

        public ItemInput(int itemId, String name, int quantity)
        {
            this.itemId = itemId;
            this.name = name;
            this.quantity = quantity;
        }

        public int getItemId()
        {
            return itemId;
        }

        public String getName()
        {
            return name;
        }

        public int getQuantity()
        {
            return quantity;
        }
    }

    private static ItemInput input(int itemId, String name, int qty)
    {
        return new ItemInput(itemId, name, qty);
    }

    private static final Map<String, List<ConversionPreset>> PRESETS = new LinkedHashMap<>();

    static
