/**
 * Controls whether the tracker and planner value patches by Grand Exchange profit or by
 * Farming experience.
 */
public enum DisplayMode
{
	/**
	 * Pick automatically: Farming XP for ironman accounts (who can't sell on the GE),
	 * GE profit for everyone else.
	 */
	AUTO("Auto (detect account type)"),
	/**
	 * Always show Grand Exchange profit.
	 */
	PROFIT("Grand Exchange profit"),
	/**
	 * Always show Farming experience.
	 */
	XP("Farming experience");

	private final String label;

	DisplayMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

