		final JMenuItem copyDebugLog = new JMenuItem("Copy debug log");
		copyDebugLog.addActionListener(e -> copyDebugLogToClipboard());
		final JPopupMenu popupMenu = new JPopupMenu();
		popupMenu.setBorder(new EmptyBorder(5, 5, 5, 5));
