	@ConfigItem(
		position = 4,
		keyName = "thirtyLineColor",
		name = "30 line color",
		description = "Color of the line separating 30 from 31 wilderness",
		section = levelLines
	)
	@Alpha
	default Color thirtyLineColor()
	{
		return Color.CYAN;
	}
