			dialogOptionOptions.getChildren() != null &&
			dialogOptionOptions.getChildren().length > 0 &&
			dialogOptionOptions.getChildren()[0].getText().contains("Take tea?")) {
			dialogOptionOptions.getChildren()[0].setText("Take coffee?");
