	{
		final String text = Text.sanitizeMultilineText(rawText).toLowerCase();

		for (Map.Entry<String, String> entry : charlieTaskToClueText.entrySet())
		{
			if (text.contains(entry.getKey().toLowerCase()))
			{
				return entry.getValue();
			}
		}

		return null;
	}

