@Data
public class ClueInstanceData
{
	private List<Integer> clueIds;
	private int itemId;
	private int despawnTick;
	private int x;
	private int y;
	private int plane;

	public ClueInstanceData(ClueInstance clue)
	{
		this.clueIds = clue.getClueIds();
		this.itemId = clue.getItemId();
