package com.cluedetails;

import static com.cluedetails.ClueDetailsConfig.CLUE_ITEMS_CONFIG;
import static com.cluedetails.ClueDetailsConfig.CLUE_WIDGETS_CONFIG;

import com.google.gson.reflect.TypeToken;
import java.util.List;
import java.util.stream.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class CluePreferenceManager
{
	private final ClueDetailsPlugin clueDetailsPlugin;
	private final ConfigManager configManager;

	@Inject
	public CluePreferenceManager(ClueDetailsPlugin clueDetailsPlugin, ConfigManager configManager)
	{
		this.clueDetailsPlugin = clueDetailsPlugin;
		this.configManager = configManager;
	}

	public boolean getHighlightPreference(int clueID)
	{
		return Boolean.TRUE.equals(configManager.getConfiguration("clue-details-highlights",
			String.valueOf(clueID), Boolean.class));
	}

	public void saveHighlightPreference(int clueID, boolean newValue)
	{
		configManager.setConfiguration("clue-details-highlights", String.valueOf(clueID), newValue);
	}

	public boolean itemsPreferenceContainsItem(int clueID, int itemID)
	{
		List<Integer> clueItemIds = getItemsPreference(clueID);

		if (clueItemIds != null)
		{
			return getItemsPreference(clueID).contains(itemID);
		}
		return false;
	}

	public List<Integer> getItemsPreference(int clueID)
	{
		String clueItems = configManager.getConfiguration(CLUE_ITEMS_CONFIG, String.valueOf(clueID));

		return clueDetailsPlugin.gson.fromJson(clueItems, new TypeToken<List<Integer>>(){}.getType());
	}

	public void saveItemsPreference(int clueID, List<Integer> newItems)
	{
		if (newItems.isEmpty())
		{
			configManager.unsetConfiguration(CLUE_ITEMS_CONFIG, String.valueOf(clueID));
		}
		else
		{
			String clueItemIdsJson = clueDetailsPlugin.gson.toJson(newItems);
			configManager.setConfiguration(CLUE_ITEMS_CONFIG, String.valueOf(clueID), clueItemIdsJson);
		}
	}

	public boolean widgetsPreferenceContainsWidget(int clueID, WidgetId widgetId)
	{
		List<WidgetId> clueWidgetIds = getWidgetsPreference(clueID);

		if (clueWidgetIds != null)
		{
			return clueWidgetIds.contains(widgetId);
		}
		return false;
	}

	public List<WidgetId> getWidgetsPreference(int clueID)
	{
		String clueWidgets = configManager.getConfiguration(CLUE_WIDGETS_CONFIG, String.valueOf(clueID));

		return clueDetailsPlugin.gson.fromJson(clueWidgets, new TypeToken<List<WidgetId>>(){}.getType());
	}

	public void saveWidgetsPreference(int clueID, List<WidgetId> newWidgets)
	{
		if (newWidgets.isEmpty())
		{
			configManager.unsetConfiguration(CLUE_WIDGETS_CONFIG, String.valueOf(clueID));
		}
		else
		{
			List<WidgetId> mappedWidgetIds = newWidgets
				.stream()
				.map(w -> new WidgetId(w.getComponentId(), w.getChildIndex() == null || w.getChildIndex() == -1 ? null : w.getChildIndex()))
				.collect(Collectors.toList());
			String clueWidgetIdsJson = clueDetailsPlugin.gson.toJson(mappedWidgetIds);
			configManager.setConfiguration(CLUE_WIDGETS_CONFIG, String.valueOf(clueID), clueWidgetIdsJson);
		}
	}
}

package com.cluedetails;

import com.google.gson.Gson;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemID;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.config.ConfigManager;
import javax.inject.Inject;

@Slf4j
@Singleton
public class ClueThreeStepSaver
{
	@Inject
	private Client client;

	@Inject
	private ClueDetailsConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private ClueInventoryManager cim;

	private ClueInstance activeMaster;

	@Getter
	private ClueInstance savedThreeStepper;

	private boolean removeEntries = false;

	private static final String THREE_STEP_MASTER_KEY = "three-step-master";

	public void scanInventory()
	{
		if (!config.threeStepperSaver()) return;

		activeMaster = cim.getClueByClueItemId(ItemID.CLUE_SCROLL_MASTER);
		if(activeMaster == null || savedThreeStepper == null)
		{
			removeEntries = false;
			return;
		}

		//removes entries if we don't know what clue is in their inv, can be made a toggle.
		removeEntries = cluesMatch() || activeMaster.getClueIds().isEmpty();
	}

	public boolean cluesMatch()
	{
		if (activeMaster == null || savedThreeStepper == null) return false;
		else return activeMaster.getClueIds().equals(savedThreeStepper.getClueIds());
	}

	public void onMenuOpened(MenuOpened event)
	{
		if (!client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		if (!config.threeStepperSaver()) return;
		if (activeMaster == null) return;

		MenuEntry firstEntry = event.getFirstEntry();
		//only menus generated from a clue in inventory pass this widget check.
		if (activeMaster.getClueIds().size() == 3 && firstEntry.getWidget() != null && firstEntry.getTarget().contains("Clue scroll (master)"))
		{
			MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
			if (cluesMatch())
			{
				client.getMenu().createMenuEntry(-menuEntries.length)
					.setOption("Unset three-stepper")
					.setTarget(event.getFirstEntry().getTarget())
					.setType(MenuAction.RUNELITE)
					.onClick(e -> removeThreeStepper());
			}
			else
			{
				client.getMenu().createMenuEntry(-menuEntries.length)
					.setOption("Set three-stepper")
					.setTarget(event.getFirstEntry().getTarget())
					.setType(MenuAction.RUNELITE)
					.onClick(e -> saveThreeStepper());
			}
		}
	}

	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.threeStepperSaver()) return;

		MenuEntry menuEntry = event.getMenuEntry();
		if (menuEntry.getTarget().contains("Torn clue scroll") && removeEntries)
		{
			if (menuEntry.getOption().contains("Use") || menuEntry.getOption().contains("Combine"))
			{
				client.getMenu().removeMenuEntry(menuEntry);
			}
		}
	}

	public void saveThreeStepper()
	{
		String clueInstanceJson = gson.toJson(activeMaster);
		configManager.setConfiguration(ClueDetailsConfig.GROUP, THREE_STEP_MASTER_KEY, clueInstanceJson);
		client.addChatMessage(ChatMessageType.GAMEMESSAGE,"","Successfully set clue as your three-stepper.","");
		updateThreeStepper();
		scanInventory();
	}

	public void removeThreeStepper()
	{
		configManager.setConfiguration(ClueDetailsConfig.GROUP, THREE_STEP_MASTER_KEY, "");
		client.addChatMessage(ChatMessageType.GAMEMESSAGE,"","Successfully unset clue as your three-stepper.","");
		updateThreeStepper();
		scanInventory();
	}

	public void updateThreeStepper()
	{
		String threeStepMasterJson = configManager.getConfiguration(ClueDetailsConfig.GROUP, THREE_STEP_MASTER_KEY);
		if (threeStepMasterJson == null) return;
		savedThreeStepper = gson.fromJson(threeStepMasterJson, ClueInstance.class);
	}

	public void startUp()
	{
		updateThreeStepper();
		scanInventory();
	}
}

package com.cluedetails;

import javax.inject.Singleton;
import net.runelite.api.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import javax.inject.Inject;
import java.awt.Graphics2D;

import static com.cluedetails.ClueDetailsConfig.SavedThreeStepperEnum.BOTH;
import static com.cluedetails.ClueDetailsConfig.SavedThreeStepperEnum.INVENTORY;

@Singleton
public class ClueThreeStepSaverWidgetOverlay extends WidgetItemOverlay
{
	private final ClueDetailsPlugin clueDetailsPlugin;
	private final ClueDetailsConfig config;

	private final ClueThreeStepSaver clueThreeStepSaver;

	@Inject
	private ClueThreeStepSaverWidgetOverlay(ClueDetailsPlugin clueDetailsPlugin, ClueThreeStepSaver clueThreeStepSaver, ClueDetailsConfig config)
	{
		this.clueDetailsPlugin = clueDetailsPlugin;
		this.clueThreeStepSaver = clueThreeStepSaver;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (itemId != ItemID.CLUE_SCROLL_MASTER || !clueThreeStepSaver.cluesMatch())
		{
			return;
		}

		if (config.threeStepperSaver() && (config.highlightSavedThreeStepper() == BOTH || config.highlightSavedThreeStepper() == INVENTORY))
		{
			clueDetailsPlugin.getItemsOverlay().inventoryTagsOverlay(graphics, itemId, widgetItem, config.invThreeStepperHighlightColor());
		}
	}
}

