@Slf4j
@PluginDescriptor(
		name = "Orb Clickthrough",
		description = "Makes selected minimap orb buttons click-through with a configurable hotkey.",
		tags = {"orbs", "orb", "minimap", "clickthrough", "hotkey"}
)
public class OrbClickthroughPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "orbclickthrough";

	// Expected menu entries generated by minimap orb widgets.
	// Menu entries are usually split into option + target, e.g. "Activate" + "Quick-prayers".
	private static final Set<String> HEALTH_MENU_OPTIONS = Set.of(
			"cure"
	);

	private static final Set<String> PRAYER_MENU_OPTIONS = Set.of(
			"activate",
			"deactivate"
	);

	private static final Set<String> PRAYER_MENU_TARGETS = Set.of(
			"quick-prayers"
	);

	private static final Set<String> RUN_MENU_OPTIONS = Set.of(
			"toggle run"
	);

	private static final Set<String> SPECIAL_ATTACK_MENU_OPTIONS = Set.of(
			"use"
	);

	private static final Set<String> SPECIAL_ATTACK_MENU_TARGETS = Set.of(
			"special attack"
	);

	private static final Set<String> WORLD_MAP_MENU_OPTIONS = Set.of(
			"floating world map",
			"fullscreen world map",
			"minimise minimap"
	);

	private static final Set<String> XP_MENU_OPTIONS = Set.of(
			"setup",
			"hide",
			"show"
	);

	private static final Set<String> XP_MENU_TARGETS = Set.of(
			"xp drops"
	);

	private static final Set<String> ACTIVITY_MENU_OPTIONS = Set.of(
			"open activity adviser",
			"close activity adviser"
	);

	private static final Set<String> WIKI_MENU_OPTIONS = Set.of(
			"lookup",
			"search",
			"dps"
	);

	private static final Set<String> WIKI_MENU_TARGETS = Set.of(
			"wiki"
	);

	private static final Set<String> STORE_MENU_OPTIONS = Set.of(
			"open store",
			"bond pouch"
	);

	private static final Set<String> COMPASS_MENU_OPTIONS = Set.of(
			"look north",
			"look east",
			"look south",
			"look west"
	);

	private static final Set<String> LOGOUT_MENU_OPTIONS = Set.of(
			"logout",
			"world switcher"
	);

	// Minimap orb widget component IDs
	private static final int ACTIVITY_BUTTON = InterfaceID.Orbs.CR_BUTTON;
	private static final int ACTIVITY_BACKING = InterfaceID.Orbs.CR_BACKING;

	private static final int XP_DROPS = InterfaceID.Orbs.XP_DROPS;

	private static final int HEALTH_BUTTON = InterfaceID.Orbs.HEALTHBUTTON;
	private static final int HEALTH_BACKING = InterfaceID.Orbs.HEALTH_BACKING;

	private static final int PRAYER_BUTTON = InterfaceID.Orbs.PRAYERBUTTON;
	private static final int PRAYER_BACKING = InterfaceID.Orbs.PRAYER_BACKING;

	private static final int RUN_BUTTON = InterfaceID.Orbs.RUNBUTTON;
	private static final int RUNENERGY_BACKING = InterfaceID.Orbs.RUNENERGY_BACKING;

	private static final int SPEC_BUTTON = InterfaceID.Orbs.SPECBUTTON;
	private static final int SPECENERGY_BACKING = InterfaceID.Orbs.SPECENERGY_BACKING;

	private static final int STORE_BUTTON = InterfaceID.Orbs.STORE_BUTTON;
	private static final int STORE_BACKING = InterfaceID.Orbs.STORE_BACKING;

	private static final int WORLDMAP = InterfaceID.Orbs.WORLDMAP;
	private static final int WORLDMAP_BACKING = InterfaceID.Orbs.WORLDMAP_BACKING;
	private static final int WORLDMAP_TOOLTIP = InterfaceID.Orbs.TOOLTIP;

	// Base game wiki orb
	private static final int WIKI_ICON = InterfaceID.Orbs.WIKI_ICON;

	// Wiki orb parent container.
	// Used to target the orb created by Wiki plugin, a dynamic replacement child.
	private static final int WIKI_CONTAINER = InterfaceID.Orbs.WIKI;

	// Compass/logout widgets.
	private static final int MODERN_COMPASS_CLICK = InterfaceID.ToplevelPreEoc.COMPASSCLICK;
	private static final int CLASSIC_COMPASS_CLICK = InterfaceID.ToplevelOsrsStretch.COMPASSCLICK;
	private static final int COMPASS_NOCLICK_CHILD_INDEX = 0;
	private static final int COMPASS_ACTION_CHILD_INDEX = 1;

	private static final int LOGOUT_STONE = InterfaceID.ToplevelPreEoc.STONE10;

	// Radar noclick regions that cover the world map/wiki/logout/radar orb areas.
	// Resizable Modern
	private static final int MODERN_MAP_NOCLICK_0 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_0; // Radar/logout
	private static final int MODERN_MAP_NOCLICK_1 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_1;
	private static final int MODERN_MAP_NOCLICK_2 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_2;
	private static final int MODERN_MAP_NOCLICK_3 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_3;
	private static final int MODERN_MAP_NOCLICK_4 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_4;
	private static final int MODERN_MAP_NOCLICK_5 = InterfaceID.ToplevelPreEoc.MAP_NOCLICK_5;

	// Resizable Classic
	private static final int CLASSIC_MAP_NOCLICK_0 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_0; // Radar/logout
	private static final int CLASSIC_MAP_NOCLICK_1 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_1;
	private static final int CLASSIC_MAP_NOCLICK_2 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_2;
	private static final int CLASSIC_MAP_NOCLICK_3 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_3;
	private static final int CLASSIC_MAP_NOCLICK_4 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_4;
	private static final int CLASSIC_MAP_NOCLICK_5 = InterfaceID.ToplevelOsrsStretch.MAP_NOCLICK_5;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private KeyManager keyManager;

	@Inject
	private OrbClickthroughConfig config;

	@Inject
	private OrbWidgetTransformer widgetTransformer;

	private HotkeyListener hotkeyListener;

	private boolean hotkeyHeld;
	private boolean toggleActive;

	private boolean noClickRegionsSynced;
	private boolean noClickRegionsSyncedForResizedMode;
	private boolean orbWidgetsApplied;

	@Override
	protected void startUp()
	{
		log.debug("Orb Clickthrough started");

		hotkeyListener = new HotkeyListener(() -> config.hotkey())
		{
			@Override
			public void hotkeyPressed()
			{
				if (config.activationMode() == OrbClickthroughActivationMode.TOGGLE_CLICK_THROUGH)
				{
					toggleActive = !toggleActive;
				}
				else
				{
					hotkeyHeld = true;
				}

				clientThread.invokeLater(OrbClickthroughPlugin.this::syncState);
			}

			@Override
			public void hotkeyReleased()
			{
				if (config.activationMode() != OrbClickthroughActivationMode.TOGGLE_CLICK_THROUGH)
				{
					hotkeyHeld = false;
					clientThread.invokeLater(OrbClickthroughPlugin.this::syncState);
				}
			}
		};

		keyManager.registerKeyListener(hotkeyListener);
		markNoClickRegionsDirty();
		clientThread.invokeLater(this::syncState);
	}

	@Override
	protected void shutDown()
	{
		if (hotkeyListener != null)
		{
			keyManager.unregisterKeyListener(hotkeyListener);
			hotkeyListener = null;
		}

		clientThread.invokeLater(() ->
		{
			widgetTransformer.restoreEverythingChangedByUs();
			hotkeyHeld = false;
			toggleActive = false;
			orbWidgetsApplied = false;
			markNoClickRegionsDirty();
		});

		log.debug("Orb Clickthrough stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			widgetTransformer.restoreEverythingChangedByUs();
			hotkeyHeld = false;
			toggleActive = false;
			orbWidgetsApplied = false;
			markNoClickRegionsDirty();
			return;
		}

		markNoClickRegionsDirty();
		clientThread.invokeLater(this::syncState);
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		/*
		 * Widgets can be recreated after login, layout changes, or other plugin changes.
		 * Resync on widget loads instead of doing the same work every client tick.
		 */
		markNoClickRegionsDirty();

		if (orbWidgetsApplied)
		{
			widgetTransformer.restoreOrbWidgetsChangedByUs();
			orbWidgetsApplied = false;
		}

		clientThread.invokeLater(this::syncState);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		clientThread.invokeLater(() ->
		{
			widgetTransformer.restoreEverythingChangedByUs();
			hotkeyHeld = false;
			toggleActive = false;
			orbWidgetsApplied = false;
			markNoClickRegionsDirty();
			syncState();
		});
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		syncExtraNoClickRegionState();
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (!shouldApplyNow())
		{
			return;
		}

		MenuEntry[] entries = client.getMenu().getMenuEntries();

		MenuEntry[] filteredEntries = Arrays.stream(entries)
				.filter(entry -> !isBlockedOrbMenuEntry(entry))
				.toArray(MenuEntry[]::new);

		if (filteredEntries.length != entries.length)
		{
			client.getMenu().setMenuEntries(filteredEntries);
		}
	}

	private void syncState()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		// MAP_NOCLICK bounds are plugin-lifetime changes.
		// They are not tied to hotkey state or individual orb config options.
		syncNoClickRegions();

		boolean shouldApply = shouldApplyNow();

		if (shouldApply)
		{
			if (!orbWidgetsApplied)
			{
				applyConfiguredOrbChanges();
				orbWidgetsApplied = true;
			}
		}
		else if (orbWidgetsApplied)
		{
			widgetTransformer.restoreOrbWidgetsChangedByUs();
			orbWidgetsApplied = false;
		}
	}

	private void syncExtraNoClickRegionState()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		/*
		 * This is intentionally not a full per-tick noclick-region sync.
		 *
		 * The dynamic extra blocker must be maintained every tick because other plugins
		 * can hide/remove the minimap without firing a useful widget-load event.
		 * patchExtraNoClickRegion() already restores our duplicate when the source
		 * MAP_NOCLICK_0 widget is hidden, missing, or fixed-mode is active.
		 */
		widgetTransformer.patchExtraNoClickRegion(MODERN_MAP_NOCLICK_0);
		widgetTransformer.patchExtraNoClickRegion(CLASSIC_MAP_NOCLICK_0);
	}

	private boolean shouldApplyNow()
	{
		switch (config.activationMode())
		{
			case HOLD_TO_CLICK_THROUGH:
				return hotkeyHeld;
			case HOLD_TO_RESTORE_CLICKS:
				return !hotkeyHeld;
			case TOGGLE_CLICK_THROUGH:
				return toggleActive;
			default:
				return false;
		}
	}

	private void applyConfiguredOrbChanges()
	{
		if (config.hideWorldMapTooltip())
		{
			widgetTransformer.hideWidget(WORLDMAP_TOOLTIP);
		}

		if (config.manageHealthOrb())
		{
			widgetTransformer.allowClickThrough(HEALTH_BACKING);
		}

		if (config.managePrayerOrb())
		{
			widgetTransformer.allowClickThrough(PRAYER_BACKING);
		}

		if (config.manageRunOrb())
		{
			widgetTransformer.allowClickThrough(RUNENERGY_BACKING);
		}

		if (config.manageSpecialAttackOrb())
		{
			widgetTransformer.allowClickThrough(SPECENERGY_BACKING);
		}

		if (config.manageWorldMapOrb())
		{
			widgetTransformer.allowClickThrough(WORLDMAP_BACKING);
		}

		if (config.manageXpOrb())
		{
			widgetTransformer.allowClickThrough(XP_DROPS);
		}

		if (config.manageActivityOrb())
		{
			widgetTransformer.allowClickThrough(ACTIVITY_BACKING);
		}

		if (config.manageWikiOrb())
		{
			widgetTransformer.allowClickThrough(WIKI_ICON);

			Widget wikiContainer = client.getWidget(WIKI_CONTAINER);

			if (wikiContainer != null)
			{
				widgetTransformer.allowClickThrough(wikiContainer);

				// The Wiki plugin adds its replacement orb as a dynamic child of WIKI_CONTAINER.
				Widget[] dynamicChildren = wikiContainer.getDynamicChildren();

				if (dynamicChildren != null)
				{
					for (Widget child : dynamicChildren)
					{
						if (child == null)
						{
							continue;
						}

						widgetTransformer.allowClickThrough(child);
					}
				}
			}
		}

		if (config.manageStoreOrb())
		{
			widgetTransformer.allowClickThrough(STORE_BACKING);
		}

		if (config.manageCompassOrb())
		{
			Widget modernCompassClick = client.getWidget(MODERN_COMPASS_CLICK);

			if (modernCompassClick != null)
			{
				Widget compassNoClickChild = modernCompassClick.getChild(COMPASS_NOCLICK_CHILD_INDEX);

				if (compassNoClickChild != null)
				{
					widgetTransformer.allowClickThrough(compassNoClickChild);
				}

				Widget compassActionChild = modernCompassClick.getChild(COMPASS_ACTION_CHILD_INDEX);

				if (compassActionChild != null)
				{
					widgetTransformer.allowClickThrough(compassActionChild);
				}
			}

			Widget classicCompassClick = client.getWidget(CLASSIC_COMPASS_CLICK);

			if (classicCompassClick != null)
			{
				Widget compassNoClickChild = classicCompassClick.getChild(COMPASS_NOCLICK_CHILD_INDEX);

				if (compassNoClickChild != null)
				{
					widgetTransformer.allowClickThrough(compassNoClickChild);
				}

				Widget compassActionChild = classicCompassClick.getChild(COMPASS_ACTION_CHILD_INDEX);

				if (compassActionChild != null)
				{
					widgetTransformer.allowClickThrough(compassActionChild);
				}
			}
		}

		if (config.manageLogoutOrb())
		{
			widgetTransformer.allowClickThrough(LOGOUT_STONE);
		}
	}

	private void syncNoClickRegions()
	{
		boolean resized = client.isResized();

		if (noClickRegionsSynced && noClickRegionsSyncedForResizedMode == resized)
		{
			return;
		}

		noClickRegionsSyncedForResizedMode = resized;

		if (!resized)
		{
			widgetTransformer.restoreNoClickRegions(
					MODERN_MAP_NOCLICK_0,
					MODERN_MAP_NOCLICK_1,
					MODERN_MAP_NOCLICK_2,
					MODERN_MAP_NOCLICK_3,
					MODERN_MAP_NOCLICK_4,
					MODERN_MAP_NOCLICK_5,
					CLASSIC_MAP_NOCLICK_0,
					CLASSIC_MAP_NOCLICK_1,
					CLASSIC_MAP_NOCLICK_2,
					CLASSIC_MAP_NOCLICK_3,
					CLASSIC_MAP_NOCLICK_4,
					CLASSIC_MAP_NOCLICK_5
			);

			noClickRegionsSynced = true;
			return;
		}

		widgetTransformer.updateNoClickRegions(
				MODERN_MAP_NOCLICK_1,
				MODERN_MAP_NOCLICK_2,
				MODERN_MAP_NOCLICK_3,
				MODERN_MAP_NOCLICK_4,
				MODERN_MAP_NOCLICK_5,
				CLASSIC_MAP_NOCLICK_1,
				CLASSIC_MAP_NOCLICK_2,
				CLASSIC_MAP_NOCLICK_3,
				CLASSIC_MAP_NOCLICK_4,
				CLASSIC_MAP_NOCLICK_5
		);

		widgetTransformer.patchExtraNoClickRegion(MODERN_MAP_NOCLICK_0);
		widgetTransformer.patchExtraNoClickRegion(CLASSIC_MAP_NOCLICK_0);

		noClickRegionsSynced = true;
	}

	private void markNoClickRegionsDirty()
	{
		noClickRegionsSynced = false;
	}

	private boolean isBlockedOrbMenuEntry(MenuEntry entry)
	{
		String option = cleanMenuText(entry.getOption());
		String target = cleanMenuText(entry.getTarget());
		int widgetId = entry.getParam1();

		if (config.manageHealthOrb()
				&& isWidgetOrChildOfAny(widgetId, HEALTH_BUTTON, HEALTH_BACKING)
				&& HEALTH_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		if (config.managePrayerOrb()
				&& isWidgetOrChildOfAny(widgetId, PRAYER_BUTTON, PRAYER_BACKING)
				&& (PRAYER_MENU_OPTIONS.contains(option) || PRAYER_MENU_TARGETS.contains(target)))
		{
			return true;
		}

		if (config.manageRunOrb()
				&& isWidgetOrChildOfAny(widgetId, RUN_BUTTON, RUNENERGY_BACKING)
				&& RUN_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		if (config.manageSpecialAttackOrb()
				&& isWidgetOrChildOfAny(widgetId, SPEC_BUTTON, SPECENERGY_BACKING)
				&& (SPECIAL_ATTACK_MENU_OPTIONS.contains(option) || SPECIAL_ATTACK_MENU_TARGETS.contains(target)))
		{
			return true;
		}

		if (config.manageWorldMapOrb()
				&& isWidgetOrChildOfAny(widgetId, WORLDMAP, WORLDMAP_BACKING)
				&& WORLD_MAP_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		if (config.manageXpOrb()
				&& isWidgetOrChildOfAny(widgetId, XP_DROPS)
				&& (XP_MENU_OPTIONS.contains(option) || XP_MENU_TARGETS.contains(target)))
		{
			return true;
		}

		if (config.manageActivityOrb()
				&& isWidgetOrChildOfAny(widgetId, ACTIVITY_BUTTON, ACTIVITY_BACKING)
				&& ACTIVITY_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		if (config.manageWikiOrb()
				&& isWidgetOrChildOfAny(widgetId, WIKI_ICON, WIKI_CONTAINER)
				&& (WIKI_MENU_OPTIONS.contains(option) || WIKI_MENU_TARGETS.contains(target)))
		{
			return true;
		}

		if (config.manageStoreOrb()
				&& isWidgetOrChildOfAny(widgetId, STORE_BUTTON, STORE_BACKING)
				&& STORE_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		if (config.manageCompassOrb()
				&& isWidgetOrChildOfAny(widgetId, MODERN_COMPASS_CLICK, CLASSIC_COMPASS_CLICK)
				&& COMPASS_MENU_OPTIONS.contains(option))
		{
			return true;
		}

		return config.manageLogoutOrb()
				&& isWidgetOrChildOfAny(widgetId, LOGOUT_STONE)
				&& LOGOUT_MENU_OPTIONS.contains(option);
	}

	private boolean isWidgetOrChildOfAny(int widgetId, int... expectedWidgetIds)
	{
		Widget widget = client.getWidget(widgetId);

		while (widget != null)
		{
			for (int expectedWidgetId : expectedWidgetIds)
			{
				if (widget.getId() == expectedWidgetId)
				{
					return true;
				}
			}

			widget = widget.getParent();
		}

		return false;
	}

	private String cleanMenuText(String text)
	{
		if (text == null)
		{
			return "";
		}

		return Text.removeTags(text).trim().toLowerCase(Locale.ROOT);
	}

	@Provides
	OrbClickthroughConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OrbClickthroughConfig.class);
	}
}

package com.orbclickthrough;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

@Singleton
public class OrbWidgetTransformer
{
    // Small always-on trims so noclick regions do not overlap exposed orb edges.
    private static final int MAP_NOCLICK_1_SHRINK_LEFT = 4;
    private static final int MAP_NOCLICK_2_SHRINK_LEFT = 4;
    private static final int MAP_NOCLICK_4_SHRINK_LEFT = 6;

    private static final int MAP_NOCLICK_3_SHRINK_RIGHT = 20;
    private static final int MAP_NOCLICK_4_SHRINK_RIGHT = 33;
    private static final int MAP_NOCLICK_5_SHRINK_RIGHT = 40;

    private static final int MAP_NOCLICK_0_SHRINK_WIDTH = 37;
    private static final int MAP_NOCLICK_0_MOVE_LEFT = 11;
    private static final int MAP_NOCLICK_0_SHIFT_DOWN = 24;
    private static final int MAP_NOCLICK_0_HEIGHT = 24;

    // Extra dynamic blocker created by this plugin.
    // Needed because shrinking MAP_NOCLICK_0 exposes part of the minimap between the logout/radar widget areas.
    private static final int MAP_NOCLICK_EXTRA_MOVE_LEFT = 18;
    private static final int MAP_NOCLICK_EXTRA_MOVE_UP = 22;
    private static final int MAP_NOCLICK_EXTRA_EXTRA_WIDTH = -34;
    private static final int MAP_NOCLICK_EXTRA_HEIGHT = 23;

    private final Client client;

    private final Set<Integer> extraNoClickRegionPatched = new HashSet<>();
    private final Map<Integer, Widget> extraNoClickRegions = new HashMap<>();

    private final Set<Widget> hiddenByUs = Collections.newSetFromMap(new IdentityHashMap<>());
    private final Set<Widget> noClickThroughChangedByUs = Collections.newSetFromMap(new IdentityHashMap<>());
    private final Set<Widget> targetVerbChangedByUs = Collections.newSetFromMap(new IdentityHashMap<>());
    private final Set<Widget> actionsChangedByUs = Collections.newSetFromMap(new IdentityHashMap<>());
    private final Set<Integer> boundsChangedByUs = new HashSet<>();

    private final Map<Widget, Boolean> originalNoClickThrough = new IdentityHashMap<>();
    private final Map<Widget, String> originalTargetVerb = new IdentityHashMap<>();
    private final Map<Widget, String[]> originalActions = new IdentityHashMap<>();
    private final Map<Integer, WidgetBounds> originalBounds = new HashMap<>();

    @Inject
    public OrbWidgetTransformer(Client client)
    {
        this.client = client;
    }

    public void hideWidget(int widgetId)
    {
        hideWidget(client.getWidget(widgetId));
    }

    public void hideWidget(Widget widget)
    {
        if (widget == null || widget.isHidden())
        {
            return;
        }

        widget.setHidden(true);
        hiddenByUs.add(widget);
    }

    public void allowClickThrough(int widgetId)
    {
        allowClickThrough(client.getWidget(widgetId));
    }

    public void allowClickThrough(Widget widget)
    {
        if (widget == null)
        {
            return;
        }

        if (!noClickThroughChangedByUs.contains(widget))
        {
            originalNoClickThrough.put(widget, widget.getNoClickThrough());
        }

        widget.setNoClickThrough(false);
        noClickThroughChangedByUs.add(widget);
    }

    public void clearTargetVerb(int widgetId)
    {
        clearTargetVerb(client.getWidget(widgetId));
    }

    public void clearTargetVerb(Widget widget)
    {
        if (widget == null)
        {
            return;
        }

        if (!targetVerbChangedByUs.contains(widget))
        {
            originalTargetVerb.put(widget, widget.getTargetVerb());
        }

        widget.setTargetVerb("");
        targetVerbChangedByUs.add(widget);
    }

    public void clearActions(int widgetId)
    {
        clearActions(client.getWidget(widgetId));
    }

    public void clearActions(Widget widget)
    {
        if (widget == null)
        {
            return;
        }

        if (!actionsChangedByUs.contains(widget))
        {
            String[] actions = widget.getActions();
            originalActions.put(widget, actions == null ? null : Arrays.copyOf(actions, actions.length));
        }

        widget.clearActions();
        actionsChangedByUs.add(widget);
    }

    public void updateNoClickRegions(
            int modernMapNoClick1,
            int modernMapNoClick2,
            int modernMapNoClick3,
            int modernMapNoClick4,
            int modernMapNoClick5,
            int classicMapNoClick1,
            int classicMapNoClick2,
            int classicMapNoClick3,
            int classicMapNoClick4,
            int classicMapNoClick5
    )
    {
        shrinkFromLeft(modernMapNoClick1, MAP_NOCLICK_1_SHRINK_LEFT);
        shrinkFromLeft(modernMapNoClick2, MAP_NOCLICK_2_SHRINK_LEFT);
        shrinkFromRight(modernMapNoClick3, MAP_NOCLICK_3_SHRINK_RIGHT);
        shrinkFromLeftAndRight(modernMapNoClick4, MAP_NOCLICK_4_SHRINK_LEFT, MAP_NOCLICK_4_SHRINK_RIGHT);
        shrinkFromRight(modernMapNoClick5, MAP_NOCLICK_5_SHRINK_RIGHT);

        shrinkFromLeft(classicMapNoClick1, MAP_NOCLICK_1_SHRINK_LEFT);
        shrinkFromLeft(classicMapNoClick2, MAP_NOCLICK_2_SHRINK_LEFT);
        shrinkFromRight(classicMapNoClick3, MAP_NOCLICK_3_SHRINK_RIGHT);
        shrinkFromLeftAndRight(classicMapNoClick4, MAP_NOCLICK_4_SHRINK_LEFT, MAP_NOCLICK_4_SHRINK_RIGHT);
        shrinkFromRight(classicMapNoClick5, MAP_NOCLICK_5_SHRINK_RIGHT);
    }

    public void restoreNoClickRegions(
            int modernMapNoClick0,
            int modernMapNoClick1,
            int modernMapNoClick2,
            int modernMapNoClick3,
            int modernMapNoClick4,
            int modernMapNoClick5,
            int classicMapNoClick0,
            int classicMapNoClick1,
            int classicMapNoClick2,
            int classicMapNoClick3,
            int classicMapNoClick4,
            int classicMapNoClick5
    )
    {
        restoreExtraNoClickRegion(modernMapNoClick0);
        restoreWidgetBounds(modernMapNoClick1);
        restoreWidgetBounds(modernMapNoClick2);
        restoreWidgetBounds(modernMapNoClick3);
        restoreWidgetBounds(modernMapNoClick4);
        restoreWidgetBounds(modernMapNoClick5);

        restoreExtraNoClickRegion(classicMapNoClick0);
        restoreWidgetBounds(classicMapNoClick1);
        restoreWidgetBounds(classicMapNoClick2);
        restoreWidgetBounds(classicMapNoClick3);
        restoreWidgetBounds(classicMapNoClick4);
        restoreWidgetBounds(classicMapNoClick5);
    }

    /*
     * Shrinks the widget from the visual left edge:
     * - normal left-anchored widgets: move X right and reduce width
     * - right-anchored widgets: reduce width only
     *
     * This keeps the visual right edge roughly fixed.
     */
    private void shrinkFromLeft(int widgetId, int pixels)
    {
        Widget widget = client.getWidget(widgetId);

        if (widget == null)
        {
            return;
        }

        if (!boundsChangedByUs.contains(widgetId))
        {
            originalBounds.put(
                    widgetId,
                    new WidgetBounds(
                            widget.getOriginalX(),
                            widget.getOriginalY(),
                            widget.getOriginalWidth(),
                            widget.getOriginalHeight()
                    )
            );
        }

        WidgetBounds originalValue = originalBounds.get(widgetId);

        if (originalValue == null)
        {
            return;
        }

        if (widget.getXPositionMode() == 2)
        {
            widget.setOriginalX(originalValue.originalX);
        }
        else
        {
            widget.setOriginalX(originalValue.originalX + pixels);
        }

        widget.setOriginalWidth(Math.max(0, originalValue.originalWidth - pixels));
        widget.revalidate();

        boundsChangedByUs.add(widgetId);
    }

    /*
     * Shrinks the widget from the visual right edge:
     * - normal left-anchored widgets: reduce width only
     * - right-anchored widgets: move X right and reduce width
     *
     * This keeps the visual left edge roughly fixed.
     */
    private void shrinkFromRight(int widgetId, int pixels)
    {
        Widget widget = client.getWidget(widgetId);

        if (widget == null)
        {
            return;
        }

        if (!boundsChangedByUs.contains(widgetId))
        {
            originalBounds.put(
                    widgetId,
                    new WidgetBounds(
                            widget.getOriginalX(),
                            widget.getOriginalY(),
                            widget.getOriginalWidth(),
                            widget.getOriginalHeight()
                    )
            );
        }

        WidgetBounds originalValue = originalBounds.get(widgetId);

        if (originalValue == null)
        {
            return;
        }

        if (widget.getXPositionMode() == 2)
        {
            widget.setOriginalX(originalValue.originalX + pixels);
        }
        else
        {
            widget.setOriginalX(originalValue.originalX);
        }

        widget.setOriginalWidth(Math.max(0, originalValue.originalWidth - pixels));
        widget.revalidate();

        boundsChangedByUs.add(widgetId);
    }

    /*
     * Applies both edge trims from the same saved original bounds.
     */
    private void shrinkFromLeftAndRight(int widgetId, int shrinkLeftPixels, int shrinkRightPixels)
    {
        Widget widget = client.getWidget(widgetId);

        if (widget == null)
        {
            return;
        }

        if (!boundsChangedByUs.contains(widgetId))
        {
            originalBounds.put(
                    widgetId,
                    new WidgetBounds(
                            widget.getOriginalX(),
                            widget.getOriginalY(),
                            widget.getOriginalWidth(),
                            widget.getOriginalHeight()
                    )
            );
        }

        WidgetBounds originalValue = originalBounds.get(widgetId);

        if (originalValue == null)
        {
            return;
        }

        int newWidth = Math.max(0, originalValue.originalWidth - shrinkLeftPixels - shrinkRightPixels);

        if (widget.getXPositionMode() == 2)
        {
            // Right-anchored mode.
            widget.setOriginalX(originalValue.originalX + shrinkRightPixels);
        }
        else
        {
            // Normal left-anchored mode.
            widget.setOriginalX(originalValue.originalX + shrinkLeftPixels);
        }

        widget.setOriginalWidth(newWidth);
        widget.revalidate();

        boundsChangedByUs.add(widgetId);
    }

    public void patchExtraNoClickRegion(int mapNoClick0WidgetId)
    {
        if (!client.isResized())
        {
            restoreExtraNoClickRegion(mapNoClick0WidgetId);
            return;
        }

        Widget mapNoClick0 = client.getWidget(mapNoClick0WidgetId);

        if (mapNoClick0 == null || isHiddenOrAncestorHidden(mapNoClick0))
        {
            restoreExtraNoClickRegion(mapNoClick0WidgetId);
            return;
        }

        /*
         * This check must happen after the visibility/null check.
         * Other plugins can hide/remove the minimap after we already patched it.
         */
        if (extraNoClickRegionPatched.contains(mapNoClick0WidgetId))
        {
            return;
        }

        if (!boundsChangedByUs.contains(mapNoClick0WidgetId))
        {
            originalBounds.put(
                    mapNoClick0WidgetId,
                    new WidgetBounds(
                            mapNoClick0.getOriginalX(),
                            mapNoClick0.getOriginalY(),
                            mapNoClick0.getOriginalWidth(),
                            mapNoClick0.getOriginalHeight()
                    )
            );
        }

        WidgetBounds originalValue = originalBounds.get(mapNoClick0WidgetId);

        if (originalValue == null)
        {
            return;
        }

        if (mapNoClick0.getXPositionMode() == 2)
        {
            // Right-anchored mode:
            // larger OriginalX = visually left.
            mapNoClick0.setOriginalX(originalValue.originalX + MAP_NOCLICK_0_MOVE_LEFT);
        }
        else
        {
            // Normal left-anchored mode:
            // smaller OriginalX = visually left.
            mapNoClick0.setOriginalX(originalValue.originalX - MAP_NOCLICK_0_MOVE_LEFT);
        }

        mapNoClick0.setOriginalY(originalValue.originalY + MAP_NOCLICK_0_SHIFT_DOWN);
        mapNoClick0.setOriginalWidth(Math.max(0, originalValue.originalWidth - MAP_NOCLICK_0_SHRINK_WIDTH));
        mapNoClick0.setOriginalHeight(MAP_NOCLICK_0_HEIGHT);

        mapNoClick0.setHidden(false);
        mapNoClick0.setNoClickThrough(true);
        mapNoClick0.setNoScrollThrough(true);
        mapNoClick0.revalidate();

        boundsChangedByUs.add(mapNoClick0WidgetId);

        createExtraNoClickRegion(mapNoClick0WidgetId, mapNoClick0);
        extraNoClickRegionPatched.add(mapNoClick0WidgetId);
    }

    public void restoreExtraNoClickRegion(int mapNoClick0WidgetId)
    {
        restoreExtraNoClickRegionWidget(mapNoClick0WidgetId);
        restoreWidgetBounds(mapNoClick0WidgetId);
        extraNoClickRegionPatched.remove(mapNoClick0WidgetId);
    }

    private void createExtraNoClickRegion(int mapNoClick0WidgetId, Widget mapNoClick0)
    {
        Widget parent = mapNoClick0.getParent();

        if (parent == null)
        {
            restoreExtraNoClickRegion(mapNoClick0WidgetId);
            return;
        }

        Widget extra = extraNoClickRegions.get(mapNoClick0WidgetId);

        if (extra != null && extra.getParent() != parent)
        {
            extra.setHidden(true);
            extra.revalidate();
            extra = null;
        }

        if (extra == null)
        {
            extra = parent.createChild(-1, WidgetType.LAYER);
            extraNoClickRegions.put(mapNoClick0WidgetId, extra);
        }

        /*
         * This widget is a sibling of MAP_NOCLICK_0.
         * Sibling positioning is needed because child widgets
         * did not reliably block scene clicks.
         */
        extra.setXPositionMode(mapNoClick0.getXPositionMode());
        extra.setYPositionMode(mapNoClick0.getYPositionMode());
        extra.setWidthMode(mapNoClick0.getWidthMode());
        extra.setHeightMode(mapNoClick0.getHeightMode());

        if (extra.getXPositionMode() == 2)
        {
            // Right-anchored mode:
            // larger OriginalX = visually left.
            extra.setOriginalX(mapNoClick0.getOriginalX() + MAP_NOCLICK_EXTRA_MOVE_LEFT);
        }
        else
        {
            // Normal left-anchored mode:
            // smaller OriginalX = visually left.
            extra.setOriginalX(mapNoClick0.getOriginalX() - MAP_NOCLICK_EXTRA_MOVE_LEFT);
        }

        extra.setOriginalY(mapNoClick0.getOriginalY() - MAP_NOCLICK_EXTRA_MOVE_UP);
        extra.setOriginalWidth(Math.max(0, mapNoClick0.getOriginalWidth() + MAP_NOCLICK_EXTRA_EXTRA_WIDTH));
        extra.setOriginalHeight(MAP_NOCLICK_EXTRA_HEIGHT);

        extra.setHidden(false);
        extra.setNoClickThrough(true);
        extra.setNoScrollThrough(true);
        extra.setHasListener(false);
        extra.revalidate();
    }

    private void restoreExtraNoClickRegionWidget(int mapNoClick0WidgetId)
    {
        Widget extra = extraNoClickRegions.remove(mapNoClick0WidgetId);

        if (extra != null)
        {
            extra.setHidden(true);
            extra.revalidate();
        }
    }

    private boolean isHiddenOrAncestorHidden(Widget widget)
    {
        Widget current = widget;

        while (current != null)
        {
            if (current.isHidden())
            {
                return true;
            }

            current = current.getParent();
        }

        return false;
    }

    public void restoreEverythingChangedByUs()
    {
        for (Integer widgetId : new HashSet<>(extraNoClickRegions.keySet()))
        {
            restoreExtraNoClickRegionWidget(widgetId);
        }

        extraNoClickRegionPatched.clear();

        restoreOrbWidgetsChangedByUs();
        restoreWidgetBounds();
    }

    public void restoreOrbWidgetsChangedByUs()
    {
        restoreHiddenWidgets();
        restoreClickThroughWidgets();
        restoreTargetVerbs();
        restoreActions();
    }

    private void restoreHiddenWidgets()
    {
        for (Widget widget : new HashSet<>(hiddenByUs))
        {
            if (widget != null)
            {
                widget.setHidden(false);
            }

            hiddenByUs.remove(widget);
        }
    }

    private void restoreClickThroughWidgets()
    {
        for (Widget widget : new HashSet<>(noClickThroughChangedByUs))
        {
            Boolean originalValue = originalNoClickThrough.remove(widget);

            if (widget != null && originalValue != null)
            {
                widget.setNoClickThrough(originalValue);
            }

            noClickThroughChangedByUs.remove(widget);
        }
    }

    private void restoreWidgetBounds()
    {
        for (Integer widgetId : new HashSet<>(boundsChangedByUs))
        {
            restoreWidgetBounds(widgetId);
        }
    }

    private void restoreWidgetBounds(int widgetId)
    {
        Widget widget = client.getWidget(widgetId);
        WidgetBounds originalValue = originalBounds.remove(widgetId);

        if (widget != null && originalValue != null)
        {
            widget.setOriginalX(originalValue.originalX);
            widget.setOriginalY(originalValue.originalY);
            widget.setOriginalWidth(originalValue.originalWidth);
            widget.setOriginalHeight(originalValue.originalHeight);
            widget.revalidate();
        }

        boundsChangedByUs.remove(widgetId);
    }

    private void restoreTargetVerbs()
    {
        for (Widget widget : new HashSet<>(targetVerbChangedByUs))
        {
            String originalValue = originalTargetVerb.remove(widget);

            if (widget != null)
            {
                widget.setTargetVerb(originalValue);
            }

            targetVerbChangedByUs.remove(widget);
        }
    }

    private void restoreActions()
    {
        for (Widget widget : new HashSet<>(actionsChangedByUs))
        {
            String[] originalValue = originalActions.remove(widget);

            if (widget != null)
            {
                widget.clearActions();

                if (originalValue != null)
                {
                    for (int i = 0; i < originalValue.length; i++)
                    {
                        widget.setAction(i, originalValue[i]);
                    }
                }
            }

            actionsChangedByUs.remove(widget);
        }
    }

    private static final class WidgetBounds
    {
        private final int originalX;
        private final int originalY;
        private final int originalWidth;
        private final int originalHeight;

        private WidgetBounds(int originalX, int originalY, int originalWidth, int originalHeight)
        {
            this.originalX = originalX;
            this.originalY = originalY;
            this.originalWidth = originalWidth;
            this.originalHeight = originalHeight;
        }
    }
}

package com.orbclickthrough;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.client.config.Keybind;
import org.junit.Test;

public class OrbClickthroughTest
{
	@Test
	public void defaultConfigValuesAreExpected()
	{
		OrbClickthroughConfig config = new OrbClickthroughConfig() {};

		assertEquals(Keybind.SHIFT, config.hotkey());
		assertEquals(OrbClickthroughActivationMode.HOLD_TO_RESTORE_CLICKS, config.activationMode());

		assertTrue(config.manageHealthOrb());
		assertFalse(config.managePrayerOrb());
		assertFalse(config.manageRunOrb());
		assertFalse(config.manageSpecialAttackOrb());

		assertTrue(config.manageWorldMapOrb());
		assertTrue(config.manageXpOrb());
		assertTrue(config.manageActivityOrb());
		assertTrue(config.manageWikiOrb());
		assertTrue(config.manageStoreOrb());

		assertTrue(config.hideWorldMapTooltip());
	}
}

